COLLDATA("qenc","ur",[[19,"§احد\nدیکھیے: اسماےحسنی","",{}],[20,"§احسان\nقرآن مجیدمیں لفظ احسان کا استعمال متعددبارہوا ہے۔جس کا ترجمہ آپ نیک عمل،خیراوربھلائی سے بھی کرسکتے ہیں۔احسان کبھی دوسروں کے لیے ہوتا ہے اور کبھی خود اپنے لیے۔پہلی حالت میں کبھی احسان بغیرکسی بدلےکے اپنی جانب سے ہوتا ہے۔جیسےسورہ النحل میں ہے: ﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ﴾ [النحل: ۹۰] \"بے شک االلہ تعالیٰ عدل، احسان اور رشتہ داروں کو ان کے حقوق ادا کرنے کا حکم دیتا ہے\"۔\nاور اللہ تعالی کبھی کسی کے عوض میں احسان کا حکم فرماتا ہے: ﴿هَلۡ جَزَآءُ ٱلۡإِحۡسَٰنِ إِلَّا ٱلۡإِحۡسَٰنُ﴾ [الرحمن: ۶۰] \"احسان کا بدلہ سوائے احسان کے اور کیا ہوسکتا ہے\"۔\nاحسان خود اپنے لیے بھی کیا جاتا ہے۔اس کا مطلب یہ ہے کہ اللہ تعالی کی اطاعت اور عبادت کے کاموں کو پوری دل جمعی، توجہ اور پختگی سےادا کیا جاے۔ اس کا بیان ایک صحیح حدیث میں اس طرح آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الإِحْسَانُ: أَنْ تَعْبُدَ اللَّه کَأَنَّکَ تَرَاه؛ فَإِنْ لَمْ تَکُنْ تَرَاه فَإِنَّه يَرَاکَ». (صحیح البخاری:۵۰، صحیح مسلم: ۸) \"احسان یہ ہے کہ تم االلہ تعالیٰ کی عبادت اس طرح کرو کہ تم اس کو دیکھ رہے اور اس کا مشاہدہ کر رہےہو۔ اگر تمھارے اندر یہ کیفیت پیدا نہ ہوسکے تو اس کی عبادت یہ سمجھ کر کروکہ وہ تم کو دیکھ رہا ہے\"۔\nمطلب یہ ہے کہ االلہ اور بندے کا تعلق اس طرح پختہ ہوکہ دونوں ایک دوسرے کو محسوس کر رہے ہوں یا کم ازکم اتناتوضرور ہو کہ بندہ یہ محسوس کرے کہ االلہ تعالیٰ اس کو دیکھ رہا ہے۔اس کے ہر عمل کاعلم اس کو ہے۔بندے کےوہ سارے کام اس کے نامہٴ اعمال میں لکھے جارہے ہیں،جن کا انھیں ایک نہ ایک دن حساب دینا ہے۔ پہلی کیفیت کو مشاہدہ اور دوسری کو مراقبہ کہتے ہیں۔اب جو شخص احسان کے اس درجے میں زندگی گزارے گا، وہ دوسروں کے ساتھ بھلاکس طرح ظلم ونا انصافی کرسکتا ہے۔ اس لیے یہ کہنا غلط نہیں ہوگا کہ احسان کے اس درجےکو چھوڑنے کے سبب ہی سےلوگ آج ہر قسم کی برائیوں میں مبتلا ہوگئے ہیں۔","",{}],[21,"§احقاف\nاحقاف حقف کی جمع ہے۔جس کے معنیٰ ریت کے بڑے بڑے ٹیلےکےہیں۔قرآن کریم میں احقاف نام کی ایک سورہ ہے،جس میں ۳۵ آیتیں ہیں۔ اس سورہ کی اکیسویں آیت میں لفظ احقاف کا ذکر ہے: ﴿وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمࣲ‏﴾ [الأحقاف: ۲۱] \"اور عاد کے بھائی کو یاد کرو۔جب اس نے اپنی قوم کواحقاف میں ڈرايا۔یقیناً اس سے پہلے بھی ڈرانے والےگزرچکے ہیں، اس کے بعد بھی۔تم سوائے االلہ تعالیٰ کےکسی کی عبادت نہ کرو۔بےشک میں تم پر بڑے دن کے عذاب سے خوف کہا تاہوں\"۔\nیہاں احقاف سے مرادایک بہت بڑا صحرائی علاقہ ہے،جو سعودی عرب کے جنوب میں پایا جاتا ہے۔جس کو \"ربع خالی\" کہا جاتا ہے۔کبھی یہاں عاد نام کی ایک بڑی قوم آبادتھی۔جس کے کچھ آثار آج بھی حضر موت (یمن)میں پائے جاتے ہیں۔اس قوم کی جانب ہود علیہ السلام کو نبی بنا کر بھیجا گیا،مگر اس قوم نےان کی بات نہیں مانی۔قرآن کے مطابق اسی وجہ سےایک بہت خوفناک طوفانی ہوا کے ذریعے انھیں ہلاک کردیا گیا: ﴿وَفِي عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ ٱلرِّيحَ ٱلۡعَقِيمَ مَا تَذَرُ مِن شَيۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِيمِ﴾ [الذاریات: ۴۱-۴۲] \"اور عاد(کے قصے) میں بھی(ہماری طرف سے تنبیہ ہے)جب کہ ہم نے ان پر خیروبرکت سے خالی آندھی بھیجی،وہ جس چیز سےگزرتی تھی اسے بوسیدہ ہڈی کی طرح (چورچور) کردیتی تھی\"۔\nانھی کے بارےمیں ایک اور جگہ قرآن میں آیا ہے: ﴿كَذَّبَتۡ عَادࣱ فَكَيۡفَ كَانَ عَذَابِي وَنُذُرِ إِنَّآ أَرۡسَلۡنَا عَلَيۡهِمۡ رِيحࣰ ا صَرۡصَرࣰ ا فِي يَوۡمِ نَحۡسࣲ مُّسۡتَمِرࣲّ تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلࣲ مُّنقَعِرࣲ‏﴾ [القمر: ۱۸-۲۰] \"قوم عاد نے بھی جھٹلایا تو کیساہوا میرا عذاب اورمیری ڈرانے والی باتیں۔ہم نے ان پر تیز وتند مسلسل چلنے والی ہوا ایک پیہم منحوس دن میں بھیج دی۔جو لوگوں کو اٹھا اٹھاکر دے پٹختی تھی۔ گویاوہ جڑسے کٹے ہوے کھجور کے تنے ہیں\"۔\nقرآن میں یہ بھی مذکورہے کہ یہ ہولناک عذاب سات راتیں اور اٹھ دن ہوتا رہا جس کی وجہ سےسب کچھ برباد ہوگیا: ﴿فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةࣲ‏﴾ [الحاقة: ۸] \"تو کیا ان میں سے کوئی بھی تمھیں باقی دکھائی دے رہا ہے\"۔\nخلاصہ یہ کہ سورہ احقاف میں االلہ تعالیٰ کی نا فرمانی کرنے والوں کے انجام کا بیان ہے۔ مثال کے طور پرقوم عاد کا ذکر کیا گیا ہے،جو اپنے زمانے میں ایک مضبوط قوم تھی، لیکن وہ االلہ کے احکام کے نہ ماننے کی وجہ سے دنیا سےنیست و نابود ہوگئی۔یہی انجام ان اقوام کا بھی ہوگا،جو االلہ تعالیٰ کےاحکام واوامرکا انکارکررہی ہیں، اس لیے کہ االلہ تعالیٰ کی عظیم طاقت کے آگے سب ہیچ اور کمزور ہیں۔\nقوم عاد کے بارے میں کچھ مزید تفاصیل لفظ \"ہو د\"کے بیان میں دیکھیے۔","",{}],[22,"§آخر\nدیکھیے: اسماےحسنی","",{}],[23,"§آخرت\nانسان کی زندگی دوحصوں میں منقسم ہے۔ایک حصے کاتعلق دنیاسے ہے،جوپیدایش کے بعدہی سے شروع ہوجاتاہےاور وفات تک چلتا ہے۔یہ حصہ ایک طرح کی کھیتی ہے،جس میں ہم اچھےیاخراب بیج بوتےہیں۔اس حصےمیں ہم کوکچھ اختیارات دیے گئے ہیں۔ان اختیارات کااستعمال ہم کیسے کریں اسی میں ہماراامتحان ہے۔\nدوسرا حصہ آخرت کہلاتاہے۔آخرت کاآغاز موت کےبعدہوتاہے۔پھر کبھی ختم نہیں ہوتا۔یہ حصہ صرف کھیتی کاٹنے اور اس کے استعمال سےتعلق رکھتاہے۔ہم نےجوکچھ پہلے حصے میں کیاہے،اس کاثمرہ ہمیں اس دوسرے حصے میں حاصل ہوگا۔\nقرآ ن کریم سب سے پہلے ہمیں اسی حصے پر ایمان لانے کاحکم دیتاہے: ﴿الٓمٓ ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدࣰ ى لِّلۡمُتَّقِينَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ﴾ [البقرة: ۱-۴] \"الم،اس کتاب(کے االلہکی کتاب ہونے)میں کوئی شک نہیں،یہ متقیوں اورپرہیز گاروں کوراہ دکھانے والی ہے۔جولوگ غیب پر ایمان لاتے ہیں اور صلاۃ کوقائم رکھتے ہیں اور ہمارے دیے(مال)میں سے خرچ کرتے ہیں اورجولوگ ایمان لاتے ہیں اس پر جوآپ کی طرف اتار ا گیا اور جوآپ سے پہلے اتارا گیا اور وہ آخرت پر بھی یقین رکھتے ہیں\"۔\nآخرت پرایمان اسلام کےبنیادی اصولوں میں سے ایک ہے۔جن کو ہم ارکان ایمان سے تعبیر کرتے ہیں۔ آخرت پر ایمان لائے بغیرکوئی شخص مسلمان نہیں ہوسکتا۔قرآن کی تعلیم کے مطابق انسان کوچاہیےکہ وہ اس دنیا سے زیادہ آخرت کی فکر کرے۔اس لیے کہ یہ دنیا بہت جلد ختم ہوجائے گی۔ لیکن آخرت کبھی ختم نہیں ہوگی: ﴿يَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعࣱ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ﴾ [غافر: ۳۹] \"اےمیری قوم!یہ دُنیوی زندگی متاع فانی ہے اور ہمیشگی کاگھرتوآخرت ہی ہے\"۔\nاس لیےقرآن کی تعلیم ہے کہ آخرت کی فکر زیادہ کرو۔ارشادباری تعالیٰ ہے:\n۱- ﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقࣱ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةࣰۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلࣲ قَرِيبࣲۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلࣱ وَٱلۡأٓخِرَةُ خَيۡرࣱ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا﴾ [النساء: ۷۷] \"آپ کہہ دیجیے کہ دنیا کی فائدہ مندی توبہت ہی کم ہے اور پرہیز گاروں کے لیے توآخرت ہی بہتر ہے\"۔\n۲- ﴿وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَعِبࣱ وَلَهۡوࣱۖ وَلَلدَّارُ ٱلۡأٓخِرَةُ خَيۡرࣱ لِّلَّذِينَ يَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ﴾ [الأنعام: ۳۲] \"اور دنیوی زندگی توکچھ بھی نہیں سوائےکھیل تماشاکےاورآخرت کاگھرمتقیوں کے لیے بہتر ہے۔کیاتم سوچتے سمجھتے نہیں؟\"۔\n۳- ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ مَا لَكُمۡ إِذَا قِيلَ لَكُمُ ٱنفِرُواْ فِي سَبِيلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِيتُم بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا مِنَ ٱلۡأٓخِرَةِۚ فَمَا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا قَلِيلٌ﴾ [التوبة: ۳۸] \"اے ایمان والو!تمھیں کیا ہوگیا ہے کہ جب تم سے کہا جاتا ہےکہ چلو االلہ کے راستے میں نکلوتو تم زمین سے لگ جاتےہو۔کیاتم آخرت کے عوض دنیا کی زندگانی پر ہی ریجھ گئےہو۔سنو! دنیا کی زندگی توآخرت کے مقابلے میں کچھ یوں ہی سی ہے\"۔\n۴- ﴿ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ وَفَرِحُواْ بِٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا فِي ٱلۡأٓخِرَةِ إِلَّا مَتَٰعࣱ‏﴾ [الرعد: ۲۶] \"لوگ دنیوی زندگی پر خوش ہورہے ہیں،حالانکہ دنیاآخرت کےمقابلے میں نہایت حقیرپونجی ہے\"۔\n۵- ﴿وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوࣱ وَلَعِبࣱۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ﴾ [العنکبوت: ۶۴] \"اوردنیاکی یہ زندگی تومحض کھیل تماشاہے۔البتہ آخرت کی زندگی ہی حقیقی زندگی ہے۔کاش ہم یہ جانتے ہوتے\"۔\nاس دنیا کوسب کچھ سمجھنے والوں اور آخرت پر ایمان ویقین نہ رکھتے والوں کی قرآن مجید سخت مذمت کرتا ہے:\n۱- ﴿إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ﴾ [النمل: ۴] \"بے شک جولوگ آخرت پر ایمان نہیں رکھتے ہم نے انھیں ان کے کرتوت زینت دار دکھادے ہیں،اس لیے وہ بھٹکتے پھر رہے ہیں\"۔\n۲- ﴿وَأَمَّا ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا وَلِقَآيِٕ ٱلۡأٓخِرَةِ فَأُوْلَٰٓئِكَ فِي ٱلۡعَذَابِ مُحۡضَرُونَ﴾ [الروم: ۱۶] \"اور جنھوں نے کفر کیا اور ہماری آیتوں اورآخرت کی ملاقات کو جھوٹا ٹھہرایا،وہ سب عذاب میں حاضر کیے جائیں گے\"۔\nاس لیے ہمیں حکم دیا گیا ہے کہ جہاں ہم دنیوی زندگی کی بھلائی کےلیے کوشش کریں اور دعا مانگیں وہیں آخرت کی بھلائی کی بھی دعا مانگیں۔کیوں کہ ہمیشہ رہنے والی دنیا تووہی ہے:\n۱- ﴿فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرࣰ اۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقࣲ وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ﴾ [البقرة: ۲۰۰-۲۰۱] \"بعض لوگ وہ بھی ہیں جوکہتے ہیں: اے ہمارے رب! ہمیں دنیا میں دے۔ایسے لوگوں کا آخرت میں کوئی حصہ نہیں اوربعض لوگ وہ بھی ہیں جوکہتےہیں: اے ہمارے رب!ہمیں دنیا میں بھی بھلائی دے اور آخرت میں بھی بھلائی عطا فرمااور ہمیں جہنم کے عذاب سے نجات دے\"۔\n۲- ﴿وَٱكۡتُبۡ لَنَا فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةࣰ وَفِي ٱلۡأٓخِرَةِ إِنَّا هُدۡنَآ إِلَيۡكَۚ قَالَ عَذَابِيٓ أُصِيبُ بِهِۦ مَنۡ أَشَآءُۖ وَرَحۡمَتِي وَسِعَتۡ كُلَّ شَيۡءࣲۚ فَسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤۡمِنُونَ﴾ [الأعراف: ۱۵۶] \"ہمارے لیے اس دنیا میں بھی بھلائی لکھ دے اورآخرت میں بھی،ہم تیری طرف رجوع کرتے ہیں\"۔","",{}],[24,"§اخلاق\nدیکھیے: قرآن مجیدمیں اخلاق کی تعلیم","",{}],[25,"§ادرک\nدیکھیے: زنجبیل","",{}],[26,"§ادريس علیہ السلام\nادریس علیہ السلام کاذکر قرآن میں دومقام پر ہوا ہے۔ایک سورہ مریم میں: ﴿وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقࣰ ا نَّبِيࣰّ ا وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا﴾ [مریم: ۵۶-۵۷] \"اور کتاب میں ادریس کاذکر کروبے شک وہ بڑا سچانبی تھااور ہم نے اسے ایک بلند مقام پر پہنچادیا\"۔\nدوم سورہ انبیا میں: ﴿وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلࣱّ مِّنَ ٱلصَّٰبِرِينَ وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ﴾ [الأنبیاء: ۸۵-۸۶] \"اوراسماعیل،ادریس اور ذوالکفل(کوبھی یادکرو)یہ سب صابر لوگ تھے اور ہم نے انھیں اپنی رحمت میں داخل کرلیا۔ یہ سب نیک لوگ تھے\"۔\nصحیح حدیث میں اتنا ذکرہے کہ معراج کی رات نبی اکرم صلی اللہ علیہ وسلم کی ادریس علیہ السلام سےچو تھے آسمان پر ملاقات ہوئی تھی (صحیح البخاری وصحیح مسلم)۔اس سےزیادہ ہم کچھ نہیں جانتے کہ یہ کون تھے اورکب دنیا میں آئے۔ہمیں قرآن مجیدسے یہ معلوم ہوتاہےکہ یہ نبی عربوں میں معروف تھے۔ لوگ ان سے اچھی طرح واقف تھے۔اس لیے ان کے بارے میں کسی نے کوئی استفسار نہیں کیا۔لیکن بنی اسرائیل نے دیگرانبیا کی طرح ادریس علیہ السلام کے بارے میں بھی بہت ساری غلط باتیں پھیلا دی تھیں۔ قرآن نے ان غلط باتوں کی تردیدکی اور یہ بھی واضح کیاکہ وہ ایک سچے نبی تھے،جن کو ہم نے بڑااونچا مرتبہ عطا کیاتھا۔\nبعض علماء کاخیال ہے کہ یہ وہی حنوک ہیں جن کا ذکر تورات میں اس طرح ہے:حنوک االلہکے ساتھ چلتا رہا۔پھر کھوگیا۔کیوں کہ االلہ نے اسے اٹھالیا۔ (پیدایش: ۵: ۲۴)\nحنوک آدم علیہ السلام کی ساتویں نسل میں سےتھے۔االلہ ہی کو پکارتےاورصرف اس کی ہی عبادت کرتے تھے۔ انھی کے نسل سے نوح پیدا ہوے۔عبرانی زبان میں حنوک کامطلب ہے پڑھنے والا۔عربی زبان میں ادریس کے معنیٰ بھی پڑھنےوالےکےہیں۔کہا جاتاہے کہ ادریس وہی حنوک ہیں، لیکن یہ سب خیالی باتیں ہیں۔قرآن کریم نے ادریس کا تفصیلی ذکر نہیں کیا ہے۔اس لیے ہم یقین سے کچھ نہیں کہہ سکتے،البتہ قرآن کریم نےصرف اس بات کی تصدیق کی ہے کہ ادریس بھی ایک سچے رسول تھے۔ لوگوں نے ان سے جوغلط باتیں منسوب کردی تھی،قرآن نے ان کی تردید کی اوریہ بتایا ہے کہ وہ بھی اسماعیل کی طرح صبرکرنے والے نبی تھے۔ان کی اس اخلاقی بلندی میں ہمارے لیے نمونہ اور نصیحت ہے۔","",{}],[27,"§آدم علیہ السلام\nآدم عبرانی لفظ ہے،جس کےمعنیٰ گندمی رنگ والے کے ہیں۔آدم علیہ السلام تمام انسانوں کے باپ ہیں۔ان کو االلہ تعالیٰ نے مٹی سے پیدا کیا اور اپنے حکم سےان کے اندرروح ڈالی۔واضح رہے کہ روح اللہ تعالیٰ کی ساری مخلوقات کی طرح ایک مخلوق ہے۔ اللہ رب العزت کے حکم سے اس کی خلقت آدم علیہ السلام کے جسم میں ہوئی۔ اللہ کی طرف اس روح کی نسبت تشریفی ہے۔(یعنی بہ طور شرف واعزاز کے، جیسے کعبۃ اللہ اور ناقۃ اللہ)۔اللہ تعالیٰ نے آدم کی تخلیق کے بعدفرشتوں کوحکم دیاکہ وہ آدم کوسجدہ کریں۔سب نےسجدہ کیا،لیکن شیطانوں کے سردار ابلیس نے سجدہ کرنے کے سے انکار کردیا۔تخلیق آدم کی تفصیل قرآن حکیم میں ملاحظہ ہو:\n۱- ﴿وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرࣰ ا مِّن صَلۡصَٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّٰجِدِينَ﴾ [الحجر: ۲۸-۳۱] \"اور جب تیرے رب نے فرشتوں سے فرمایا کہ میں ایک انسان کو کالی اور سڑی ہوئی کھنکھناتی مٹی سے پیدا کرنے والا ہوں۔تو جب میں اسے پورا بنا چکوں اور اس میں میں اپنی طرف سےروح پھونک دوں تو تم سب اس کے لیےسجدے میں گر پڑنا۔چنانچہ ابلیس کےسواسارےفرشتوں نے سجدہ کر لیا۔ ابلیس نے سجدہ کرنےوالوں میں شامل ہونے سے صاف انکار کر دیا\"۔\n۲- ﴿فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ فَسَجَدَ ٱلۡمَلَٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ إِلَّآ إِبۡلِيسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ﴾ [ص: ۷۲-۷۴]\"سو جب میں اسے ٹھیک ٹھاک کرلوں اور اس میں اپنی طرف سےروح پھونک دوں، تو تم سب اس کے سامنے سجدے میں گر پڑنا چنانچہ تمام فرشتوں نے سجدہ کیا مگرابلیس نے (نہ کیا)، اس نے تکبر کیا اور وہ تھا کافروں میں سے \"۔\nجب االلہتعالیٰ نے انکار کی وجہ پوچھی توابلیس نے کہا:﴿قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرࣱ مِّنۡهُ خَلَقۡتَنِي مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِينࣲ‏﴾ [الأعراف: ۱۲] \"میں اس سے بہتر ہوں کیوں کہ تونے مجھے آگ سے پیدا کیاہے اور اسے مٹی سے بنایا ہے\"۔ االلہ تعالیٰ کوابلیس کی یہ گستاخی پسند نہیں آئی اور اس کو جنت سے نکال دیا۔\nجب االلہ تعالیٰ نے فرشتوں سے کہا کہ میں زمین میں خلیفہ بنانے والا ہوں توفرشتوں کوبڑاتعجب ہواکہ ہم االلہ تعالیٰ کی دن رات عبادت کررہے ہیں پھر آدم کوپیدا کرنے کی کیاضرورت ہے۔االلہ تعالیٰ نے فرمایا: ﴿مَا لَا تَعۡلَمُونَ﴾ [البقرة: ۳۰] \"جومیں کررہاہوں مجھے معلوم ہے۔تم کو اس کاعلم نہیں\"۔مزیدارشادباری ہے: ﴿وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ قَالَ يَٰٓـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَآئِهِمۡۖ فَلَمَّآ أَنۢبَأَهُم بِأَسۡمَآئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّيٓ أَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ﴾ [البقرة: ۳۱-۳۳] \"اور االلہ تعالیٰ نے آدم کوتمام نام سکھا کران چیزوں کو فرشتوں کے سامنے پیش کیا اور فرمایا: اگر تم سچے ہوتوان چیزوں کے نام بتاؤ۔ان سب نے کہا: اے االلہ!تیری ذات پاک ہے ہمیں تو صرف اتنا ہی علم ہے جتناتونے ہمیں سکھارکھا ہے،توعلیم وحکیم ہے۔پورے علم وحکمت والا توہی ہے۔االلہ تعالیٰ نے آدم سے فرمایا: تم ان کے نام بتادو۔جب آدم نےسارے نام بتادیے توفرشتوں سےفرمایاکہ کیا میں نے تمھیں(پہلے ہی)نہ کہا تھا کہ زمین اور آسمانوں کا غیب میں ہی جانتا ہوں اور میرے علم میں ہے جوتم ظاہر کررہے ہواور جوتم چھپاتے ہو\"۔\nپھر آدم کی پسلی سےان کی بیوی حوّا کوپیداکیا۔ ارشادباری تعالیٰ ہے : ﴿يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسࣲ وَٰحِدَةࣲ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالࣰ ا كَثِيرࣰ ا وَنِسَآءࣰۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبࣰ ا﴾ [النساء: ۱] \"اے لوگو! اپنے رب سے ڈرو،جس نے تمھیں ایک جان سے پیدا کیا اور اسی سے اس کی بیوی کوپیدا کرکےان دونوں سے بہت سے مرد اور عورتیں پھیلادیں۔اس االلہ سے ڈرو جس کے نام پر ایک دوسرے سے مانگتے ہواور رشتے ناتے توڑنے سے بھی بچو۔بے شک االلہ تعالیٰ تم پر نگہبان ہے\"۔\nصحیح بخاری میں ابوہریرہ رضی اللہ عنہ سےمروی حدیث میں آیاہے کہ نبی اکرم صلی اللہ علیہ وسلم کا ارشاد ہے: «وَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا فَإِنَّهُنَّ خُلِقْنَ مِنْ ضِلَعٍ وَإِنَّ أَعْوَجَ شَيْءٍ فِي الضِّلَعِ أَعْلاهُ فَإِنْ ذَهَبْتَ تُقِيمُهُ کَسَرْتَهُ وَإِنْ تَرَکْتَهُ لَمْ يَزَلْ أَعْوَجَ فَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا».(صحيح البخاری: ۵۱۸۶ وصحیح مسلم: ۷۱۵/۵۴)\n\"اور میں تمھیں عورتوں کے بارے میں بھلائی کی وصیت کرتا ہوں کیوں کہ وہ پسلی سے پیدا کی گئی ہیں اور پسلی میں بھی سب سے زیادہ ٹیڑھا اس کے اوپر کا حصہ ہے۔ اگر تم اسے سیدھا کرنا چاہو گے تو اسے توڑ ڈالو گے اور اگر اسے چھوڑ دوگے تو ٹیڑھی ہی باقی رہ جائے گی۔ اس لئے میں تمھیں عورتوں کے بارے میں اچھے سلوک کی وصیت کرتا ہوں\"۔\nابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ الْمَرْأَةَ خُلِقَتْ مِنْ ضِلَعٍ لَنْ تَسْتَقِيمَ لَکَ عَلَی طَرِيقَةٍ فَإِنْ اسْتَمْتَعْتَ بِهَا اسْتَمْتَعْتَ بِهَا وَبِهَا عِوَجٌ وَإِنْ ذَهَبْتَ تُقِيمُهَا کَسَرْتَهَا وَکَسْرُهَا طَلاقُهَا». (صحیح مسلم: ۱۴۶۸) \" عورت پسلی سے پیدا کی گئی ہے، وہ تم سے سیدھی چال کبھی نہیں چلے گی، اگر اس سے فائدہ اٹھانا ہے تو اس کی کجی کے رہتے ہوئے فائدہ اٹھاؤ اور اگر اسے سیدھا کرنے چلو گے تو اسے توڑ دڈالو گے اور اس کا توڑنا اسے طلاق دینا ہے\"۔\nتورات میں بھی آیاہے کہ حوّا کو آدم کی پسلی سے پیداکیا گیا۔حوّا کو آدم سے پیدا کرنے میں کوئی تعجب نہیں ہونا چاہیے۔ کیوں کہ االلہ تعالیٰ جب خود آد م کومٹی سے پیدا کرسکتاہے توحوّا کوآدم سے پیدا کرنے میں کیاتعجب ہے؟ پھر آدم وحوا کوااللہ تعالیٰ نے جنت میں رکھااور ان سے کہاکہ جوچاہوکھاؤ پیو،البتہ اس درخت کاپھل مت کھانا۔ لیکن شیطان ان دونوں کوبہلاپھسلاکر اس ممنوع درخت کے پاس لے گیااور قسم کهاکر ان سے کہنے لگا کہ تمھارے رب نے اس کا پھل کھانے سے اس لیے روکا ہے کہ کہیں تم فرشتہ نہ بن جاؤیا ہمیشہ کے لیے جنت میں رہنے والے نہ بن جاؤ۔اس لیے ان دونوں نے اس درخت کاپھل کھالیا۔تب ان کوااللہ تعالیٰ نےحکم دیاکہ زمین پر اترجاؤ اور ایک مقرر وقت تک تمھیں وہیں رہنا پڑےگا۔جب آدم کواحساس ہوا کہ وہ شیطان کے بہکاوے میں آگئےتوانھوں نے االلہ تعالیٰ سے توبہ کی۔ (البقرة: ۳۵-۳۶)\nاس طرح آدم اورحوّا دونوں زمین پررہنے لگے۔ دونوں سےدولڑکے پیدا ہوے،ایک کانام قاین(قابیل) تھااور دوسرےکانام ہابیل۔قاین کامطلب ہوتا ہے لوہار(حداد)اور ہابیل کامطلب ہوتا ہے لڑکا۔آدم ایک لڑکے کا دوسرے لڑکے کی جڑوا ں بہن سے شادی کردیتے تھے،پھر قابیل نے اپنے بھائی ہابیل کوقتل کردیا۔ قرآن مجیدمیں آیا ہے:﴿وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱبۡنَيۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانࣰ ا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ ٱلۡأٓخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ﴾ [المائدة: ۲۷] \"آدم علیہ السلام کے دونوں بیٹوں کاکھرا کھرا حال بھی انھیں سنادو۔ ان دونوں نے ایک قربانی پیش کی، جب ان میں سےایک کی قربانی قبول ہوگئی اور دوسرے کی نہ ہوئی تووہ کہنے لگا کہ میں تجھے مارہی ڈالوں گا۔اس نےکہا: االلہ تعالیٰ تقویٰ والوں کا ہی عمل قبول کرتا ہے\"۔\nتورات سےمعلوم ہوتاہے کہ ہابیل بھیڑبکریاں چراتاتھا۔اس لیے اس نے جانور کے پہلے بچے کی قربانی دی۔ قابیل کاشت کارتھا، اس لیے اس نے پھلوں کی قربانی پیش کی،جس کوااللہ تعالیٰ نے قبول نہیں فرمایا۔اس وجہ سے وہ غضبناک ہوگیا۔ اس نے اپنے بھائی ہابیل کوقتل کردیا۔ (کتاب پیدایش: ۴:۲-۹)\nقتل کےبعدقابیل کی سمجھ میں نہیں آرہا تھا کہ بھائی کی لاش کوکیا کرے۔قرآن مجید میں آیا ہے: ﴿يَٰقَوۡمِ ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّواْ عَلَىٰٓ أَدۡبَارِكُمۡ فَتَنقَلِبُواْ خَٰسِرِينَ﴾ [المائدة: ۲۱] \"پھرااللہ تعالیٰ نے ایک کوّے کو بھیجا جو زمین کھودرہاتھا۔تاکہ اسےدکھائےکہ وہ کس طرح اپنے بھائی کی نعش کوچھپا دے،وہ کہنے لگا: ہائے افسوس! کیامیں ایسا کرنے سے بھی گیا گزرا ہوگیا کہ اس کوّے کی طرح اپنے بھائی کی لاش کودفنا دیتا؟پھر وہ بڑاہی پشیمان اور شرمندہ ہوگیا\"۔\nاس طرح بنی نوع انسان نےمردےکوزمین میں دفن کرناسیکھا۔عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لاَ تُقْتَلُ نَفْسٌ ظُلْمًا إِلاَّ کَانَ عَلَی ابْنِ آدَمَ الأَوَّلِ کِفْلٌ مِنْ دَمِها، لأَنَّه أَوَّلُ مَنْ سَنَّ الْقَتْلَ». (صحیح البخاری: ۳۳۳۵) \"جب بھی کوئی قتل ہوتاہے توآدم کے پہلے بیٹے کواس قتل کے گناہ کاکچھ حصہ پہنچتاہے۔کیوں کہ وہ پہلا انسان ہے، جس نے قتل کی ابتداکی\"۔\nہابیل کے قتل کےبعد آدم اور حوّا سے شیث پیدا ہوے۔شیث کے معنیٰ بدل کے ہیں۔ اس کا مطلب یہ ہے کہ شیث ہابیل کابدل تھے، جس کو اس کے بھائی قابیل نے قتل کردیا تھا۔پھر ان دونوں قابیل اور شیث سے بنی نوع انسان کی نسل چلی۔ (پیدایش: ۴:۲۵-۳۵)\nمحمد بن اسحاق اور دیگر مورخین نے بیان کیاہے کہ آدم کے کل بیس لڑکے اور بیس لڑکیاں پیدا ہوئیں۔ بعض دوسرےلوگ کہتے ہیں کہ ساٹھ لڑکے اور ساٹھ لڑکیاں پیدا ہوئیں اوران سے انسانوں کی نسل چلی۔\nتورات میں ہے کہ شیث کی پیدایش کے بعد آدم آٹھ سوسال تک زندہ رہے۔ شیث کی پیدایش کےوقت آدم کی عمر ۳۰ا سال تھی۔ان سے لڑکے اورلڑکیاں پیدا ہوئیں۔آدم کی عمر وفات کے وقت ۹۳۰ سال تھی۔ (پیدایش: ۵:ا-۵) کچھ احادیث میں آدم علیہ السلام کی عمر ایک ہزار سال مذکورہے۔اگر اسے صحیح مان لیں تو ان کی جنت میں رہنے کی عمر ستر سال ہوگی۔\nآدم علیہ السلام نے اپنی وفات سے قبل شیث کو اپنا وارث بنایا۔جن کو االلہ تعالیٰ نے ان کے بعد نبی بنایا اوران پر کوئی کتاب بھی نازل کی۔لیکن اس کے بارے میں ہمارے پاس کوئی سندنہیں ہے۔بعض علماء کاخیال ہےکہ آدم علیہ السلام کی قبر ہندستان میں ہے۔ بعض کاخیال ہے کہ مکہ میں۔مگر ان میں سے کسی بات کے لیے کوئی ثبوت نہیں۔آدم کی وفات کے ایک سال بعد ان کی زوجہ محترمہ حوّا کی بھی وفات ہوئی۔","",{}],[28,"§آدمی\nدیکھیے: انسان","",{}],[29,"§اذان\nلفظ اذان کا مطلب ہے پکارنا، ندا کرنا۔قرآن کریم میں ہے کہ االلہ تعالیٰ نے ابراہیم علیہ السلام کو حکم دیا کہ وہ لوگوں کو حج کے لیے پکاریں: ﴿وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالࣰ ا وَعَلَىٰ كُلِّ ضَامِرࣲ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقࣲ‏﴾ [الحج: ۲۷] \"اور لوگوں میں حج کے لیے منادی کردو۔وہ تیرے پاس پیدل اور دبلے پتلے اونٹوں پر، دور دراز کی تمام راہوں سے آئیں گے\"۔\nعبداللہ بن عمر رضی اللہ عنہما کہتےہیں:«کَانَ الْمُسْلِمُونَ حِينَ قَدِمُوا الْمَدِينَةَ يَجْتَمِعُونَ فَيَتَحَيَّنُونَ الصَّلاةَ ليسَ يُنَادَی لَهَا، فَتَکَلَّمُوا يَوْمًا فِي ذَلِکَ فَقَالَ بَعْضُهُمْ: اتَّخِذُوا نَاقُوسًا مِثْلَ نَاقُوسِ النَّصَارَی، وَقَالَ بَعْضُهُمْ: بَلْ بُوقًا مِثْلَ قَرْنِ اليهُودِ، فَقَالَ عُمَرُ: أَوَلا تَبْعَثُونَ رَجُلا يُنَادِي بِالصَّلاةِ؟ فَقَالَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم : يَا بِلالُ قُمْ فَنَادِ بِالصَّلاةِ». (صحیح البخاری: ۶۰۴، وصحیح مسلم: ۳۷۷/۱) \"ابتدا میں مسلمان مدینہ میں نماز کو متعین وقت پر باجماعت ادا کرنے کے لیے لوگوں کو اطلاع دینے کے لیے کوئی مناسب طریقہ نہیں رکھتےتھے۔وہ آپس میں کہنے لگے: کیوں نہ ہم نصاری کی طرح نماز کے اعلان کے لیے گھنٹی بجائیں۔ کسی نے کہا کہ کیوں نہ یہودیوں کی طرح نرسنگھا پھونکیں۔ عمر رضی اللہ عنہ نے یہ رائے دی کہ سب سےبہتر طریقہ یہ ہے کہ نماز کے اعلان کے لیے کسی کو کہاجائے کہ جاؤ اور نماز نماز پکارو۔ اس بات کو نبی اکرم صلی اللہ علیہ وسلم نے پسند فرمایا اور بلال رضی اللہ عنہ کوحکم دیا کہ جاؤ نماز کے لیےپکارو\"۔\nمگرابھی بھی لوگ اس بارے میں فکر مند ہی تھے کہ ایک دن عبدااللہ بن زید بن عبد ربہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوکرآپ کوخبردی کہ االلہ کےرسول! میں نیم غنودگی کی کیفیت میں تھاکہ کیا دیکھتا ہوں کہ ایک شخص آیا اور اس نے میرے سامنے اذان دی۔عمر رضی اللہ عنہ نے کہا کہ میں نے بھی بیس روزقبل ایسا ہی دیکھا تھا۔اس پر نبی اکرم صلی اللہ علیہ وسلم نے بلال رضی اللہ عنہ کو حکم دیا کہ وہ اذان دیں۔کیوں کہ ان کی آواز میٹھی اور بلند تھی۔ اس دن سے آج تک نماز کےاعلان کے لیے مسجدوں میں اذان دی جاتی ہے۔جس میں االلہ تعالیٰ کی عظمت اور نبی اکرم صلی اللہ علیہ وسلم کےرسول ہونے کی گواہی دی جاتی ہے۔نماز کے لیے بلایا جاتا ہے۔اذان کے کلمات یہ ہیں: اللَّه أَکْبَرُ: االلہسب سے بڑا ہے، (چار بار) أَشْهدُ أَنْ لا إِلَه إِلا اللَّه: میں گواہی دیتا ہوں کہ االلہ کے سوا کوئی معبود برحق نہیں، (دوبار) أَشْهدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّه: میں گواہی دیتا ہوں کہ محمد االلہ کے رسول ہیں، (دوبار) حَيَّ عَلَی الصَّلاةِ: آؤ نماز کے لیے آؤ، (دوبار) حَيَّ عَلَی الْفَلاحِ: آؤ کامیابی کی طرف آؤ، (دوبار) اللَّه أَکْبَرُ: االلہسب سے بڑا ہے (دوبار) لا إِلَه إِلا اللَّه: االلہکے سوا کوئی حقیقی معبود نہیں (ایک بار)۔\nاذان کی آواز سننے والے ہر مسلمان پر ضروری ہے کہ وہ اذان کا جواب دے اوروہ بھی اسی طرح اذان کے کلمات کو آہستہ آہستہ دہرائے اور جب موذن حَيَّ عَلَی الصَّلاةِ اور حَيَّ عَلَی الْفَلاحِ پر پہنچےتو اس کے جواب میں کہے: لاحَوْلَ وَلا قُوَّةَ إِلا بِاللَّه۔اس کا مطلب ہے کہ نماز پڑھنے اور کامیابی کی جانب ہمارے آنے کی طاقت وقوت نہیں اگر االلہ نہ چاہے۔اس عمل میں انسان ایک طرح سے االلہ تعالیٰ کے مقابلے میں اپنی بے چارگی کا اظہار کرتا ہے۔\nاذان کا اصل جواب تو یہی ہے کہ ہم اذان کی آواز سنتے ہی نماز کے لیے چل پڑیں۔مگر االلہ کے رسول صلی اللہ علیہ وسلم نے ان الفاظ کے دہرانے کا حکم بھی دیا ہے۔\nاذان کےبعد ایک مخصوص دعاپڑھی جاتی ہے جس کا ذکر صحیح احادیث میں موجود ہے۔اس کے پڑھنےسے نبی اکرم صلی اللہ علیہ وسلم کی شفاعت اگر االلہ نے چاہا توقیامت کے دن حاصل ہوگی۔\nصحیح احادیث میں مذکور ہے کہ موذن کی گردن قیامت کے دن سب سے اونچی ہوگی۔(صحیح مسلم ۳۸۷)\nاسی طرح ایک دوسری حسن حدیث میں آیا ہے کہ قیامت کے دن موذن کے لیے جہاں تک اس کی آواز پہنچے گی سب گواہی دیں گے۔ (سنن ابی داود: ۵ا۵)","",{}],[30,"§ارض\nارض کواردو میں زمین کہتے ہیں،اس کی جمع اراضی ہے، جو اردو میں بھی مستعمل ہے۔یہ وہی جگہ ہے، جس پرہم چلتے پھرتے اور رہتےہیں۔ یہ اللہ تعالیٰ کی مخلوقات میں سے ایک مخلوق ہے،جس میں غور و فکر کرنےوالوں کے لیے بہت ساری عبرت اورہدایت کی باتیں ہیں۔قرآن مجیدمیں ہے:﴿إِنَّ فِي خَلۡقِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ لَأٓيَٰتࣲ لِّأُوْلِي ٱلۡأَلۡبَٰبِ﴾ [آل عمران: ۱۹۰] \"بےشک آسمانوں اور زمین کی تخلیق میں اور رات اوردن کے ایک دوسرے کے بعد باری باری سے آنے میں عقل مندوں کے لیے بہت سی نشانیاں ہیں\"۔\nزمین وآسمان آپس میں ملے ہوےتھے۔ ارشاباری تعالیٰ ہے : ﴿أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقࣰ ا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ﴾ [الأنبیاء: ۳۰] \"کیا کافروں نے دیکھا نہیں کہ آسمان اورزمین پہلے سے آپس میں جڑے ہوے تھے،پھر ہم نے انھیں الگ الگ کردیا اور پانی سے ہر جاندار چیز بنائی۔ تو یہ لوگ ایمان کیوں نہیں لاتے؟\"۔\nاس آیت سے ایسا معلوم ہوتا ہے کہ قدیم زمانے سے یہ بات چلی آرہی ہے کہ آسمان اور زمین آپس میں دونوں جڑے ہوے تھے۔ اسی لیے قرآن کافروں کو مخاطب کررہا ہے کہ کیا انھوں نے دیکھا اورغورو فکرنہیں کیا۔یہاں آسمان سے مراد ہے کہ جو کچھ آسمان میں ہے۔مختلف طرح کے سیارے الگ ہوتے ہی اپنی اپنی راہ کی طرف نکل پڑے اور پھر اپنی متعینہ حد یا مدار میں گھومنے لگے۔\nاللہ تعالیٰ نے اس پوری کائنات کو جس میں آسمان اور زمین بھی ہےصرف چھ دنوں میں پیدا کیا:﴿ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيࣲّ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ﴾ [السجدة: ۴] \"اللہ تعالیٰ وہ ہے جس نے آسمان و زمین اور جو کچھ ان درمیان ہے سب کو چھ دن میں پیدا کر دیا پھر عرش پر مستوی ہوا تمھارے لیے اس کے سوا کوئی مددگار اور سفارشی نہیں۔ کیا اس پر بھی تم نصیحت حاصل نہیں کرتے \"۔\nآسمان کی طرح زمین کےبھی سات طبقات ہیں۔ ارشادباری تعالیٰ ہے: ﴿ٱللَّهُ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتࣲ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ يَتَنَزَّلُ ٱلۡأَمۡرُ بَيۡنَهُنَّ لِتَعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا﴾ [الطلاق: ۱۲] \"اللہ ہی تو ہے جس نے سات آسمان پیدا کیے اور انھی کی طرح زمینیں بھی۔ اس کا حکم ان کے درمیان اترتا ہے، تاکہ تم جان لو کہ اللہ ہر چیزپر قادر ہے اور اللہ تعالیٰ نے ہر چیزکو بہ اعتبار علم گھیر رکھا ہے\"۔\nسعیدبن زید بن عمروبن نفیل رضی اللہ عنہ سے مروی حدیث میں ہےکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ اقْتَطَعَ شِبْرًا مِنْ الأَرْضِ ظُلْمًا طَوَّقَه اللَّه إِيَّاه يَوْمَ الْقِيَامَةِ مِنْ سَبْعِ أَرَضِينَ». (صحیح مسلم: ۱۳۷/۱۶۱۰) \"جس نے کسی کی ایک بالشت کے برابر زمین پر قبضہ کیاقیامت کے دن سات زمینوں کا طوق اس کی گردن میں ڈال دیا جائے گا\"۔\n٭ زمین کو پہاڑوں کے ذریعےسےمستحکم کردیا تاکہ کسی ایک طرف جھک نہ جائے۔ارشاد باری تعالیٰ ہے :\n۱- ﴿وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرࣰ ا وَسُبُلࣰ ا لَّعَلَّكُمۡ تَهۡتَدُونَ﴾ [النحل: ۱۵] \"اور اس نے زمین میں پہاڑ گاڑ دیئے ہیں تاکہ تمھیں لے کر ہلے نہ اور نہریں اور راستے بنادیےتاکہ تم منزل مقصود کو پہنچو\"۔\n۲- ﴿وَجَعَلۡنَا فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجࣰ ا سُبُلࣰ ا لَّعَلَّهُمۡ يَهۡتَدُونَ﴾ [الأنبیاء: ۳۱] \"اور ہم نے زمین میں مستحکم پہاڑ رکھ دئیے تاکہ وہ تمھیں لے کر لڑھک نہ جائے اور ہم نے اس میں ایسے درے بنائے جو راستوں کے کام آتے ہیں تاکہ وہ راہ پاسکیں\"۔\n۳- ﴿خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدࣲ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةࣲۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجࣲ كَرِيمٍ﴾ [لقمان: ۱۰] \"اس نے آسمان کو بغیر ستون کے پیدا کیا جیسا کہ تم دیکھتے ہو اور زمین میں پہاڑ ڈال دیے تاکہ وہ تمھیں لے کر لڑھک نہ جائے اور اس میں ہر طرح کے حیوان پھیلادیے\"۔\nپہاڑوں کو زمین میں گاڑ نے کا اہم فائدہ یہ ہے کہ زمین کی رفتار اور اس کی چال کو ٹھیک رکھا جائے۔\nاللہ تعالیٰ نے ہرچیز کو ایک اندازےکے ساتھ پیدا کیا: ﴿إِنَّا كُلَّ شَيۡءٍ خَلَقۡنَٰهُ بِقَدَرࣲ وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ﴾ [القمر: ۴۹-۵۰] \"یقیناً ہم نے ہرچیز کو اندازےکےساتھ پیدا کیا اور ہمارا حکم تو بس ایک دم کی بات ہوتی ہے۔ جیسے آنکھ جھپکنا\"۔\nجس طرح پلک جھپکانے میں دیر نہیں ہوتی اسی طرح ہمارے حکم(کام)کو شکل اختیار کرنے میں دیر نہیں ہوتی۔یہ جو کچھ ہوتا ہے،وہ پورے قانون کے مطابق ہوتا ہے۔تاکہ دنیا کو مقرر ہ نظام پر چلنے میں کوئی پریشانی نہ ہو۔\nاللہ کے ایک دن کا نظام ہمارے ایک ہزار سال کے برابر ہے: ﴿يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمࣲ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةࣲ مِّمَّا تَعُدُّونَ﴾ [السجدة: ۵] \"وہ آسمان سے زمین تک ہر کام کا انتظام کرتا ہے پھر یہ کام اس کے پاس پہنچ جاتے ہیں جس کا اندازہ تمھارے حساب سے ایک ہزار سال کے برابر ہے\"۔\nاللہ تعالیٰ آسمان سےجس کے اوپر اس کا عرش ہے اور جہاں لوحِ محفوظ ہے،زمین پر اپنا حکم نازل فرماتا ہے۔جیسے زندگی،موت، صحت،بیماری،جنگ اورامن وغیرہ۔ ایک ہزار سال کی پوری تفصیل اس کے پاس ایک دن کے برابر ہے۔ اس سے اس کی عظیم حکومت کا پتا چلتا ہے۔\nآسمان کوستاروں کےذریعےعمدہ طریقے سے مزین کیاگیاہے:\n۱- ﴿إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ﴾ [الصافات: ۶] \"ہم نےدنیاکےنزدیک والےآسمان کوستاروں کےذریعے نہايت مزین کردیا\"۔\n۲- ﴿وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومࣰ ا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ﴾ [الملک: ۵] \"ہم نے دنیا کے نزدیک والے آسمان کو چراغوں(ستاروں)سے سجایا اور اس سے شیطانوں کو بھگانے کا کام لیا\"۔\nزمین کی طرح دوسرے آسمانوں میں بھی مخلوقات پائی جاتی ہیں: ﴿وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةࣲ وَٱلۡمَلَٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ﴾ [النحل: ۴۹] \"اور جو جاندار آسمانوں اور زمین میں ہیں سب اللہ ہی کو سجدہ کرتے ہیں اورفرشتے بھی۔وہ تکبرنہیں کرتے\"۔\nزمین پر رہنے والوں کے لیے چاند کا نکلنااورڈوبنا وقت جاننے کا ذریعہ ہے:\n۱- ﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ﴾ [البقرة: ۱۸۹] \"وہ آپ سے چاند(کے نکلنےاور ڈوبنے)کے بارے میں پوچھتے ہیں؟ تو آپ بتادیں کہ یہ لوگوں کے لیے وقت اور حج(کا موقع) جاننے کا ذریعہ ہے\"۔\n۲- ﴿هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءࣰ وَٱلۡقَمَرَ نُورࣰ ا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَٰلِكَ إِلَّا بِٱلۡحَقِّۚ يُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَعۡلَمُونَ﴾ [یونس: ۵] \"وہی تو ہے جس نےسورج کو چمک دار بنایا اور چاند کو چاندنی بخشی اور اس کے لیے منزلیں مقرر کیں تاکہ تم اس کے ذریعےسالوں کی گنتی اورحساب معلوم کرو\"۔\nسورج کو چمک دار بنانے کےمعنیٰ ہیں کہ اس کی روشنی خود اپنی ہے۔چاند کو چاندنی بخشنے کےمعنیٰ ہیں کہ وہ سورج کی روشنی کی وجہ سے روشن ہے، اس کی اپنی کوئی روشنی نہیں ہے۔\n۳- ﴿تَبَارَكَ ٱلَّذِي جَعَلَ فِي ٱلسَّمَآءِ بُرُوجࣰ ا وَجَعَلَ فِيهَا سِرَٰجࣰ ا وَقَمَرࣰ ا مُّنِيرࣰ ا﴾ [الفرقان: ۶۱] \"وہ بڑی برکت والا ہے، جس نے آسمان میں برج بنائے اور اس میں ایک روشنی والا چراغ(سورج)اور چمک دار چاند بھی بنا دیا\"۔\nیہاں برج کےمعنیٰ آسمان کے وہ علاقے ہو سکتے ہیں جنھیں مضبوط سرحدوں نے ایک دوسرے سے الگ کر رکھا ہے۔ تاکہ کوئی علاقہ دوسرے علاقے کو پار نہ کرسکے۔\nستاروں کو سمندر اور زمین پر راستا تلاش کرنے کا ذریعہ بنایا:\n۱- ﴿وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُواْ بِهَا فِي ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡأٓيَٰتِ لِقَوۡمࣲ يَعۡلَمُونَ﴾ [الأنعام: ۹۷] \"اور وہی ہے جس نے تمھارے لیے تارے بنائے تاکہ تم ان کے ذریعے سے زمین اور سمندر کی تاریکیوں میں راستا معلوم کرسکو۔ علم رکھنے والوں کے لیے ہم نے آیتیں کھول کھول کر بیان کر دی ہیں\"۔\n۲- ﴿وَعَلَٰمَٰتࣲۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ﴾ [النحل: ۱۶] \"اور تاروں کے ذریعے بھی لوگ راستاپا لیتے ہیں\"۔\nزمین کو اس لائق بنادیا کہ اس میں ہر طرح کی غذا پیدا ہوتی ہے:\n۱- ﴿وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءࣲ مَّوۡزُونࣲ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ﴾ [الحجر: ۱۹-۲۰] \"اور ہم نے زمین کو پھیلایا اور اس میں پہاڑ ڈال دیےاور اس میں ہر طرح کی چیزیں ایک اندازے کے ساتھ اُگائیں۔اسی میں تمھارے کھانے پینےکے سامان بنائے۔ ان کے لیے بھی جن کو روزی دینے والے تم نہیں ہو\"۔\n۲- ﴿وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرࣲ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتࣲ مِّن نَّخِيلࣲ وَأَعۡنَٰبࣲ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةࣱ وَمِنۡهَا تَأۡكُلُونَ﴾ [المؤمنون: ۱۸-۱۹] \"اور آسمان سے ہم نے ایک اندازے کے ساتھ پانی اتاراپھر اسے زمین میں ٹھہرا دیا اور اسے لے جانے کی قوت بھی ہمیں حاصل ہے۔ پھر اس (پانی)کےذریعے سے تمھارے لیے ہم نے کھجوروں اور انگوروں کے باغ بنائے کہ تمھارے لیے ان باغوں میں بہت سے خوش ذائقہ پھل ہیں، ان میں سے تم کھاتے ہو\"۔\nاللہ نےزمین کو ہمارے لیے اور ہر طرح کے جاندار کے لیے رزق کا ذریعے بنایا۔ اب تک جوکچھ ہمیں پتاچلا ہے وہ زمین میں پائے جانے والے وسائل کا صرف ۴ فیصد ہے۔ ابھی تک ۹۶ فیصد کا ہمیں علم نہیں ہوا ہے۔ اس سے اس بات کی تصدیق ہوتی ہے کہ اللہ تعالیٰ نے ہر چیز کوطے شدہ اندازے کے ساتھ اتارا۔\nیہ کائنات ستاروں کا سنگم ہے۔اس کے چاروں طرف سیارے گھوم رہے ہیں، جو اپنے مرکز کی کشش کی وجہ سے اپنے مدار سے باہر نہیں نکل سکے۔جیسے سورج ایک تارا ہے جس کے چاروں طرف سیارے گھوم رہے ہیں۔ اسی طرح سورج بھی کسی بڑے تارے کاسیارہ ہے جس کے چاروں طرف یہ گھوم رہا ہے۔ کتنے ستارے ایسے ہیں، جن کا ابھی تک ہمیں علم نہیں ہوا: ﴿وَٱلسَّمَآءَ بَنَيۡنَٰهَا بِأَيۡيْدࣲ وَإِنَّا لَمُوسِعُونَ﴾ [الذاریات: ۴۷] \"اور آسمان کو ہم نے اپنے ہاتھوں سے بنایا اور بے شک ہم ہی اسے بڑھاتے رہنے والے ہیں\"۔\nکائنات کی ہر چیز اپنے اپنے راستے پر چل رہی ہے:\n﴿وَٱلشَّمۡسُ تَجۡرِي لِمُسۡتَقَرࣲّ لَّهَاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ وَٱلۡقَمَرَ قَدَّرۡنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِيمِ لَا ٱلشَّمۡسُ يَنۢبَغِي لَهَآ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّيۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلࣱّ فِي فَلَكࣲ يَسۡبَحُونَ﴾ [یس: ۳۸-۴۰] \"سورج کے لیے جو متعین راہ ہے وہ اسی پر چلتا رہتا ہے اور یہ سب اللہ کا طے کیا ہوا ہے۔ چاند کے لیے ہم نے ٹھکانے مقرر کر دیے ہیں۔ یہاں تک کہ گردش لگا کر وہ کھجور کی پرانی ٹہنی کی طرح ہوجاتا ہے۔نہ سورج کے بس میں ہے کہ وہ چاند کو چھولے اور نہ رات دن سے آگے بڑھ جانے والی ہے۔ سب کے سب اپنے مدار میں گردش کرتے رہتے ہیں\"۔\nمدارسےمراد وہ نظام ہےجس کے اندر سیارے اپنےستاروں کے ساتھ آسمان میں گردش کرتے رہتےہیں۔جیسے چاند زمین کے ساتھ، زمین سورج کے ساتھ اورسورج کسی اور بڑے سیارہ کے ساتھ گردش کر رہا ہےلیکن کہیں آپس میں ٹکراؤ نہیں ہوتا اور جس دن ایسا ہوگا وہ اس کائنات کا آخری دن ہوگایعنی قیامت ہوگی۔اس دن سب کچھ نیست ونابود ہوجائے گا صرف اللہ کا نام باقی رہ جائے گا:﴿كُلُّ مَنۡ عَلَيۡهَا فَانࣲ وَيَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ﴾ [الرحمن: ۲۶-۲۷] \"زمین پر جو کچھ ہےختم ہونے والا ہے۔ صرف تمھارے رب کا چہرہ جو عظیم اور عزت والا ہے، باقی رہ جائے گا\"۔","",{}],[31,"§اِرم\nقوم عاد ارم کے نام سے بھی معروف ہے۔جو پہاڑوں میں بڑے بڑے ستون بناکراپنے گھربناتی تھی۔جس کی پوری تفصیل لفظ عا د میں دیکھی جاسکتی ہے۔قرآن کریم میں صرف ایک جگہ پر لفظ ارم کا تذکرہ آیا ہے: ﴿إِرَمَ ذَاتِ ٱلۡعِمَادِ﴾ [الفجر: ۷] \"قوم ارم کے ساتھ جو ستونوں والے تھے\"۔\nیہ ارم کیا ہے؟ بعض علماء کاخیال ہےکہ ان میں سے ایک شخص کانام اِرم تھا،اسی کے نام پراس کی پوری قوم کو ارم کہا جانے لگا۔کچھ دوسرےعلما کی رائے ہے کہ یہ پہاڑوں میں گھر بناکر رہنے والوں کی جانب اشارہ ہے۔جس کوعبرانی لغت میں رشم کہتے ہیں اور جس کامعنیٰ ہے علامت،یہ اسی قوم عاد کی جانب اشارہ ہے جو پہاڑوں میں اپنا گھر بناکررہتی تھی۔ان کے گھر وں پر آج بھی آرامی اور ثمودی زبان میں کتبے(لوحات)پائے جاتے ہیں۔","",{}],[32,"§آزر\nابراہیم علیہ السلام کے والد کانام آزر ہے۔اس کا ذکر قرآن مجیدمیں صرف ایک بار آیا ہے:﴿وَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّيٓ أَرَىٰكَ وَقَوۡمَكَ فِي ضَلَٰلࣲ مُّبِينࣲ‏﴾ [الأنعام: ۷۴] \"اور یادکرو جب ابراہیم نے اپنے باپ آزر سے فرمایا کہ کیاتو بتوں کومعبود قرار دیتا ہے۔بے شک میں تجھ کو اور تیری قوم کوصریح گمراہی میں دیکھتا ہوں\"۔\nتورات میں ابراہیم کےوالد کانام تارح ذکر کیاگیاہے۔اب یاتوہم کہیں کہ تورات کے جمع کرنے والےسے تساہل ہواہےیایہ کہیں کہ تارح آزر کالقب رہاہوگا۔اس کے علاوہ جوکچھ بھی کہا جائے وہ درست نہیں۔\nآزر: اُرکارہنےوالا ایک تاجر تھا۔ اس وقت عراق میں لوگ بہت زورو شورسے بت پرستی میں مبتلا تھے۔خاص طور پر چاند کی پوجاکرتے تھے۔دیویدیوتاؤں کے مجسمے خود اپنے ہاتھ سے بناتے اور پھر ان کی پوجاکرتے۔ان کو اتنی چھوٹی بات سمجھ میں نہیں آتی تھی کہ جن کو انھوں نے اپنے ہاتھوں سے بنایاہے،وہ انھیں کیافائدہ پہنچاسکتے ہیں۔آزر کےتین لڑکے ہوے: حاران، ابراہیم اور ناحور۔حاران سے لوط پیداہوے،جن کا ذکر بعد میں آئے گا۔حاران کی وفات اُر میں ہی ہوگئی۔ابراہیم کے چھوٹے بھائی ناحور کے بارہ بیٹے پیدا ہوے۔یہ سب لوگ اُر میں ہی رہ گئے،مگر آزر ابراہیم اور حاران کے لڑکے لوط کولےکر شام کے شہر حاران چلاگیااور وہیں اس کی وفات ہوگئی۔ (دیکھیے: بائبل -کتاب پیدایش: اا:۲۷)\nاس سے معلوم ہوتا ہے کہ ابراہیم اور ان کے والد آزر میں جو گفتگو ہوئی تھی وہ مقام حاران میں ہوئی ہوگی۔کیوں کہ تورات میں آیا ہے: اپنے باپ کے گھر چھوڑ کراس ملک میں چلاجا جو میں تجھے دکھاؤں گا۔ تجھےایک بڑی قوم بناؤں گا اور برکت دوں گا۔ (پیدایش: ۲ا:ا-۲)\nتورات سے معلوم ہوتا ہے کہ جب ابراہیم کے باپ کی عمر ۲۰۵سال ہوگئی توحاران میں ہی اس کی وفات ہوگئی لیکن وہ بت پرستی سے الگ نہیں ہوا۔ ابراہیم علیہ السلام کاخیال تھا کہ وہ بت پرستی سے رک جائے گا اور اس کی بخشش کےلیے االلہ تعالیٰ سے دعاے مغفرت کریں گے۔لیکن جب واضح ہوگیا کہ وہ بت پرستی سے باز نہیں آئے گا توابراہیم علیہ السلام نے اس سے علاحدگی اختیار کرلی۔ قرآن مجیدمیں ہے:﴿وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَٰهِيمَ لِأَبِيهِ إِلَّا عَن مَّوۡعِدَةࣲ وَعَدَهَآ إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُۥٓ أَنَّهُۥ عَدُوࣱّ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَٰهِيمَ لَأَوَّٰهٌ حَلِيمࣱ‏﴾ [التوبة: ۱۱۴] \"(ابراہیم)کااپنے باپ کے لیے دعائے مغفرت مانگنا وہ صرف وعدہ کے سبب سے تھا، جوانھوں نے اس سے وعدہ کرلیا تھا۔پھر جب ان پر یہ بات ظاہر ہوگئی کہ وہ االلہ کا دشمن ہے تووہ اس سے بالکل بے تعلق ہوگئے، واقعی ابراہیم علیہ السلام بڑے نرم دل اور بردبارتھے\"۔\nقرآن مجیدمیں ایک دوسرے مقام پر مذکور ہے: ﴿قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةࣱ فِيٓ إِبۡرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذۡ قَالُواْ لِقَوۡمِهِمۡ إِنَّا بُرَءَٰٓؤُاْ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ ٱلۡعَدَٰوَةُ وَٱلۡبَغۡضَآءُ أَبَدًا حَتَّىٰ تُؤۡمِنُواْ بِٱللَّهِ وَحۡدَهُۥٓ إِلَّا قَوۡلَ إِبۡرَٰهِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَآ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَيۡءࣲۖ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ﴾ [الممتحنة: ۴] \"(مسلمانو!)تمھارے لیے ابراہیم میں اور ان کے ساتھیوں میں بہترین نمونہ ہے،جب کہ ان سب نے اپنی قوم سے برملاکہہ دیا کہ ہم تم سے اور جن جن کی تم االلہ کے سوا عبادت کرتے ہوان سب سے بالکل بیزار ہیں۔ہم تمھارےعقائدکےمنکر ہیں، جب تک تم االلہ کی وحدانیت پر ایمان نہ لاؤ۔ہم میں تم میں ہمیشہ کے لیے بغض و عداوت ظاہر ہوگئی۔لیکن ابراہیم کی اتنی بات تو اپنے باپ سے ہوئی تھی کہ میں تمھارے لیے استغفار ضرور کروں گااور تمھارے لیے مجھے االلہ کے سامنے کسی چیز کااختیار کچھ بھی نہیں۔اے ہمارے رب!تجھی پر ہم نے بھروسہ کیا ہے اور تیری ہی طرف رجوع کرتے ہیں اور تیری ہی طرف لوٹناہے\"۔\nابراہیم علیہ السلام کی پاکیزہ سیرت ہمارے لیے ایک بہترین نمونہ ہے۔انھوں نے بت پرست والد کوبھی االلہ کے راستے میں ترک کردیا۔کیوں کہ شرک کرنے والا االلہ کا دشمن اور باغی ہے۔االلہ تعالیٰ نے شرک کوبہت بڑا ظلم قرار دیاہے۔ (لقمان:۳ا)","",{}],[33,"§ازواج مطہرات رضی اللہ عنہن\nعربی زبان میں نبی اکرم صلی اللہ علیہ وسلم کی بیویوں کو ازواج نبی کہتےہیں۔آپ کی بیویوں کومسلم معاشرے میں بہت اونچا اور خاص مقام حاصل ہے، جو امہات المومنین کے لقب سے مشہورہیں۔\n۱-قرآن مجیدنے بڑے واضح الفاظ میں یہ اعلان کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم کی بیویاں عام عورتوں کی طرح نہیں ہیں: ﴿يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدࣲ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضࣱ وَقُلۡنَ قَوۡلࣰ ا مَّعۡرُوفࣰ ا﴾ [الأحزاب: ۳۲] \"اے نبی کی ازواج! تم عام عورتوں کی طرح نہیں ہو، اگر تم اللہ کا خوف رکھو۔اس لیے تمھاری باتوں میں لوچ نہ ہو کہ وہ شخص جس کے دل میں مرض ہے،لالچ میں پڑ جائے۔تم عام انداز سے بات کرو\"۔\n۲-قرآن میں نبی اکرم صلی اللہ علیہ وسلم کی بیویوں کو یہ ہدایت دی گئی ہے: ﴿يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣰ ا﴾ [الأحزاب: ۳۰] \"اے نبی کی بیویو!تم میں سے جو بھی کھلی ہو‏ئی بے حیائی کا کام کرے گا،اسے دوہرا عذاب دیا جائے گا اور اللہ کے لیے یہ بہت آسان ہے\"۔\n۳-نبی اکرم صلی اللہ علیہ وسلم کی بیویاں مسلمانوں کے لیے ماں کےدرجے میں ہیں۔ قرآن کریم میں آیا ہے: ﴿ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفࣰ اۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورࣰ ا﴾ [الأحزاب: ۶] \"نبی مومنوں پر خود ان سے بھی زیادہ حق رکھنے والے ہیں اور نبی کی بیویاں مومنوں کی مائیں ہیں اور رشتہ دار کتاب اللہ کی رو سے بنسبت دوسرے مومنوں اور مہاجروں کے آپس میں زیادہ حق دار (ہاں) مگر یہ کہ تم اپنے دوستوں کے ساتھ حسن سلوک کرنا چاہو یہ حکم (الٰہی) میں لکھا ہے\"۔\n۴-اس لیے نبی اکرم صلی اللہ علیہ وسلم کی بیویوں سےشادی کرنا ہمیشہ کے لیےممنوع قراردیا گیا:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعࣰ ا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابࣲۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا﴾ [الأحزاب: ۵۳] \"اے ایمان والو! جب تک تمھیں اجازت نہ دی جائے تم بنی کے گھروں میں نہ جایا کرو کھانے کے لیے ایسے وقت میں اس کے پکنے کا انتظار کرتے رہو بل کہ جب بلایا جائے جاؤ اور جب کھا چکو نکل کھڑے ہو، وہیں باتوں میں مشغول نہ ہو جایا کرو، نبی کو تمھاری اس بات سے تکلیف ہوتی ہے، تو وہ لحاظ کر جاتے ہیں اور اللہ تعالیٰ (بیان) حق میں کسی کا لحاظ نہیں کرتا جب تم نبی کی بیویوں سے کوئی چیز طلب کرو تو تم پردے کے پیچھےسے طلب کرو۔تمھارے اور ان کے دلوں کے لیے کامل پاکیزگی یہی ہے۔ نہ تمھیں جائز ہے کہ تم رسول اللہ کو تکلیف دواور نہ تمھیں یہ حلال ہے کہ آپ کے بعد کسی وقت بھی آپ کی بیویوں سے نکاح کرو۔یاد رکھو اللہ کے نزدیک یہ بہت بڑا گناہ ہے\"۔\nتمھارے لیےیہ ہرگز مناسب نہیں ہےکہ اللہ کے رسول کو دکھ پہنچاؤ اور نہ تمھارے لیے یہ جائز ہےکہ ان کے بعد ان کی بیویوں سے شادی کرو۔بلاشبہ اللہ کی نظر میں یہ بہت بڑا گناہ ہے۔\nنبی اکرم صلی اللہ علیہ وسلم کی ازواج کاماں کے برابر ہونے کا مطلب یہ ہے کہ ان کی عزت و احترام کیا جائے۔لیکن ان سے پردہ کیا جائے گا۔اس طرح آپ صلی اللہ علیہ وسلم کی ازواج کے لیے دوسری شادی کرنا جائز نہیں تھا۔\nنبی اکرم صلی اللہ علیہ وسلم کی بارہ(۲ا) بیویاں تھیں۔ہندوؤں کی مذہبی کتابوں ویدوں اور پرانوں میں آخری رسول کے بارے میں بھی آیا ہےکہ ان کی بارہ(۲ا) بیویاں ہوں گی۔ تاریخ سےبھی ثابت ہوتا ہےکہ نبی اکرم صلی اللہ علیہ وسلم کے سوا بارہ(۲ا)بیویوں والا کوئی دوسرا رسول نہیں آیا۔\nان بارہ (۲ا) ازواج مطہرات عنہن کی تفصیل درج ذیل ہے:\n۱- ام المومنین خدیجہ بنت خویلدڤ:\nپچیس(۲۵)سال کی عمرمیں نبی اکرم صلی اللہ علیہ وسلم نے خدیجہڤسےشادی کی،جو چالیس سال کی بیوہ تھیں۔ان کےپہلےشوہرکا نام ابوہالہ اور دوسرے کا عتیق تھا۔وحی کی ابتدا کیسے ہوئی، اس کی تفصیل صحیح بخاری میں ام المومنین عائشہ ڤسےمروی ہے،جس میں خدیجہڤ کی سیرت پربھی اچھی روشنی پڑتی ہے، اس لیے یہاں پر پوری حدیث درج ذیل ہے: «أَوَّلُ مَا بُدِئَ به رَسُولُ اللَّه صلی اللہ علیہ وسلم مِنَ الْوَحْیِ الرُّؤْيَا الصَّالِحَةُ فِی النَّوْمِ، فَکَانَ لاَيَرَی رُؤْيَا إِلاَّ جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِليه الْخَلاَءُ، وَکَانَ يَخْلُو بِغَارِ حِرَاءٍ فَيَتَحَنَّثُ فِيه - وَهوَ التَّعَبُّدُ - الليالِیَ ذَوَاتِ الْعَدَدِ قَبْلَ أَنْ يَنْزِعَ إِلَی أَهلِه، وَيَتَزَوَّدُ لِذَلِکَ، ثُمَّ يَرْجِعُ إِلَی خَدِيجَةَ، فَيَتَزَوَّدُ لِمِثْلِها، حَتَّی جَاءَه الْحَقُّ وَهوَ فِي غَارِ حِرَاءٍ، فَجَاءَه الْمَلَکُ فَقَالَ: اقْرَأْ. قَالَ: «مَا أَنَا بِقَارِئٍ». قَالَ: «فَأَخَذَنِي فَغَطَّنِي حَتَّی بَلَغَ مِنِّي الْجَهدَ، ثُمَّ أَرْسَلَنِي فَقَالَ: اقْرَأْ. قُلْتُ: مَا أَنَا بِقَارِئٍ. فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّی بَلَغَ مِنِّی الْجَهدَ، ثُمَّ أَرْسَلَنِي فَقَالَ: اقْرَأْ. فَقُلْتُ: مَا أَنَا بِقَارِئٍ. فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ، ثُمَّ أَرْسَلَنِي فَقَالَ:﴿ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ﴾ [العلق: ۱-۵]فَرَجَعَ بہا رَسُولُ اللَّه صلی اللہ علیہ وسلم يَرْجُفُ فُؤَادُه، فَدَخَلَ عَلَی خَدِيجَةَ بِنْتِ خُوَيْلِدٍ رضی اللہ عنہا فَقَالَ: «زَمِّلُونِي زَمِّلُونِي». فَزَمَّلُوه حَتَّی ذَهبَ عَنْه الرَّوْعُ، فَقَالَ لِخَدِيجَةَ وَأَخْبَرَها الْخَبَرَ: «لَقَدْ خَشِيتُ عَلَی نَفْسِي». فَقَالَتْ خَدِيجَةُ: کَلاَّ وَاللَّه مَا يُخْزِيکَ اللَّه أَبَدًا، إِنَّکَ لَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْکَلَّ، وَتَکْسِبُ الْمَعْدُومَ، وَتَقْرِئ الضَّيْفَ، وَتُعِينُ عَلَی نَوَائِبِ الْحَقِّ. فَانْطَلَقَتْ به خَدِيجَةُ حَتَّی أَتَتْ به وَرَقَةَ بْنَ نَوْفَلِ ابْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّی ابْنَ عَمِّ خَدِيجَةَ -وَکَانَ امْرَأً تَنَصَّرَ فِي الْجَاهلیةِ، وَکَانَ يَکْتُبُ الْکِتَابَ الْعِبْرَانِيَّ، فَيَکْتُبُ مِنَ الإِنْجِيلِ بِالْعِبْرَانِيَّةِ مَا شَاءَ اللَّه أَنْ يَکْتُبَ، وَکَانَ شَيْخًا کَبِيرًا قَدْ عَمِيَ- فَقَالَتْ لَه خَدِيجَةُ: يَا ابْنَ عَمِّ! اسْمَعْ مِنَ ابْنِ أَخِيکَ. فَقَالَ لَه وَرَقَةُ: يَا ابْنَ أَخِي! مَاذَا تَرَی؟ فَأَخْبَرَه رَسُولُ اللَّه صلی اللہ علیہ وسلم خَبَرَ مَا رَأَی. فَقَالَ لَه وَرَقَةُ: هذَا النَّامُوسُ الَّذِی نَزَّلَ اللَّه عَلَی مُوسَی علیہ السلام يَا ليتَنِی فِيها جَذَعًا، ليتَنِي أَکُونُ حَيًّا إِذْ يُخْرِجُکَ قَوْمُکَ. فَقَالَ رَسُولُ اللَّه صلی اللہ علیہ وسلم : «أَوَمُخْرِجِيَّ همْ». قَالَ: نَعَمْ، لَمْ يَأْتِ رَجُلٌ قَطُّ بِمِثْلِ مَا جِئْتَ به إِلاَّ عُودِيَ، وَإِنْ يُدْرِکْنِي يَوْمُکَ أَنْصُرْکَ نَصْرًا مُؤَزَّرًا. ثُمَّ لَمْ يَنْشَبْ وَرَقَةُ أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْيُ». (صحیح البخاری: ۳) \"سب سے پہلے وحی کی ابتدا سچے خوابوں سے ہوئی۔ آپ نیند میں کوئی بھی خواب دیکھتے تو صبح کو واضح طور سے اس خواب کو واقعی صورت میں دیکھ لیتے۔ پھر آپ کے لیے تنہائی محبوب بنادی گئی، آپ غارحراء میں تنہائی اختیار کرتے، وہاں کئی کئی راتیں عبادت کرتے پھر گھر آتے اور توشہ لےجاتے،یہاں تک کہ ایک دن حق ( وحی) کا معاملہ ہوا، فرشتہ آیا اور بولا: آپ پڑھیے! آپ نے کہا: میں پڑھنا نہیں جانتا۔ اس پر فرشتے نے آپ کو پکڑ کر بھینچا، پھر چھوڑکر کہا: پڑھیے! پھر میں نے کہا: میں پڑھنا نہیں جانتا، پھر فرشتہ نے مجھ کو پکڑ کر انتہائی زور سے بھینچااور کہا: پڑھیے\"۔ اس طرح تین بار کیا، پھر کہا: ﴿ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ﴾ [العلق: ۱-۳] \" پڑھ اپنے رب کے نام سے جس نے پیدا کیا جس نے انسان کو خون کے لوتھڑے سے پیدا کیا۔تو پڑھتا رہ تیرا رب بڑے کرم والا ہے \"۔آپ ان آیات کے ساتھ اس حال میں لوٹے کہ آپ کا دل کانپ رہا تھا، خدیجہ کے پاس آئے اور فرمایا: مجھے کمبل اڑھاؤ، مجھے کمبل اڑھاؤ، انھوں نے کمبل اوڑھا دیا یہاں تک کہ آپ کا خوف چلا گیا۔ آپ نے ان کو پوری بات بتائی اور یہ کہا کہ مجھے اپنی جان کا خطرہ ہے۔ خدیجہ نے کہا: اللہ کی قسم ایسا ہرگز نہ ہوگا، اللہ آپ کو ہرگز رسوا نہیں کرے گا، کیوں کہ آپ رشتوں کو جوڑتے ہیں،امانتوں میں خیانت نہیں کرتے۔یتیموں اور بے سہاروں کوسہارا دیتے ہیں۔مہمان کی خاطرمدارات کرتے ہیں۔بھلائیوں کے کاموں میں مدد کرتے ہیں۔بھلا اللہ آپ کو کیسے برباد ہونے دے گا۔پھر آپ صلی اللہ علیہ وسلم کو لے کر اپنے چچا زادبھائی ورقہ بن نوفل کے پاس گئیں جنھوں نے نصرانی مذہب اپنا لیا تھااورجو عبرانی زبان میں انجیل کا مطالعہ کرتے تھے۔جب خدیجہ نے ان سے بتایا کہ ان کےساتھ ایسا ایسا ہوا ہے تو ورقہ بول اٹھے:یہ تو وہی ہےجو موسیٰ علیہ السلام کے پاس آیا تھا۔کاش میں اس وقت تک زندہ رہتا جب تمھاری قوم تمھیں یہاں سے نکال دے گی۔اللہ کے رسول صلی اللہ علیہ وسلم نے کہا:کیا یہ لوگ مجھے یہاں سے نکال دیں گے؟ورقہ نے کہا:ہاں،تمھاری طرح جو بھی آیا،اس کو اس کی قوم نے اُسےتکلیفیں پہنچائیں۔اگر میں اس وقت تک زندہ رہا تو تمھاری مدد کروں گا۔لیکن کچھ ہی دنوں بعد ان کا انتقال ہوگیا اور وحی کا سلسلہ (عارضی طور پر) منقطع ہوگیا\"۔\nایک کے سواآپ کی ساری اولاد خدیجہ ڤ ہی سےہیں۔جن کے اسمائے گرامی ذیل ہیں:لڑکوں میں قاسم، عبدااللہ(ان کا لقب طیب وطاہر تھا)۔(دونوں کا انتقال بچپن ہی میں ہوگیا تھا)۔لڑکیوں میں رقیہ،زینب،ام کلثوم اور فاطمہ۔ہجرت سےتین سال پہلے خدیجہڤ کا انتقال ہوگیا۔ان کی بہت ساری خوبیوں میں سے ایک خوبی کابیان ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں آئی ہے: «أَتَی جِبْرِيلُ النبی صلی اللہ علیہ وسلم فَقَالَ: يَا رَسُولَ اللَّه! هذِه خَدِيجَةُ قَدْ أَتَتْ مَعَها إِنَاءٌ فِيه إِدَامٌ أَوْ طَعَامٌ أَوْ شَرَابٌ، فَإِذَا هيَ أَتَتْکَ فَاقْرَأْ عَليها السَّلاَمَ مِنْ رَبها وَمِنِّي، وَبَشِّرْها بِبَيْتٍ فِي الْجَنَّةِ مِنْ قَصَبٍ، لاَصَخَبَ فِيه وَلاَ نَصَبَ». (صحیح البخاری: ۳۸۲۰، وصحیح مسلم: ۲۴۳۲) \"ایک بار جبرئیل علیہ السلام آئے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سےعرض کیا: اےمحمد!یہ خدیجہ ہیں، آپ کے پاس آرہی ہیں ان کے ساتھ ایک برتن ہے جس میں سالن یا کوئی کھانا یا کوئی مشروب ہے، جب یہ آپ کے پاس آئیں تو ان کے رب اور میری جانب سے ان کو سلام پہنچانااور ان کو یہ بشارت دینا کہ جنت میں ان کے لیے ایک ایسا گھر ہے جس میں نہ کسی طرح کا شور وغل ہوگا،نہ کبھی ان کو اس میں تکان ہوگی\"۔\n۲- ام المومنین سودہ بنت زمعہڤ:\nام المومنین سودہ بنت زمعہڤکےپہلے شوہر کا نام سکران بن عمروتھا۔ دونوں اسلام قبول کرنے کے بعد حبشہ ہجرت کر گئے۔سکران کا وہیں انتقال ہوگیا۔ام المومنین خدیجہڤکابھی انتقال ہوگیا۔ دس(۰ا) سن نبوی میں نبی اکرم صلی اللہ علیہ وسلم نے سودہڤسےشادی کر لی۔ان کا انتقال ۵۴ھ میں ہوا۔ (طبقات ابن سعد:۸:۵۳)۔بعض لوگوں کا خیال ہے کہ ان کا انتقال عمر رضی اللہ عنہ کی خلافت کے آخری دنوں میں ہوا۔ (التاریخ الکبیر للبخاری: ۴۹-۵۰)\n۳- ام المو منین عائشہ بنت ابوبکر رضی اللہ عنہما :\nنبی اکرم صلی اللہ علیہ وسلم نے جن عورتوں سےشادی کی،ام المومنین عائشہڤ کے سواسب بیوہ یا مطلقہ تھیں۔ آپ ان سےبہت محبت کرتے تھے۔ انس بن مالک رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: «فَضْلُ عَائِشَةَ عَلَی النِّسَاءِ کَفَضْلِ الثَّرِيدِ عَلَی سَائِرِ الطَّعَامِ». (صحیح البخاری: ۳۷۷۰، صحیح مسلم: ۲۴۴۶) \"عائشہ کی فضیلت وبرتری تمام عورتوں پر ایسی ہےجیسے ثرید نامی کھانا سب کھانوں سے بہتر ہے\"۔\nثرید نامی کھانا آج بھی عربوں میں مشہور ہے۔یہ کھجوراور گیہوں کو آپس میں پیس کر گھی میں پکایا جاتاہے۔\nام المومنین عائشہڤمسلم دنیا میں نہایت ہی مشہور خاتون ہیں،جن کے ذریعےسےہم تک بہت ساری حدیثیں پہنچی ہیں۔احادیث بیان کرنے والے دس بڑےعظیم صحابہ ٔ کرام میں سے آپ بھی ایک ہیں۔ان کی حدیثوں کی تعداد ۰ا۲۲بتائی جاتی ہے۔ام المومنین عائشہڤکی گود میں نبی اکرم صلی اللہ علیہ وسلم کا انتقال ہوا۔ان کے گھرمیں نبی اکرم صلی اللہ علیہ وسلم کو دفن کیا گیا۔ام المومنین عائشہڤنےاحادیث کی تبلیغ واشاعت میں بڑھ چڑھ کرحصہ لیا۔خاص طور سے وہ احادیث جن کا تعلق نبی اکرم صلی اللہ علیہ وسلم کی گھر یلو زندگی سےتھا۔آپ کا اپنے گھروالوں کےساتھ رویہ کیسا تھا،خواہ وہ تعلیم ونصیحت کےبارے میں ہویا ازدواجی زندگی کے بارے میں۔آپ نے نبی اکرم صلی اللہ علیہ وسلم کی زندگی کے ایک ایک پہلو کو تفصیل سے بیان کیا ہے،جو مسلمانوں کے لیے ایک اعلیٰ نمونہ ہے۔۵۷ھ میں انتقال ہوا۔مقبرۃالبقیع(مدینہ منورہ)میں تدفین ہوئی۔\n۴-ام المومنین حفصہ بنت عمر رضی اللہ عنہما :\nام المومنین حفصہ بنت عمر رضی اللہ عنہما کے پہلے شوہرخنیس بن حذافہ رضی اللہ عنہ،غزوہ ٔ بدر کےشہداء میں سے تھے۔ایک بارنبی اکرم صلی اللہ علیہ وسلم نے کسی وجہ سے حفصہڤ کو طلاق دے دی تو جبرئیل علیہ السلام نے آکرکہا کہ آپ طلاق سے رجوع کرلیں،کیوں کہ حفصہ بہت زیادہ روزہ دار،تہجدپڑھنے والی خاتون ہیں۔ یہ جنت میں بھی آپ کی بیوی رہیں گی۔ (سنن ابی داود: ۲۲۸۲،سنن نسائی: ۶:۳ا۲)\nحفصہ ڤکا انتقال سن ا۴ھ میں ہوا۔\n۵- ام المومنین زينب بنت خزیمہ بن حارثڤ:\nام المومنین زینب بنت خزیمہ بن حارثڤکے پہلے شوہر عبیدہ بن حارث رضی اللہ عنہ، غزوۂ بدر کے شہداء میں سےتھے۔ان کےانتقال کے بعد زینب ڤکی شادی نبی اکرم صلی اللہ علیہ وسلم سے ہوئی۔لیکن شادی کے چار ماہ بعد سن۴ھ میں انتقال کرگئیں۔\n۶-ام المومنین ام سلمہ ہندبنت ابی امیہڤ:\nام المومنین ام سلمہ ہندبنت ابی امیہڤ ابو سلمہ بن عبد الاسد رضی اللہ عنہ کی بیوی تھیں۔ان کے انتقال کے بعدسن ۴ھ میں ان کی شادی نبی اکرم صلی اللہ علیہ وسلم سے ہوئی۔وہ بیوہ اورتین بچوں کی ماں تھیں۔آپ ان اور اس طرح کی بیوہ عورتوں سےشادی کر کے ان کی مدداوراس کےذریعےسے ان کے خاندانوں میں اسلام کی تبلیغ کرنا چاہتےتھے۔ کیوں کہ عرب کے لوگ اپنے کنبہ میں،جس سے شادی کرتے تھے،اس کی پوری مدد کرتے تھے۔اس لیے آپ کا شادی کرنا بھی اسلام کے مفاد اور اس کی تبلیغ وتوسیع کے لیے تھا۔ام سلمہ ڤ کا انتقال سن ۵۹ھ میں ہوا اورمقبرۃ البقیع میں دفن کیا گیا۔\n۷-ام المومنین زينب بنت جحشڤ:\nام المومنین زینب بنت جحشڤنبی اکرم صلی اللہ علیہ وسلم کے منہ بولے بیٹے زید کی بیوی تھیں۔لیکن ان کاآپس میں ایک دوسرے کے ساتھ نباہ دشوار ہوگیا تھا،جس کی وجہ سے زید نےان کو طلاق دےدی۔ عرب روایت کے مطابق کوئی شخص اپنے منہ بولے بیٹے کی بیوہ یامطلقہ سے شادی نہیں کرسکتا تھا۔منہ بولے بیٹے کو اس کےاپنے بیٹے کے برابر سمجھا جاتا تھا،لیکن اسلام کو اس روایت کو ختم کرنا تھا۔اس لیے اللہ کےحکم سے نبی اکرم صلی اللہ علیہ وسلم نے زینبڤسے شادی کر لی۔ ابتدا میں اس کی کافی مخالفت کی گئی۔ لیکن جب اللہ تعالیٰ کی جانب سےدرج ذیل آیت نازل ہوئی تو یہ مخالفت ختم ہوگئی اور منہ بولے بیٹےکی بیوہ سے شادی کرنا اسلام میں جائزکردیا گیا: ﴿قَضَىٰ زَيۡدࣱ مِّنۡهَا وَطَرࣰ ا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجࣱ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرࣰ اۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰ﴾ [الأحزاب: ۳۷] \" پس جب کہ زید نے اس عورت سے اپنی غرض پوری کرلی ہم نے اسے تیرے نکاح میں دے دیا تاکہ مسلمانوں پر اپنے لے پالک بیویوں کے بارے میں کسی طرح تنگی نہ رہے جب کہ وہ اپنی غرض ان سے پوری کرلیں اللہ کا (یہ) حکم تو ہو کر ہی رہنے والا ہے \"۔\nاس لیے زینبڤاس بات پر فخر کیا کرتی اور کہتی تھیں کہ تم لوگوں کی شادیاں تمھارے گھر والوں نے کروائیں، لیکن میری شادی اللہ تعالیٰ نے کرائی۔\nایک صحیح حدیث میں آیا ہے کہ ازواج مطہرات رضی اللہ عنہن میں سب سے زیادہ خیرات کرنے والی سب سے پہلے مجھ سے ملے گی۔ام المومنین عائشہڤ کہا کرتی تھیں کہ زینب میں دو خوبیاں تھیں:ایک یہ کہ ان کی شادی اللہ تعالی نے کرائی، دوسری یہ کہ نبی اکرم صلی اللہ علیہ وسلم کا فرمان ہے کہ زیادہ خیرات کرنے والی سب سے پہلے مجھ سے ملے گی اور وہ یہی زینب تھیں جن کا انتقال سن ۲۰ھ میں ہوا۔\n۸- ام المومنین جويریہ بنت حارث ڤ:\nام المومنین جویریہ بنت حارث ڤکے پہلے شوہر کا نام صفوان بن ذی شکرتھا۔نبی اکرم صلی اللہ علیہ وسلم نے سن ۶ھ میں ان سے شادی کی۔ان کا انتقال سن ۵۶ھ میں ہوا۔\n۹- ام المومنین ام حبیبہ بنت ابی سفیان رضی اللہ عنہما :\nام المومنین ام حبیبہ بنت ابی سفیان رضی اللہ عنہما کےپہلےشوہر کا نام عبید اللہ بن جحش تھا۔دونوں مسلمان ہونےکے بعد ہجرت کرکے حبشہ چلے گئےلیکن عبید اللہ وہا ں جاکر نصرانی ہوگیا اور شراب پینے لگا۔ حبشہ ہی میں اس کا انتقال ہوگیا۔حبشہ کےبادشاہ نجاشی نے۴۰۰دینارمہر کے بدلےنبی اکرم صلی اللہ علیہ وسلم کی ام حبیبہ سےشادی کردی۔جب اس کی اطلاع ام حبیبہ کے والد ابوسفیان کو دی گئی،جنھوں نے ابھی تک اسلام قبول نہیں کیا تھا تو انھوں نے کہا: وہ تو ایسا سردار ہے جس کا نام کاٹا نہیں جاسکتا۔ ایسی عظیم شخصیت میری لڑکی سے شادی کرنے کے لائق ہے۔ابو سفیان، مکہ کے سردار تھےاور اسلام مخالف گروہ کےلیڈر بھی،لیکن نبی اکرم صلی اللہ علیہ وسلم کی عظمت سے انکار نہیں کرسکے۔ام حبیبہڤکا انتقال سن۴۴ھ میں ہوا۔ اس وقت ان کے بھائی معاویہ رضی اللہ عنہ مسلمانوں کے خلیفہ تھے۔\n۰ا- ام المومنین صفیہ بنت حی بن اخطبڤ:\nام المومنین صفیہ بنت حی بن اخطبڤیہودیوں کے سردار حی بن اخطب کی صاحبزادی تھیں۔ غزوۂ خیبرمیں یہ لونڈی بنا کر لائی گئی تھیں۔ان کے پہلے شوہر کا نام کنانہ تھاجو کسی جنگ میں مارا گیا تھا۔اس کے بعد نبی اکرم صلی اللہ علیہ وسلم نے ان سے شادی کی۔یہ بڑی عقل مند اور سوجھ بوجھ والی خاتون ثابت ہوئیں۔انس بن مالک رضی اللہ عنہ کہتے ہیں: «بَلَغَ صَفِيَّةَ أَنَّ حَفْصَةَ قَالَتْ: إِنِّی ابْنَةُ يَهودِيٍّ. فَبَکَتْ، فَدَخَلَ عَليها النبی صلی اللہ علیہ وسلم وَهيَ تَبْکِي فَقَالَ: «مَا شَأْنُکِ». فَقَالَتْ: قَالَتْ لی حَفْصَةُ: إِنِّي ابْنَةُ يَهودِيٍّ. فَقَالَ النبی صلی اللہ علیہ وسلم : «إِنَّکِ ابْنَةُ نبی وَإِنَّ عَمَّکِ لَنبي وَإِنَّکِ لَتَحْتَ نبی فَفِيمَ تَفْخَرُ عَليکِ». فَقَالَ: «اتَّقِي اللَّه يَا حَفْصَةُ». (مسند أحمد: ۳/۱۳۶، ۱۲۷۲۷)\n\"ایک بار نبی اکرم صلی اللہ علیہ وسلم کی اہلیہ حفصہ نے ان کو طعنہ دیا کہ تم یہودی کی بیٹی ہو۔جس کی وجہ سے وہ بہت غمزدہ ہوگئیں اور رونے لگیں۔جب نبی اکرم صلی اللہ علیہ وسلم کو اس کی اطلاع ملی تو آپ نے صفیہ کومخاطب کرتے ہوے کہا:تم نبی کی بیٹی ہو۔ تمھارے چچا نبی تھے۔ اب تم نبی کی بیوی ہو۔ پھر یہ تمھارے مقابلے میں کس طرح فخر کرسکتی ہیں۔ حفصہ! تمھیں چاہیے کہ اللہ سے ڈرو\"۔\nیہ حی بن اخطب کی بیٹی تھیں جو ہارون علیہ السلام کی نسل سے تھا۔ان کاانتقال سن ۵۰ھ میں ہوا اور انھیں بقیع نامی قبرستان میں دفن کیا گیا۔\nاا- ام المومنین میمونہ بنت حارث بن حزنڤ:\nام المومنین میمونہ بنت حارثڤ کی قبول اسلام سے پہلے پہلی شادی مسعود بن عمروثقفی سے ہوئی۔ طلاق کے بعد ان کی شادی ابو رحم بن عبدالعزیٰ سے ہوئی،جس کا انتقال ہوگیا۔۷ھ میں ان کی نبی اکرم صلی اللہ علیہ وسلم سےشادی ہوئی۔ ۸۰سال کی عمر میں سن ا۶ھ میں ان کا انتقال ہوااور مکہ کے نزدیک سَرِف مقام پر ان کو دفن کیا گیا۔\n۲ا-ماریہ قبطیہ بنت شمعون مصریڤ:\nماریہ قبطیہ بنت شمعون مصریڤایک بڑی خوبصورت خاتون تھیں۔اسکندریہ کے گورنر نے انھیں نبی اکرم صلی اللہ علیہ وسلم کو تحفہ میں بھیجا۔آپ کو ان سے بڑا پیارتھا۔کیوں کہ یہ آپ کے صاحبزادے ابراہیم کی والدہ تھیں جن کا بچپن میں ہی انتقال ہوگیا تھا۔ان کی وفات سن۴اھ میں ہوئی اور انھیں بقیع قبرستان میں دفن کیا گیا۔\nیہ نبی اکرم صلی اللہ علیہ وسلم کی بارہ ازواج مطہرات کا مختصر تذکرہ ہے۔ریحانہ بنت زید نامی ایک بیوی کا نام بھی آتا ہے،جو بنوقریظہ نامی یہودی خاندان سےتھیں۔بنو قریظہ کی جنگ کے بعد یہ آپ کے پاس آگئیں اور اسلام قبول کرلیا۔اس کےبعد آپ نے ان سے شادی کی۔سن۰اھ میں ان کا انتقال ہوگیا۔کچھ اور ازواج کا ذکر بھی تاریخ کی کتابوں میں آتا ہے لیکن آپ کے گھر آنےسے پہلے ہی ان کو یا تو طلاق ہوگئی یا پھر ان کا انتقال ہوگیا۔جیسے،عالیہ بنت جمعان،امیمہ بنت نعمان،خولہ بنت ہزیل،عمرہ بنت زید وغیرہ۔\nایک سےزیادہ شادی کرنا قدیم روایت رہی ہے۔بائبل کےمطابق زیادہ تر انبیا ایک سےزیادہ عورتوں کے شوہر تھے۔عیسیٰ علیہ السلام چونکہ شادی ہی نہ کرسکے، اس لیےنہ تو پادری اور نہ عیسائی راہبائیں(ننیں)شادی کرتی ہیں۔ان کا عقیدہ ہےکہ قیامت کے بعدیہ سب یسوع مسیح سے شادی کریں گی۔گویا جس نبی نے زندگی بھر شادی نہیں کی، وہ دوسری زندگی میں سیکڑوں عورتوں کا شوہر بنے گا۔اس بارے میں اسلام نے کچھ نہیں بتایا ہے۔\nاب اگر ہم سماجی نقطۂ نظر سے دیکھیں تو ایک سے زیادہ شادی ایک معاشرتی ضرورت ہے۔کبھی خود انسان کی ضرورت ہے تو کبھی سماج کی۔اسی لیے دیکھا یہ گیا ہے کہ جس سماج اور مذہب میں ایک سے زیادہ شادی پر پابندی ہے،ان میں بدکاری زیادہ پھیلتی ہے۔کیوں کہ انسان جب اپنی فطری خواہشوں کو جائزطریقے سے پوری نہیں کرپاتا تو غلط راستےاپناتا ہے۔اگر کسی ایسے معاشرےکا مطالعہ کریں جس میں بیواؤں کی شادی نہیں ہوتی تو معلوم ہوگا کہ مذہب کے نام پر ان کی عصمت و عفت کو کس طرح پامال کیا جاتاہے۔ مذہبی مقامات میں ان کے ساتھ کیسا سلوک ہوتا ہے۔اسی طرح ایسے کئی سماج بھی پائے جاتےہیں جہاں عورتوں کی تعدادمردوں سے زیادہ ہوتی ہے۔معاشرتی پابندیاں بھی ایسی ہیں کہ ایک باپ،جس کے۴-۶بیٹیاں ہوجائیں،آسانی کے ساتھ ان کی شادی نہیں کرسکتا۔ان حالات میں ایک سے زیادہ شادی ہی صحیح طریقہ ہے۔کیوں کہ تعددازدواج کی صورت میں لڑکیوں سے کچھ لیا نہیں جاتا، بلکہ لڑکیوں کو مہر کی شکل میں رقم دی جاتی ہے اوراس سے بڑھ کر مرداپنی ایک یا ایک سے زائد بیویوں کی پوری طرح سرپرستی اور کفالت کرتاہےحتی کہ بیوہ عورتوں کی اولاد کی بھی پرورش کرتاہے۔\nان حالات کی وجہ سےاسلام نے ایک سے زیادہ شادی کی اجازت دی ہے۔لیکن اس کے لیے بھی کچھ قوانین وضع کیےگئے ہیں۔ان میں سے ایک یہ ہے کہ کوئی شخص ایک ہی وقت میں چار سے زیادہ شادی نہیں کرسکتا۔ (النساء: ۳)۔ دوسرایہ کہ سب کے ساتھ انصاف کرنا لازمی ہے۔(النساء:۳)۔جو کھانے پینےاور رہنے سہنے سے لے کر رات گزارنے تک سبھی معاملات میں کرنا ہوگا اور اگر کوئی شخص اپنے اندر اس کی استطاعت نہیں رکھا تو پھر اس کے لیے یہی بہتر ہے کہ ایک ہی عورت کے ساتھ زندگی گزارے۔کیوں کہ بیویوں میں انصاف نہ کرنے سےسماج کی اصلاح نہیں ہوگی،بلکہ سماج میں فساد پھیلےگا جس سے ایک سے زائد شادی کا مقصد فوت ہوجاتا ہے۔","",{}],[34,"§اسباط\nاسباط سبط کی جمع ہے۔اس کے معنیٰ خاندان کے ہیں۔ قرآن مجیدمیں یعقوب علیہ السلام کی اولاد کو اسباط کہا گیا ہے: ﴿إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحࣲ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورࣰ ا﴾ [النساء: ۱۶۳] \"(اے محمد!)ہم نے آپ کی طرف اسی طرح وحی بھیجی ہے، جس طرح نوح اور ان سے پہلےکےنبیوں کی طرف بھیجی تھی۔ ابراہیم، اسماعیل، اسحاق، یعقوب اور اولادیعقوب، عیسیٰ، ایوب، یونس، ہارون اورسلیمان کی طرف بھی ہم نے وحی بھیجی تھی اور داودکو ہم نے زبور بھی عنایت کی تھی\"۔(اسی طرح ملاحظہ کریں: سورہ بقرہ : ۱۳۶،آل عمران : ۸۴)\nپھراس کا استعمال یہودیوں کے خاندان کے معنیٰ میں ہونے لگا،جس طرح عربوں کے لیے قبیلہ کالفظ استعمال ہوتا ہے۔\nقرآن مجیدنےسورہ الاعراف آیت ۵۹ا-۶۰ا میں اسی جانب اشارہ کیا ہے۔ موسیٰ کی قوم میں ایک گروہ ایسا ہے جو حق کے مطابق ہدایت کرتا ہے اور اس کے مطابق انصاف بھی کرتا ہے۔ ہم نے ان کو بارہ خاندان میں تقسیم کرکے ان کے کئی گروہ بنادیے تھے۔\nبائبل میں بھی یعقوب علیہ السلام کی اولاد کو اسباط کہاگیاہے، جو درج ذیل ہیں: ا-أشیر، ۲- بنیامین، ۳-جاد، ۴-دان، ۵۔روبین، ۶- زبولون، ۷-شمعون، ۸-نفتالی، ۹- یساکر، ۰ا-یہودا۔\nمذکور بالا دس تو یعقوب علیہ السلام کی اولادہیں،باقی دو یعقوب کے پوتے،یوسف کی اولاد:۱۱- عفرایم ۱۲- اورمنشی ہیں،ان کواسباط کہا جاتاہے۔جب کہ یوسف اورلاوی بھی اولادیعقوب ہیں، لیکن ان کواسباط نہیں کہتے۔موسیٰ بن عمران کے وصی یوشع بن نون نے اسباط کے فلسطین کی مقدس آراضی تقسیم کی اورلاوی بن یعقوب کی اولاد کوہیکل(عبادت خانہ)کا عابد(پجاری)متعین کیا گیا۔یہ بارہ اسباط سلیمان علیہ السلام کےزمانے تک مل جل کر رہتےتھے۔ہرسبط کا ایک سردار ہوتا تھا۔لیکن سلیمان علیہ السلام کی وفات کےبعد یہ سب آپس میں لڑپڑے اور بنی اسرائیل کی حکومت دو حصوں میں منقسم ہوگئی۔\nبنی اسرائیل کے بارہ اسباط کی طرح عیسیٰ علیہ السلام نےبھی اپنےاحکام اور تعلیمات کوبنی اسرائیل تک پہنچانے کے لیے بارہ سفیرمقررکیے۔یہ اس بات کا ثبوت ہے کہ عیسیٰ علیہ السلام کی دعوت صرف یہودیوں کے لیے مخصوص تھی نہ کہ سارے عالم کے لیے۔","",{}],[35,"§اسحاق علیہ السلام\nاسحاق علیہ السلام ابراہیم علیہ السلام کےدوسرے صاحبزادےتھے۔ ان کی پیدایش کی خوش خبری االلہ تعالیٰ نے اس طرح دی:﴿وَٱمۡرَأَتُهُۥ قَآئِمَةࣱ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزࣱ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبࣱ قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدࣱ مَّجِيدࣱ‏﴾ [ہود: ۷۱-۷۳] \"(اس کی بیوی جوکھڑی ہوئی تھی وہ ہنس پڑی)تو ہم نےاسے اسحاق کی اور اسحاق کے پیچھےیعقوب کی خوش خبری دی۔ وہ کہنے لگی: ہائے میری کم بختی! میرے ہاں اولادکیسےہوسکتی ہےمیں خودبڑھیا اور یہ میرا شوہربھی بہت بڑی عمر کا ہے۔یہ یقیناً بڑی عجیب بات ہے۔ فرشتوں نےکہا :کیاتوااللہ کی قدرت سے تعجب کررہی ہے؟ تم پر اے اس گھر کے لوگو! االلہ کی رحمت اور اس کی برکتیں نازل ہوں،بےشک االلہ حمدوثناکا سزاواراور بڑی شان والاہے\"۔\nابراہیم علیہ السلام کی دوسری بیوی سارہ کواولاد کی خوش خبری پراس لیےتعجب ہوا کہ وہ بانجھ تھیں۔ان کی عمر نوے سال اور ان کے شوہر کی عمر سوسال ہوچکی تھی۔اس لیے جب ان کوبچے کی پیدایش کی خوش خبری دی گئی تووہ تعجب میں پڑگئیں۔ ایک دوسری بات یہ بھی ہے کہ اس عمر میں ولادت کے سبب عام طور پرعورتوں کوشرم آتی ہےکہ دوسری عورتیں کیا کہیں گی۔اس وجہ سے شرم سے وہ اپنا منہ پیٹنے لگیں۔\nاسحاق علیہ السلام کوبھی االلہ تعالیٰ نے نبوت سے نوازا۔ قرآن کریم میں اس کواس طرح بیان کیاگیاہے: ﴿وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيࣰّ ا مِّنَ ٱلصَّٰلِحِينَ﴾ [الصافات: ۱۱۲] \"اورہم نے اس کو(ابراہیم کو)اسحاق نبی کی بشارت دی جو صالح لوگوں میں سے ہوگا\"۔\nجب اسحاق سینتیس(۳۷) سال کے ہوے توان کی والدہ سارہ کی وفات ہوگئی۔ان کوابراہیم علیہ السلام نے مکفیلہ والی زمین کے غار میں دفن کیا۔ (پیدایش: ۲۳:۹ا)یہ ہبرون میں ہےاور اب اس کو آل خلیل کےنام سےموسوم کیاجاتاہے۔یہ جگہ بیت المقدس سےانیس(۹ا) اور بیت اللحم سےتیرہ (۳ا) میل کی دوری پرہے۔\nاسحاق علیہ السلام سنہ ۲۲۳۵ ق م میں ہبرون نامی مقام پر پیدا ہوے،جب وہ چالیس سال کے ہوگئے تو ابراہیم علیہ السلام نےاپنی قوم حاران سے ان کے لیے ایک بیوی منگوائی (پیدایش: ۲۴:۴) شادی کےبیس سال بعد ان کے یہاں جڑواں لڑکے پیداہوے۔ایک کا نام عیسواور دوسرے کایعقوب رکھا گیا۔ (پیدایش: ۲۵:ا۲-۲۶) جب اسحاق علیہ السلام کی عمر پچھتر(۷۵) سال کی ہوگئی تو ان کے والد ابراہیم علیہ السلام کی وفات ہوگئی۔انھوں نے ابراہیم علیہ السلام کواپنی ماں سارہ کےقریب دفن کردیا۔ جب ملک میں قحط سالی آگئی تو وہ شہرجرارچلے گئے،وہاں کابادشاہ ابی ملک نے ان کوبہت ساری بکریاں اور اونٹ دیے اور انھوں نے اس کے لیے دعائیں کیں۔\nاسحاق علیہ السلام کے دوسرے بیٹے یعقوب کواسرائیل بھی کہتے ہیں اور ان کی اولاد سےجوقوم پھیلی اسے بنی اسرائیل کہاجاتاہے۔ اسحاق نےجرار شہرسے نکل کر اپنی اولاد کے ساتھ ایک مقام بئرسبع میں سکونت اختیار کی،یہ جگہ ہبرون سے جنوب کی طرف اٹھائیس(۲۸)میل کی مسافت پر ہے۔وہیں ۸۰ سال کی عمرمیں ان کی وفات ہوگئی اور ان کواپنے والد ابراہیم اور والدہ سارہ کے قریب ہی دفن کیا گیا۔\nتورات میں یہ بھی تحریف ہوگئی ہےکہ ابراہیم علیہ السلام نے جس بیٹےکوقربان کیا تھا اس کانام اسحاق تھا۔جب کہ خودتورات میں ہےکہ اپنے اکلوتےبیٹےاسحاق جس کوتوبے حد پیارکرتاہے کولے کر موریا ملک جااور ایک پہاڑ پر جومیں تجھے بتاؤں گااسے قربان کردے۔ (پیدایش: ۲۲:۲)\nسب کومعلوم ہے کہ ان کے اکلوتے بیٹے اس وقت اسحاق نہیں بلکہ اسماعیل تھے۔پھرجس بیٹے کو ابراہیم علیہ السلام زیادہ پیارکرتے تھے وہ اسماعیل ہی تھے اس لیے کہ وہ پہلے لڑکے تھے اور ابراہیم علیہ السلام کےرب نےان سے وعدہ بھی کیا تھا کہ ان کی نسل سے ایک بڑی قوم بناؤں گا (پیدایش: ا۲:۸ا) جب کہ اسحاق نہیں،بلکہ اسماعیل اکلوتے بیٹے تھے،جواسحاق سے پہلے پیدا ہوے اور اپنے والد کی وفات کے بعد بھی زندہ رہے۔\nسورہ الصافات سےبھی واضح ہوتاہےکہ جن کوقربانی کے لئے پیش کیاگیا تھا وہ اسماعیل ہی تھے۔ (دیکھیے:سورہ الصافات ا۰ا-ااا) قرآن کریم دونوں کاذکرکرتے ہوے بیان کرتاہے:﴿وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنࣱ وَظَالِمࣱ لِّنَفۡسِهِۦ مُبِينࣱ‏﴾ [الصافات: ۱۱۳] \"اور ہم نے ابراہیم اور اسحاق پر برکتیں نازل فرمائیں۔ ان دونوں کی اولاد میں بعض تونیک بخت ہیں اور بعض اپنے نفس پرصریح ظلم کرنے والے ہیں\"۔\nاسماعیل علیہ السلام سےعرب قوم پیدا ہوئی اور اسحاق علیہ السلام سے بنی اسرائیل،جوان کے صاحبزادے یعقوب کی جانب منسوب کی جاتی ہےاورچوں کہ یعقوب علیہ السلام کا نام اسرائیل بھی ہے اس لیے یہ بنی اسرائیل کے نام سے جانے جاتے ہیں، پھریعقوب علیہ السلام سے بارہ بیٹےہوےجن کے اسماء درج ذیل ہیں: ا- روبین، ۲- شمعون، ۳-لاوی،۴-یہودا، ۵-یساکر، ۶-زوبلون، ۷-یوسف(راحیل نامی بیوی سے) ۸-بنیامین، ۹-دان،۱۰- اورنفتالی(دونوں راحیل کی لونڈی بلہۃ سے)، ۱ا-جاد، ۲ا- اوراشیر(دونوں لیئۃ کی لونڈی زلفہ سے)۔ (دیکھیے :تورات، کتاب پیدایش: ۲۵:۳ا-۴ا)\nپھر ان سے بنی اسرائیل کے بارہ قبیلے وجود میں آئے جن کا ذکر تورات میں باربار آیاہے۔","",{}],[36,"§اسد\nدیکھیے: قسورة","",{}],[37,"§اسراء\nانبیا کی زندگی میں کبھی کبھی ایسا موقع بھی آتا ہے، جب االلہ تعالیٰ ان کواپنی کائنات کے کچھ مخفی اسرارسےمطلع کرنا چاہتاہے۔جس کے سبب ان کی خود اعتمادی میں اضافہ اور ان پر جوفرائض عائد گئے،ان کوبہتر انداز میں ادا کرنے کی رغبت بڑھ جاتی ہے۔انھی اسرار میں سےواقعۂ معراج بھی ہے۔اسراء کاذکر توخود قرآن میں ہے۔ لیکن معراج کابیان قرآن میں نہیں، لیکن بہت ساری متواتر احادیث میں اس کا تذکرہ آیا ہے، جن کوتیس سے زیادہ صحابہ کرام رضی اللہ عنہم نے روایت کیاہے۔\nرات کے سفرکو اسراءکہتے ہیں۔اس کااشارہ سورہ اسراء (جس کوسورہ بنی اسرائیل بھی کہتےہیں) میں اس طرح آیا ہے: ﴿سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلࣰ ا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾ [الإسراء: ۱] \"پاک ہے وہ(االلہ تعالیٰ)جواپنے بندے کو رات ہی رات میں مسجد حرام سے مسجد اقصی تک لے گیا، جس کے آس پاس ہم نے برکت دےرکھی ہے۔ تاکہ ہم اسے اپنی قدرت کے بعض نمونے دکھائیں۔ یقیناً االلہ تعالیٰ خوب سننے اور دیکھنے والاہے\"۔\nاسراءکےبعدنبی اکرم صلی اللہ علیہ وسلم کوساتوں آسمان کاسفر کرایا گیاجس میں،آپ نےمتعددمعجزات کامشاہدہ کیا،جن کا کچھ ذکرسورہ النجم میں بھی آیاہے۔قرآن مجیدمیں اس کے علاوہ اس بارے میں مزید کچھ نہیں آیاہے۔لیکن سیرت کی کتابوں سے معلوم ہوتاہے کہ اسراء کایہ غیر معمولی واقعہ ہجرت مکہ سے ایک سال قبل وقوع پذیر ہوا۔\nنبی اکرم صلی اللہ علیہ وسلم ابھی ابھی اہل طائف کواسلام کی دعوت دےکرواپس آئے تھے،جنھوں نے آپ کی دعوتِ اسلام کوٹھکرادیاتھا اور آپ کوتکلیف پہنچائی۔آپ کوپتھرمارے جس کی وجہ سے آپ کے پاؤں لہولہان ہوگئے۔اس حالت میں آپ بہت رنجیدہ تھے کہ اسراء کا واقعہ رونماہوا۔جس کے ذریعے سےااللہ تعالیٰ نے آپ کے رنج وغم کودورکرنا چاہا۔آپ کواپنی بےمثال نشانیاں بھی دکھانی چاہی تاکہ آپ ناامید نہ ہوں۔ صبرکےساتھ اپنا کام کرتےرہیں۔آئیے دیکھیں کہ اس سفر میں آپ نے کیا کیا دیکھا:\nا-نبی اکرم صلی اللہ علیہ وسلم (خانہ کعبہ کے قریب) اپنے گھرمیں آرام فرمارہے تھے کہ جبریل علیہ السلام نے آکر آپ کو اٹھایااورآپ کے سینے کوچاک کیا۔ آپ کادل نکالا۔ اس کوزمزم کے پانی سےدھویا۔ پھر اس کوعقل اور حکمت سے بھرےسونے کے برتن میں لے کر آئے اور اپنی جگہ پر لٹادیا۔دل نکالنے کاواقعہ اس وقت بھی ہوا تھا جب آپ بچے تھے۔\n۲-پھر وہ بْراق نامی ایک سواری لے کر آئے۔ براق کارنگ سفید تھا۔ وہ گدھے سے بڑا اور خچر سے کچھ چھوٹا تھا۔ اس کی رفتار اتنی تیز تھی کہ جہاں تک نگاہ جاتی تھی اس کا پاؤں وہاں پڑتا تھا۔\n۳- کچھ ہی لمحوں میں آپ بیت االلہ سے بیت المقدس پہنچ گئے،جس کی مسافت اس وقت سفر کرنےوالوں کے مطابق چالیس روز کی تھی۔وہاں آپ نے نماز میں انبیاے کرام کی امامت فرمائی۔\n۴- ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں آیا ہے : «أُتِيَ رَسُولُ اللَّه صلی اللہ علیہ وسلم ليلَةَ أُسْرِيَ به بِإِيلياءَ بِقَدَحَيْنِ مِنْ خَمْرٍ وَلَبَنٍ فَنَظَرَ إِليهمَا فَأَخَذَ اللَّبَنَ قَالَ جِبْرِيلُ: الْحَمْدُ لِلَّه الَّذِي هدَاکَ لِلْفِطْرَةِ لَوْ أَخَذْتَ الْخَمْرَ غَوَتْ أُمَّتُکَ». (صحیح البخاری: ۴۷۰۹) \"جس رات رسول اللہ صلی اللہ علیہ وسلم کو ایلیا(بیت المقدس) لے جایا گیا،جبریل علیہ السلام دوپیالے لے کر آئے۔ایک میں دودھ اور دوسرے میں شراب تھی۔آپ نے دودھ والا پیالہ لے لیا۔اس پر جبریل نے کہا:آپ نےفطرت اور سادگی کوپسندکیا،اگر آپ شراب والا پیالہ لیتے توآپ کی امت بھٹک جاتی\"۔\n۵- اس کے بعدجبریل علیہ السلام نبی اکرم صلی اللہ علیہ وسلم کولے کر آسمان کی طرف چلے۔ پہلے آسمان پر آدم، دوسرے پر عیسیٰ اور یحیی،تیسرے پر یوسف،چو تھے پر ادریس،پانچویں پرہارون، چھٹے پر موسیٰ اور ساتویں پر ابراہیم(علیہم السلام)سے ملاقات ہوئی۔سب سےتعارف ہوا۔سب نے آپ کوخوش آمدید کہا۔\n۶- اس سفر میں آپ سدرة المنتہی تک پہنچ گئے، جہاں کوئی مخلوق نہیں پہنچ سکتی۔وہاں آپ نے فرشتوں کےقلم چلنے کی آواز سنی،جوکائنات کی تقدیر لکھنے میں مشغول تھے۔\n۷-آپ اورآپ کی امت پر ایک دن اور ایک رات میں پچاس صلاتیں فرض کی گئیں، جوآپ صلی اللہ علیہ وسلم کی التجا پر پانچ رہ گئیں۔ لیکن اللہ تعالی نے اپنے فضل وکرم سے ان کاثواب پچاس کے برابر کردیا۔\n۸-آپ سے سوال کیا گیا کہ کیا آپ نے اس سفر میں االلہ تعالیٰ کوبھی دیکھا؟ آپ نے جواب دیا:\"وہ توایک نورہے، اسے کیسے دیکھا جاسکتاہے؟\"۔(صحیح مسلم:۷۸ا)\n۹-آپ نے اس سفر میں جبریل علیہ السلام کوان کی اصلی شکل میں دیکھا، جن کے چھےسوپر تھے۔ جنھوں نے پوری کائنات کوڈھانپ لیا تھا۔\n۰ا-اس سفر میں آپ نےااللہتعالیٰ کی عظیم نشانیاں دیکھیں۔ (سورہ النجم: ۸ا)\nان نشانیوں میں سے کچھ درج ذیل ہیں:\nوہاں ایک ایسی نہر دیکھی،جس کےکنارےپر ایک محل بنا ہواتھا،اس کی اینٹیں ہیرے جواہرات کی تھیں۔آپ نے جبریل علیہ السلام سے اس کے بارے میں سوال کیا تو انھوں نے بتایاکہ یہ نہر کوثر ہے۔ وہ محل جسے آپ نےدیکھا ہے اس کو اللہ تعالی نے آپ کے لیے بنایا ہے۔\nآپ نے وہاں بیت المعمور دیکھا، جس میں ہر روز ستر ہزار فرشتے نماز ادا کرتے ہیں،جواس میں سے نکلنے کےبعد دوبارہ واپس نہیں جاتے۔ (یعنی پھر دوسرے ستر ہزار آتے ہیں) (صحیح البخاری: ۳۲۰۷)۔\nوہاں چار نہریں دیکھیں۔ دوجنت میں جاری تھیں اور دودنیا میں، جن کو نیل اور فرات کہتے ہیں۔\nوہاں کچھ ایسے لوگوں کوبھی دیکھا جواپنا چہرہ اپنے ناخنوں سے کھرچ رہے تھے۔آپ نے جبریل سےپوچھا:یہ کون لوگ ہیں؟ جواب دیاکہ یہ وہ لوگ ہیں جودوسروں کی غیبت کیا کرتے تھے۔ (سنن ابی داود: ۵/۹۴ا)\nآپ نےوہاں جنت اور جہنم کابھی مشاہدہ کیا۔ان میں رہنے والے اور مستقبل میں جانے والوں کوبھی دیکھا۔االلہ تعالیٰ نے اپنے نبی کواسراء اور معراج کے واقعےسےیہ بتاناچاہا کہ وہ بہت عظیم ہے۔ وہ جوچاہےکرسکتاہے۔لیکن یہ بات وہ لوگ نہیں سمجھ سکتے جوایمان والے نہیں ہیں۔اس لیے جب نبی اکرم صلی اللہ علیہ وسلم نے اپنےسفر اسراء ومعراج کا ذکرمکےوالوں سے کیا تووہ آپ کا مذاق اڑانے لگے۔جابربن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب قریش نے مجھ کو واقعۂ معراج کےسلسلہ میں جھٹلایا تو میں (کعبہ کے ) مقام حجر میں کھڑا ہوا تھا اور میرے سامنے پورا بیت المقدس کر دیا گیا تھا۔ میں اسے دیکھ دیکھ کر اس کی ایک ایک علامت بیان کرنے لگا \"۔\nیہی وہ مشکل وقت تھا، جب مکےمیں دشمنانِ اسلام نےابوبکر صدیق رضی اللہ عنہ کوشرمندہ کرنے کے لیے کہاکہ کیاتم نے اپنے دوست کے بارے میں سناہے، جوکہتے ہیں کہ وہ ایک رات میں بیت المقدس جاکر آگئے۔ابوبکر رضی اللہ عنہ نےفرمایا: اگر وہ ایسا کہتے ہیں تواس میں تعجب کی کوئی بات نہیں۔ہم تواس بات پر یقین کرتے ہیں کہ آسمان سے ان پر وحی آتی ہے۔اگر وہ بیت المقدس ایک رات میں آنے جانے کی بات کرتے ہیں توہمیں پورا یقین ہے کہ ایسا ہی ہوا ہوگا۔یہ سن کر دشمنانِ اسلام حیرت زدہ رہ گئے۔اس واقعے کے بعدنبی اکرم صلی اللہ علیہ وسلم نےابوبکرکوصدیق کےخطاب سے نوازا جس کامطلب ہے تصدیق کرنے والا۔\nاگرآج بھی کوئی شخص ان باتوں پر شک وشبہ کرے تو ہم یہی کہیں گے کہ وہ االلہ تعالیٰ کی عظیم سلطنت وقوت کونہیں جانتا۔ سب سے پہلے ہم اسے نبی اکرم صلی اللہ علیہ وسلم کے صادق و مصدوق ہونے کاپیغام دیں گے۔جب وہ آپ کونبی مان لےگا،پھرآپ کی کسی بات پر شک نہیں کرےگا۔رہے وہ لوگ جوآپ کونبی نہیں مانتےتوہم ان سے گزارش کریں گے کہ وہ دین اسلام کامطالعہ کریں۔\nاس بارے میں اختلاف ہے کہ یہ سفر صرف روح کا تھایا جسم اور روح دونوں کا۔قرآن کریم کےاسلوب بیان سے یہ پتا چلتا ہے کہ آپ کا یہ سفر جسم اور روح دونوں کے ساتھ تھا۔االلہ تعالیٰ کا فرمان ہے: ﴿سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلࣰ ا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾ [الإسراء: ۱] \"پاک ہے وہ اللہ تعالیٰ جو اپنے بندے کو رات ہی رات میں مسجد حرام سے مسجد اقصیٰ تک لے گیا جس کے آس پاس ہم نے برکت دےرکھی ہے اس لئے کہ ہم اسے اپنی قدرت کے بعض نمونے دکھائیں۔ یقیناً اللہ تعالیٰ سمیع وبصیر(خوب سننے دیکھنے والا)ہے\"۔\nاس اسلوب سے ظاہر ہوتاہے کہ یہ کسی عظیم واقعےکی طرف اشارہ ہے۔اب اگر یہ سفرصرف روح کاہوتا یاخواب میں ہوتا تواس میں کون سی اچنبھے کی بات تھی۔اس طرح کے خواب تو کوئی بھی دیکھ سکتا ہے۔ پھر مکہ کےان دشمنانِ اسلام کواس کا انکارکرنے کی کیا ضرورت ہوسکتی تھی؟\nااللہ تعالیٰ کا فرمان ہے: ﴿وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةࣰ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنࣰ ا كَبِيرࣰ ا﴾ [الإسراء: ۶۰] \"اور جومنظر ہم نے تمھیں دکھایا اسے توبس ہم نے لوگوں کے لیے آزمایش بنادیا\"۔\nاس سے بھی معلوم ہوتاہے کہ یہ خواب نہیں بلکہ جسمانی سفر تھا۔کیوں کہ اگر یہ صرف ایک خواب ہوتا تواس میں لوگوں کے لیے کیا آزمایش تھی۔خواب تو ہم ایک سے ایک حیرت انگیز دیکھتے رہتے ہیں۔یہاں قرآن کریم نےلفظ رؤیا کا استعمال کیاہے۔جس کامعنیٰ خواب بھی ہوتاہے۔لیکن جب اس کے ساتھ لوگوں کی آزمایش کابھی ذکر کردیا توپھریہ عینی مشاہدے کےمعنیٰ میں بدل گیا۔مذکورلفظ سے کچھ علماءکویہ غلط فہمی ہوگئی ہےکہ یہ پورا سفر ایک خواب تھا۔لیکن جب سورہ اسراءکی ابتدائی آیت کواس ساٹھویں آیت کے ساتھ ملاکر غور کرنے سےواضح ہوجاتا ہے کہ یہ جسم اور روح دونوں کاسفر تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے سب کچھ اپنی آنکھوں سے دیکھا۔یہ سب کچھ ہم اس لیے متوقع اور ممکن بل کہ یقینی مانتے ہیں کہ یہ سفرآپ کوااللہ تعالیٰ نے کرایا جوعظیم ہے اور جس کی قدرت دنیا کے ذرے ذرےمیں جاری ہے۔جس نے آدم علیہ السلام کومٹی سے بنایا۔ابراہیم علیہ السلام کوآگ سےزندہ نکالا۔موسیٰ علیہ السلام کے لیے سمندر کےپانی کودو حصوں میں تقسیم کردیا اور عیسیٰ علیہ السلام کوعظیم معجزات عطا کیے۔کیا وہ االلہ تعالیٰ محمد صلی اللہ علیہ وسلم کویہ سفر نہیں کراسکتا؟\nیہاں یہ بات بھی جان لینی ضروری ہے کہ اسراء ومعراج کاتصورآپ اس وقت تک نہیں کرسکتے جب تک آپ کوااللہ تعالیٰ کی عظیم قدرت پر پورا ایمان ویقین نہ ہو۔غور کیجیے کہ اب تک سب سے زیادہ تیز رفتار سفر کرنے والی جس چیز کی دریافت ہوئی ہے وہ روشنی ہے، جوایک سکنڈ میں ایک لاکھ چھیاسی ہزار میل سفرکرتی ہےاور ہمارے شمسی نظام سےباہر جوقریب ترین سیارہ ہے اس کو الفاسنیچوری(Alpha centauri A) کہتے ہیں، وہاں تک پہنچنے کے لیے ہمیں ۴۲۴ نوری سال چاہیے۔جب کہ ابھی ہم پہلے آسمان میں ہی ہیں اور نبی اکرم صلی اللہ علیہ وسلم اسراء ومعراج میں ساتویں آسمان تک پہنچ گئےتھے، جہاں بیت المعمور ہے۔اس کے آگے کوئی نہیں جاسکتا۔اب االلہ تعالیٰ کی عظیم قدرت دیکھیے جو فرماتا ہے: ﴿وَمَآ أَمۡرُنَآ إِلَّا وَٰحِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ﴾ [القمر: ۵۰] \"اور ہماراحکم توآنکھوں کے جھپکنے کی طرح ہوتاہے\"۔\nجس طرح آنکھ جھپکنے میں کچھ دیر نہیں ہوتی اسی طرح االلہتعالیٰ کےحکم کوعملی صورت میں آنے میں دیر نہیں ہوتی۔بلکہ کسی بھی کام کے لیے االلہتعالیٰ کاحکم صرف کن (ہوجا)ہوتاہے اور وہ ہوجاتاہے۔(البقرة: ۴۴)\nاس طرح پلک جھپکتے آپ پہلے آسمان پر پہنچے۔ دوبارہ پلک جھپکتے تیسرے آسمان پرپہنچے۔یہاں تک کہ آپ سدرة المنتہی تک پہنچ گئے۔یہاں نوری رفتار بھی ماندپڑگئی۔بلکہ رفتار کاایک دوسرا پیمانہ استعمال کیاگیا۔ وہ ہے االلہ تعالیٰ کا لفظ \"کن\"(ہوجا)کہنا۔ اس سے پتا چلا کہ نبی اکرم صلی اللہ علیہ وسلم کاسفرمعراج االلہ تعالیٰ کے لفظ \"کن\"کہنے سےہواتھا۔جس کے سامنے دُنیوی نظام وقت،قاعدہ اور دوردراز کی مسافت سب ختم ہوجاتی ہے۔لیکن یہ ساری باتیں وہی لوگ سمجھ سکتے ہیں جوصاحب عقل وخرد ہیں۔\nاسرائيل\nاسرائیل یعقوب علیہ السلام کالقب ہے۔یہ عبرانی زبان کالفظ ہے۔عبرانی میں اسرائیل اس شخص کو کہتے ہیں جوااللہ کے ساتھ مل کر مذہبی جنگ کرے۔اس کاذکر بائبل میں بھی آیاہے۔ (بائبل،پیدایش: ۳۴:۷)\nاسرائیل کے دوسرےمعنیٰ عبدااللہ کے بھی ہیں۔یہ دولفظوں سے مل کر بنا ہے۔ایک اسرا،جس کے معنیٰ االلہ، دوسرےایل،جس کےمعنیٰ بندے کے ہیں۔ بائبل میں بنی اسرائیل کواسرائیل بھی کہا گیاہے۔ (بائبل خروج: ۳۲ ۴)\nمصر میں کچھ ایسی تختیاں ملی ہیں جومنفتاح نام کے فرعون کے عہدکی ہیں۔جو۲۲۷ا-۲۳۴ا ق م مصر کاحاکم یافرعون تھا۔ ان تختیوں میں بھی بنی اسرائیل کواسرائیل کہا گیاہے(دیکھیے :قاموس کتاب مقدس: ص ۶۹)\nاس سےمعلوم ہوتا ہے کہ اسرائیل یعقوب علیہ السلام کالقب بھی ہے اور بنی اسرائیل کانام بھی۔\nقرآن مجیدمیں اسرائیل کاذکر صرف ايک بار آياہے:﴿كُلُّ ٱلطَّعَامِ كَانَ حِلࣰّ ا لِّبَنِيٓ إِسۡرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡرَٰٓءِيلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُواْ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَآ إِن كُنتُمۡ صَٰدِقِينَ﴾ [آل عمران: ۹۳] \"تورات کے نزول سے پہلے یعقوب نے جس چیز کو اپنے اوپر حرام کر لیا تھا اس کےسوا تمام کھانے بنی اسرائیل پر حلال تھے۔ آپ کہہ دیجیےکہ اگر تم سچے ہو تو تورات لے آؤ اور پڑھ کر سناؤ \"۔\nاس آیت کے نزول کا سبب یہ ہے کہ یہودیوں نے مسلمانوں پراعتراض کیاکہ تم لوگ ابراہیم کے دین پر ہونے کادعوی کرتے ہو،لیکن اونٹ کاگوشت کھاتے ہو،جوابراہیم اوریعقوب علیہما السلام کےیہاں حرام تھا۔قرآن نے جواب دیا کہ کھائی جانے والی ہرچیزبنی اسرائیل کے لیے حلال تھی۔ لیکن یعقوب علیہ السلام نے کسی مرض کی وجہ سے اپنے اوپر اونٹ کاگوشت حرام کرلیا تھا۔ سنن ترمذی اور مسند احمد میں ہے کہ یعقوب علیہ السلام نے اونٹ کاگوشت اور اس کادودھ اپنے اوپر حرام کرلیا تھا۔ جس کےبعد اسرائیل کی اولاد نےاس کوہمیشہ کے لیے ناجائز کرلیا۔ جب کہ ابھی تورات اتری بھی نہیں تھی۔اس لیے قرآن مجیدنےچیلنج کیاکہ اگرتم اپنے دعوےمیں سچے ہوتولاؤ تورات اور دکھاؤ کہ ابراہیم نے اونٹ کاگوشت کہاں حرام کیاہے؟\nبائبل میں ہے: پھر رب نے موسیٰ اور ہارون سے کہا کہ تم بنی اسرائیل سے کہوکہ جتنے جانور زمین پر ہیں، ان سب میں سےجن کے پاؤں الگ ہوں،چیرےہوے ہوں اور جْگالی کرتے ہوں تم ان کو کھاسکتے ہو۔مگر جوجگالی نہیں کرتےیاجن کے پاؤں چیرے ہوے نہیں ہیں، ان میں سے تم ان جانوروں کو نہ کھانا۔ اونٹ جوجگالی توکرتاہے،لیکن اس کا کھُرچیراہوا نہیں ہوتا۔ اس لیےیہ تمھارے لیےپاک اور حلال نہیں ہے۔ اسی طرح سافان اور خرگوش جو جگالی توکرتے ہیں مگر ان کے کھُرچیرے ہوےنہیں ہوتے اور سور کہ اس کے کھُر چیرے توہوتے ہیں لیکن وہ جگالی نہیں کرتا۔ (دیکھیے: احبار اا:ا-۸ اور استثناء ۴ا:۷-۸)۔ایسا ان کے لیے سزا کے طور پر کیاگیاہے۔جس کاذکر قرآن میں یوں آیاہے:\n۱- ﴿فَبِظُلۡمࣲ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرࣰ ا﴾ [النساء: ۱۶۰] \"جو نفیس چیزیں ان کے لیےحلال کی گئی تھیں وہ ہم نے ان پر حرام کر دیں ان کے ظلم کے باعث اور اللہ تعالیٰ کی راہ سے اکثر لوگوں کو روکنے کے باعث\"۔\n۲- ﴿وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرࣲۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمࣲۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ﴾ [الأنعام: ۱۴۶] \"اور یہودپر ہم نے تمام ناخن والے جانور حرام کردیے تھے اور گائے اوربکری میں سے ان دونوں کی چربیاں ان پر ہم نے حرام کردی تھیں مگر وہ جوان کی پشت پریا انتڑیوں میں لگی ہویا جوہڈی سے ملی ہو۔ان کی شرارت کےسبب ہم نے ان کویہ سزادی اور ہم یقیناً سچے ہیں\"۔\nاس سے معلوم ہو اکہ وہ ساری چیزیں بھی بنی اسرائیل کے لیے حلال تھیں جومسلمانوں کے لیے حلال ہیں۔یہی یعقوب وابراہیم علیہما السلام کابھی دین تھا۔بلکہ قرآن کریم نبی اکرم صلی اللہ علیہ وسلم کی تعریف کرتے ہوے بیان کرتاہےکہ جب وہ(محمد)آئیں گےتوبنی اسرائیل نےجوحلال اور پاک چیزیں حرام کردی تھیں ان کودوبارہ حلال کریں گے۔ جوبوجھ انھوں نے اپنے اوپر ڈال لیا تھا، اس سے ان کو آزاد کردیں گے۔ (الاعراف: ۵۷ا)\nپھر یہی ہوا کہ آج رؤے زمین کی ایک تہائی سے زیادہ کی آبادی ان بیڑیوں سے آزاد ہوچکی ہے۔اللہ تعالیٰ نےچاہاتوآہستہ آہستہ جوں جوں لوگ اسلام قبول کرتے جائیں گے، یہ زنجیریں ٹوٹتی چلی جائیں گی۔","",{}],[38,"§اسلام\nاسلام کامطلب ہے: امن وسلامتی،اس لیے دین اسلام کامطلب سلامتی والا مذہب ہے۔اسی سے \"سلم\"ہے۔ قرآن مجیدمیں آیاہے:﴿وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ﴾ [الأنفال: ۶۱] \"اگروہ لوگ صلح(سلامتی)کی طرف جھکیں توتوبھی صلح کی طرف جھک جا۔ االلہپربھروسارکھ،یقیناً وہ سمیع وعلیم، بہت سننےاور جاننے والا ہے\"۔\nمطلب یہ ہے کہ اگرجنگ ہورہی ہواور دشمن صلح وامن کاپیغام بھیجے تو بھی سلامتی کوقبول کرلینا چاہیے۔اسلام قبول کرنے کامطلب اپنے آپ کوااللہ کے حکم کے سامنے جھکادینا ہے۔قرآن مجید میں ہے: ﴿فَإِنۡ حَآجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِيَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡأُمِّيِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُواْ فَقَدِ ٱهۡتَدَواْۖ وَّإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُۗ وَٱللَّهُ بَصِيرُۢ بِٱلۡعِبَادِ﴾ [آل عمران: ۲۰] \"پھر بھی اگر یہ آپ سے جھگڑیں تو آپ کہہ دیں کہ میں اور میرے تابع داروں نے اللہ تعالیٰ کے سامنے اپنا سر تسلیم خم کر دیا ہے اور اہل کتاب سے اور ان پڑھ لوگوں سے کہہ دیجیے! کہ کیا تم بھی اطاعت کرتے ہو؟ پس اگر یہ بھی تابع دار بن جائیں تو یقیناً ہدایت والے ہیں اور اگر یہ رو گردانی کریں، تو آپ پر صرف پہنچا دینا ہے اور اللہ بندوں کو خوب دیکھ بھال رہا ہے\"۔\nپھر یہ اسلام کوئی نیا مذہب نہیں، بلکہ یہی سارے انبیا ورسل کا بھی دین رہاہے۔ قرآن مجیدمیں ہے:\n۱- ﴿إِنَّآ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِيهَا هُدࣰ ى وَنُورࣱۚ يَحۡكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسۡلَمُواْ لِلَّذِينَ هَادُواْ وَٱلرَّبَّٰنِيُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُواْ مِن كِتَٰبِ ٱللَّهِ وَكَانُواْ عَلَيۡهِ شُهَدَآءَۚ فَلَا تَخۡشَوُاْ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُواْ بِـَٔايَٰتِي ثَمَنࣰ ا قَلِيلࣰ اۚ وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ﴾ [المائدة: ۴۴] \"ہم نے تورات نازل فرمائی، جس میں ہدایت ونورہے۔یہودیوں میں اسی تورات کے ذریعے سے االلہ تعالیٰ کے ماننے والے انبیااور اہل االلہ اور علماءفیصلے کیاکرتے تھے۔ کیوں کہ انھیں اللہ کی اس کتاب کی حفاظت کا حکم دیا گیا تھااور وہ اس پر اقراری گواہ تھے۔ اب تمھیں چاہیےکہ لوگوں سے نہ ڈرو اور صرف میرا ڈر رکھو۔ میری آیتوں کو تھوڑے تھوڑے مول پر نہ بیچو اور جو لوگ اللہ کی اتاری ہوئی وحی کے ساتھ فیصلے نہ کریں وہ کافر ہیں\"۔\n۲- مزیدارشادہے: ﴿مَا كَانَ إِبۡرَٰهِيمُ يَهُودِيࣰّ ا وَلَا نَصۡرَانِيࣰّ ا وَلَٰكِن كَانَ حَنِيفࣰ ا مُّسۡلِمࣰ ا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ﴾ [آل عمران: ۶۷] \"ابراہیم نہ یہودی تھے اور نہ عیسائی۔ بلکہ وہ توسب سے کٹ کر رہنے والے (خالص) مسلمان تھے اور وہ مشرکوں میں سے نہیں تھے\"۔\nیوسف علیہ السلام نے االلہ تعالیٰ سے یہ دعا کی: ﴿رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمࣰ ا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾ [یوسف: ۱۰۱] \"اےمیرے رب! تونے مجھے ملک عطافرمایا اور تو نے مجھے خواب کی تعبیرسکھائی۔اے آسمان وزمین کے پیداکرنے والے! توہی دنیا وآخرت میں میرا ولی (دوست)اور کار سازہے، تومجھے اسلام کی حالت میں فوت کراور نیکوں میں ملادے\"۔\nمزیدارشادباری تعالیٰ ہے: ﴿وَإِذۡ أَوۡحَيۡتُ إِلَى ٱلۡحَوَارِيِّـۧنَ أَنۡ ءَامِنُواْ بِي وَبِرَسُولِي قَالُوٓاْ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ﴾ [المائدة: ۱۱۱] \"اور جب میں نے حواریوں کوحکم دیا کہ تم مجھ پراور میرے رسول پر ایمان لاؤ انھوں نے کہاکہ ہم ایمان لائے اور آپ شاہد رہیے کہ ہم پورے فرماں بردار ہیں\"۔\nاورفرمایا: ﴿قَالَ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ﴾ [النمل: ۳۸] \"سلیمان علیہ السلام نے اپنے درباریوں سے فرمایا: اےسردارو! تم میں سے کوئی ہے جوان کے مسلمان ہوکر پہنچنے سے پہلے ہی اس کا تخت مجھے لادے\"۔\nان آیات سے معلوم ہوتاہے کہ نبی اکرم صلی اللہ علیہ وسلم جودین لے کر آئے اور جس کواسلام کہتے ہیں وہ سارے انبیاورسل کادین ہے۔ یہ کوئی نیا دین نہیں ہے۔\nارشاد باری تعالیٰ ہے:﴿قُلۡ مَا كُنتُ بِدۡعࣰ ا مِّنَ ٱلرُّسُلِ وَمَآ أَدۡرِي مَا يُفۡعَلُ بِي وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّ وَمَآ أَنَا۠ إِلَّا نَذِيرࣱ مُّبِينࣱ‏﴾ [الأحقاف: ۹] \"آپ کہہ دیجیے: میں کوئی بالکل ا نوکھا رسول تو نہیں، نہ مجھےیہ معلوم ہے کہ میرے ساتھ اور تمھارےساتھ کیاکیاجائے گا۔میں توصرف اسی کی پیروی کرتاہوں جومیری طرف وحی بھیجی جاتی ہے۔ میں توصرف علی الاعلان آگاہ کردینے والا ہوں\"۔\nنیزارشاد باری تعالیٰ ہے : ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۗ وَمَن يَكۡفُرۡ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ﴾ [آل عمران: ۱۹] \"بے شک االلہ کے نزدیک دین توصرف اسلام ہے\"۔\nاور فرمایا: ﴿وَمَن يَبۡتَغِ غَيۡرَ ٱلۡإِسۡلَٰمِ دِينࣰ ا فَلَن يُقۡبَلَ مِنۡهُ وَهُوَ فِي ٱلۡأٓخِرَةِ مِنَ ٱلۡخَٰسِرِينَ﴾ [آل عمران: ۸۵] \"جوشخص اسلام کے سوا اور دین تلاش کرے اس کادین ہرگز قبول نہ کیاجائے گا اور وہ آخرت میں نقصان پانے والوں میں ہوگا\"۔\nاس طرح دیکھا جائے تومعلوم ہوتاہے کہ اسلام وہ مذہب ہے،جس کوااللہ تعالیٰ نے اپنے آخری رسول پر پوراکردیا اور اس کے ذریعےسےسلسلۂ نبوت ورسالت کوہمیشہ کے لیے ختم کردیا۔اب اسلام ہی وہ دین ہے،جس کے سوا االلہ تعالیٰ کسی اور دین کوقبول نہیں کرے گا۔اس مذہب کواللہ تعالیٰ نے بہت آسان بنایاہے۔اس میں کسی طرح کی کوئی دشواری نہیں ہے۔اللہ تعالیٰ نےاس کےماننے والوں پر کوئی ایسا بوجھ نہیں ڈالا، جس کی وہ طاقت نہ رکھتے ہوں۔اس دین کی بنیاد توحیدباری تعالیٰ ہے۔ اس کی پہچان سچائی ہے۔عدل وانصاف اس کااہم جز ہے۔اس کانچوڑایک دوسرے پر رحم کرناہے۔یہ ایسا دین ہے، جوہر اچھے اور مفیدکام کاحکم دیتااورمضر اور برے کاموں سے منع کرتاہے۔یہ ایسا دین ہے، جس کےذریعے سے االلہ تعالیٰ اپنے بندوں کے ایمان واخلاق کودرست کرتا اور دُنیوی واخروی زندگی کوسنوار تاہے۔ اس کے ذریعے سے االلہ تعالیٰ ٹوٹے ہوےدلوں کوجوڑتاہے۔ انسان کو صراط مستقیم دکھاتاہے۔یہ ایسا مذہب ہے جس میں سارے احکام واضح ہیں۔خواہ وہ اعتقادات سےمتعلق ہوں یااعمال واخلاق سے یامعاملات سے۔\nاسلام کا خلاصہ یہ ہے :انسان کواپنے رب اور خالق کے اسماء وصفات سے روشناس کرانا۔\nبندوں کوصرف االلہتعالیٰ کی عبادت کی دعوت دینا اور یہ واضح کرنا کہ االلہتعالیٰ کاکوئی شریک اورساجھی نہیں۔اس کے بتائے ہوےاحکام واوامر پر چلنا اور منع کی ہوئی چیز وں سے اجتناب۔\nصلاة جس کوہم اردو زبان میں نماز کہتے ہیں، اسلام کادوسرا ر کن ہے۔یہ حقیقت میں اسی توحیدالٰہی کوباربار یاد دلاتی اوراس پر تنبیہ کرتی ہے کہ خبردار زندگی کے کسی لمحے اور پل میں توحید کوچھوڑ کر شرک نہ کربیٹھنا۔اس لیےکہ شیطان اسی وقت سے ہمارے پیچھے لگاہوا ہے، جب سے اس کواور آدم کوجنت سے نکالا گیا تھا۔ قرآن مجیدمیں ہے: ﴿قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمࣱ وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ قَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ﴾ [الحجر: ۳۴-۴۰] \"فرمایا: اب توجنت سے نکل جا۔کیوں کہ توراندۂ درگاہ ہے۔ تجھ پر میری پھٹکار ہے، قیامت کے دن تک کے لیے۔کہنے لگاکہ اے میرے رب! مجھے اس دن تک کی ڈھیل دے کہ لوگ دوبارہ اٹھاکھڑے کیے جائیں۔فرمایاکہ اچھا توان میں سے ہےجنھیں مہلت ملی ہے روز مقرر کے وقت تک کی۔ (شیطان نے)کہاکہ اے میرے رب! چونکہ تونے مجھے گمراہ کیاہے، مجھے بھی قسم ہے کہ میں بھی زمین میں ان کے لیے معاصی کومزین کروں گا اور ان سب کوبہکاؤں گا بھی۔ سوائے تیرے ان بندوں کے جومنتخب کرلیے گئے ہیں\"۔\nاس کاثبوت پیش کردینے کے بعد بندے پر ضروری ہوجاے گا کہ وہ ہر طرح کی عبادت صرف االلہ کےلیے خاص کرے۔جیسے دعا،سوال،فریاد، نذرونیاز وغیرہ۔ان امورمیں وہ کسی کوشریک نہ بنائے خواہ وہ فرشتے ہوں یا دوسرے پاک نفوس۔ انسانی شکل میں ہوں یا کسی اور بھیس میں۔\nتوحید کےبارے میں اللہ تعالیٰ نے ہمیں یہ دعاسکھائی ہے: ﴿إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ﴾ [الفاتحة: ۵] \"ہم تیری ہی عبادت کرتے ہیں اور تجھ سے ہی مدد چاہتے ہیں\"۔\nاورفرمایا: ﴿قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا﴾ [الإسراء: ۵۶] \"کہہ دیجیے: االلہ کے سوا جنھیں تم معبود سمجھ رہے ہوانهیں پکارو۔لیکن نہ تووہ تم سے کسی تکلیف کو دور کرسکتے ہیں اور نہ بدل سکتے ہیں\"۔\nموت کے بعدوالی زندگی کے بارے میں بتانا اور اس بات سے آگاہ کرنا کہ آخرت والی زندگی میں ان کے ساتھ کیا ہونے والا ہے، موت کے بعددوبارہ اٹھائے جانےکےکیامراحل ہوں گےاور ان کا نتیجہ کیا ہوگا۔جنت یاجہنم؟\nاسلام کا لفظ استعمال کیا جاتا ہے تو اس میں ایمان اور اس کے ارکان واجزا٫ بھی داخل ہیں۔ اسی طرح سے ایمان کے لفظ کے اطلاق میں اسلام اور اس کے ارکان واجزا٫ بھی داخل ہوتے ہیں-ایک ساتھ دونوں کا ذکر ہو تو دونوں کے معنی الگ الگ ہوتے ہیں۔\nایمان کے چھ ارکان ہیں:\n۱-اللہ پر ایمان: االلہ پر ایمان کامطلب :\n(الف) یہ ماننا کہ االلہ تعالیٰ سب کارب، خالق اور مالک ہے۔وہی کائنات کامدبر اور مختار کل ہے۔اس کو توحید ربوبیت کہتے ہیں۔\n(ب)صرف وہی ذات عبادت کے لائق ہے۔اس کو چھوڑکرجن کی عبادت بھی کی جاتی ہے،وہ سب غلط اور باطل معبود ہیں۔اس کو توحید الو ہیت کہتے ہیں۔\n(ج)اس کے سارے نام اچھے اور بلند ہیں۔وہ ان ساری صفا ت سے متصف ہے،جن کا ذکر قرآن اورصحیح احادیث میں آیا ہے۔اس کو توحید اسما٫و صفات کہتے ہیں۔\nاسلام نے جہاں توحید کاحکم دیا، وہیں شرک کی شدید مذمت بھی کی ہےاور وہ لوگ جوایک االلہ کو چھوڑ کرکسی غیر کی عبادت کرتے ہیں ان کوجہنم کی سزا کی دھمکی دی ہے۔ارشاد باری تعالیٰ ہے: ﴿لَقَدۡ كَفَرَ ٱلَّذِينَ قَالُوٓاْ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِيحُ ٱبۡنُ مَرۡيَمَۖ وَقَالَ ٱلۡمَسِيحُ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۖ إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارࣲ‏﴾ [المائدة: ۷۲] \"بے شک وہ لوگ کافر ہوگئے جن کاقول ہے کہ مسیح ابن مریم ہی االلہ ہے۔ حالانکہ خود مسیح نے ان سے کہا تھا کہ اے بنی اسرائیل! االلہ ہی کی عبادت کرو جومیرا اور تمھارا سب کارب ہے۔ یقین مانو کہ جوشخص کسی کو االلہ کے ساتھ شریک ٹھہراتاہے، االلہ تعالیٰ نے اس پر جنت حرام کردی ہے۔ اس کاٹھکانا جہنم ہی ہے اور گنہگاروں کی مدد کرنے والا کوئی نہیں ہوگا\"۔\n۲- انبیاورسل پر ایمان:االلہ تعالیٰ نے اس دنیا میں بے شمار انبیاورسل بھیجے۔سب سے پہلے نبی آدم علیہ السلام تھے اور سب سے آخری نبی ورسول محمد صلی اللہ علیہ وسلم ہیں۔سارے انبیاورسل ہماری طرح مخلوق تھے۔ان میں کسی طرح کی خالقیت کی صفت نہیں پائی جاتی تھی۔وہ سب االلہ تعالیٰ کے نیک بندے تھے۔االلہ تعالیٰ نے ان کو اپنا نبی ورسول بناکر ان پر بڑا احسان کیا۔آخری رسول جناب محمد صلی اللہ علیہ وسلم کے بعدنبوت ورسالت کاسلسلہ ختم ہوگیا۔اب قیامت تک کوئی نبی نہیں آئے گا۔آپ صلی اللہ علیہ وسلم کادین ساری دنیاکے انس وجن کے لیے اور رہتی دنیا تک عام ہے۔\n۳-فرشتوں پر ایمان : فرشتے االلہ تعالیٰ کی ایسی مخلوق ہیں،جن کواس نےصرف اپنی عبادت کے لیے پیداکیا ہے۔یہ ہروقت اللہ تعالیٰ کی عبادت اور اطاعت میں مشغول رہتے ہیں۔االلہ تعالیٰ نے ان کومختلف ذمہ داریاں سونپی ہیں۔\nااللہ تعالیٰ نے انبیاورسل تک اپنا پیغام پہنچانے کے لیے جبریل علیہ السلام کومامور کیا۔بارش کاکام میکائیل کواور اسرافیل کوقیامت کےلیے صور پھونکنے کاکام سونپاگیاہے۔ ایک موت کافرشتہ ہے، جس کےذمہ روح نکالنے کاکام ہے۔ بعض لوگ اس فرشتے کانام عزرائیل بتاتے ہیں۔لیکن اس کی توثیق کتاب وسنت سے نہیں ہوتی۔سارے فرشتے االلہ تعالیٰ کےاحکام کی تعمیل میں مصروف ہیں۔ا ن میں سے کسی کو کوئی اختیار نہیں ہے۔\n۴- االلہ کی طرف سے نازل کردہ کتابوں پرایمان:االلہ تعالیٰ نے بنی نوع انسان کی ہدایت ورہنمائی کے لیے اپنے رسولوں پرآسمانی کتابیں نازل کی ہیں۔ ان میں آخری کتاب قرآن کریم ہےجس کانزول خاتم الانبیامحمد صلی اللہ علیہ وسلم پر ہوا، جوقیامت تک آنے والے انسانوں کی ہدایت کاواحدذریعہ ہے۔ جوآسمانی صحیفےقرآن سے پہلےآئے ہیں ان میں سے کچھ کاذکر قرآن میں ملتاہے۔\nتورات: موسیٰ علیہ السلام پر نازل ہوئی،اس کتاب میں بنی اسرائیل کوہدایت کی گئی۔\nانجیل : عیسیٰ علیہ السلام پر اتاری گئی۔\nزبور : داود علیہ السلام کودی گئی۔\nصحیفے: ابراہیم علیہ السلام کودیے گئے۔\n۵-یوم آخرت پر ایمان: آخرت کے دن پرایمان لانے کامطلب ہے کہ ایک دن یہ دنیا فنا ہوجائےگی۔االلہ تعالیٰ سارے انسانوں کودوبارہ اٹھائےگااور ان کے اعمال کے مطابق ان کے ساتھ عدل وانصاف کرے گا۔اس کے بعدجنت وجہنم کافیصلہ ان کے حق میں ہوگا۔پرہیزگاروں اور نیک لوگوں کے لیے جنت اور بْرے لوگوں (کافر،مشرک اورمنافق)کے لیے جہنم کی سزا ہوگی۔\n۶-تقدیر پر ایمان:تقدیر کامطلب ہے کہ االلہ تعالیٰ نے اس کائنات کو علم وقدرکے ذریعے سے پیدافرمایا۔اس لیے یہاں جوکچھ بھی ہورہاہے،اللہ تعالیٰ کواس کا علم ہے۔وہ سب کچھ اس کے پاس مکتوب ہے۔دنیامیں جو کچھ ہورہا ہے، اس کی رضا ورغبت اور ارادےاورمشیت سے ہورہاہے۔\n§اسلا م کے ارکان:\nاسلام کے پانچ ارکان ہیں۔جن پرایمان لائے اورعمل کےبغیر آدمی مسلمان نہیں ہوسکتا۔ان کی تفصیل درج ذیل ہے:\n(۱) کلمۂ شہادت: لا إله إلا اللہ محمد رسول اللہ (اس بات کی گواہی دینا کہ االلہ کے سوا حقیقت میں کوئی عبادت کے لائق نہیں اور محمد صلی اللہ علیہ وسلم اللہ تعالیٰ کے بھیجے ہوےرسول ہیں)مطلب یہ ہے کہ االلہ تعالیٰ ہمارا خالق ومالک اوررب ہے۔اس لیے صرف وہی عبادت کامستحق ہے۔اس کےسوا جس کی بھی عبادت کی جائے وہ غلط اور باطل ہے۔ اس کو توحید الوہیت کہتے ہیں۔\nمحمد صلی اللہ علیہ وسلم کے رسول االلہ ہونے کامطلب ہے کہ ہم آپ کی لائی ہوئی تعلیمات پرایمان لائیں اور جس چیز کاحکم دیاہے،اس کو بجالائیں اور جس چیزسےمنع کیا ہے اس سے رک جائیں اور االلہ تعالیٰ کی عبادت کا وہی طریقہ اپنائیں جس کااس نے حکم دیاہے۔اس کو توحید رسالت کہتے ہیں۔ اس کلمےکے اقرار سے آدمی دین اسلام میں داخل ہوتا ہے۔\n(۲) صلاة(نماز): االلہ تعالیٰ نے ہم پر بے شمار احسانات کیے ہیں۔ان احسانات کے بدلے االلہ تعالیٰ کاہمارے اوپر حق ہے کہ ہم اس کی عبادت کریں۔االلہتعالیٰ نے ہم پر ایک احسان یہ بھی کیاہے کہ اپنی عبادت اور بندگی کاطریقہ بھی اپنے نبی کے ذریعے سے ہم کو بتادیاہے۔اس کاحکم ہے:﴿فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمࣰ ا وَقُعُودࣰ ا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبࣰ ا مَّوۡقُوتࣰ ا﴾ [النساء: ۱۰۳] \"بے شک نماز ایمان والوں پر وقت کی پابندی کے ساتھ فرض کردی گئی ہے\"۔\nاس طرح دن اور رات میں پانچ بارنمازادا کرنا ہمارے اوپر فرض ہے۔کیوں کہ یہ االلہ کاحکم ہے۔ االلہاور بندے کے تعلق کوجوڑنے کاسب سے بہتر ذریعہ نمازہے۔ اس ذریعے سے بندہ االلہ کو پکارتا ہےاور اس سے مناجات کرتاہے۔ جب ایک مسلمان نماز اس طرح ادا کرے گاتو نماز اس کوہر طرح کی برائیوں سے روکے گی۔ اس لیے چوبیس گھنٹوں میں پانچ بار نماز فرض کی گئی۔صحیح حدیثوں میں آیا ہےکہ نمازنہ پڑھنے والا کفر کامرتکب ہوجائے گا۔ایک دوسری حدیث میں ہے کہ اسلام اور کفر کے درمیان جوفرق ہے وہ نماز ہے۔ (مزید تفصیل کے لیےدیکھیے: لفظ صلاة )\n(۳) زکاة: زکاۃ ایک اہم عبادت کے ساتھ ایک طرح کاصدقہ ہے، جوہر اس مسلمان پر سال میں ایک بار نکالنا فرض ہے،جس پر زکاةفرض ہوجائے۔ زکاۃکو ان حاجت مندوں پر خرچ کیاجاتا ہے، جن کاذکر قرآن مجیدمیں موجود ہےاور زکاۃ کےمصارف آٹھ ہیں،اس طرح مال دار اپنے مال کو پاک کرتےہیں۔ان میں ضرورتمندوں کے لیے ہمدردی پیدا ہوتی ہے اور مسلم معاشرہ کے سارے افراد آپس میں بھائی بھائی دکھائی دینے لگتے ہیں۔نہ تو اغنیا فقرا سے نفرت کرتے ہیں اور نہ فقرا اغنیا سے حسد۔\nایک صحیح حدیث میں مذکورہے کہ زکاة مال داروں سے لی جائے گی اور فقرا میں تقسیم کی جائے گی۔\nسونے اور چاندی میں ڈھائی فیصد(۲.۵٪)اور اناج اورغلّےمیں جسے بارش کےذریعے پیدا کیاگیاہے، عشریعنی دس فیصد(۰ا٪) اور جس کونہرکےپانی اورسنچائی کےدوسرے ذرائع سے پیداکیاگیاہے اس میں پانچ فیصد(۵٪)زکاة نکالنے کاحکم ہے۔ (مزید تفصیل کے لیے دیکھیے: لفظ زکاة)\n(۴) صوم(روزہ):اسلام کاچو تھا رکن روزہ ہے۔اس کوعربی میں صوم کہتے ہیں۔سالانہ رمضان کے مہینے میں ایک ماہ کے لیے ہرعاقل وبالغ مسلمان مرد وعورت پر روزہ رکھنا فرض ہے۔یہ روزہ فجرکے طلوع ہونے یعنی اذانِ فجر سےشروع ہوتا ہےاور سورج کے ڈوبنے تک باقی رہتاہے۔اس درمیان ہر طرح کاکھانا پینا اورجنسی خواہش کی تکمیل اور گالی گلوج منع ہے۔روزہ رکھنے سے روح پاک ہوتی ہےاور گناہ ختم ہوتےہیں، جنت میں درجہ اونچاہوتاہے۔ روزے کے بے شمار فوائد ہیں۔ (مزید تفصیل کے لیے دیکھیے لفظ: صوم، روزہ )\n(۵) حج:اس مذہبی سفرکو کہتے ہیں جومکہ مکرمہ کے لیے کیاجاتاہے۔حج کے سفراوراس میں ہونے والے خرچ کی استطاعت رکھنے والےہرمسلمان(مردوعورت)پرزندگی میں ایک بارحج فرض ہے،جوماہ ذی الحجہ کی آٹھویں سے شروع ہوکرتیرہ ذی الحجہ تک کی مدت میں اداکیاجاتاہے،مکہ جاکر وہاں کعبہ شریف کاطواف اورصفاومروہ کی سعی کےعلاوہ آٹھ ذی الحجہ جس کو یوم ترویہ کہتے ہیں منی جاکررات گزارنے کے بعد نویں تاریخ کومیدان عرفات میں وقوف کےلیے روانہ ہوجاتاہے۔حجاج عرفات میں ظہراورعصر کی نمازظہرکےوقت قصراکٹھی اداکرکےسورج ڈوبنے تک ذکرواذکاراوراللہ تعالیٰ کی یاد میں گزارتے ہیں۔سورج ڈوبتے ہی مزدلفہ جاتےہیں اوروہاں مغرب اورعشاکی قصرصلاۃ ایک ساتھ ادا کرتے ہیں اوررات بھرسوکر فجراداکرتےہیں اوراس کے بعد ذکرواذکارکرکے سورج نکلنے سے پہلے منی کے لیے روانہ ہوجاتےہیں۔ دس ذی الحجہ کو منی میں قربانی کی جاتی ہےاوراسی دن جمرۂ کبریٰ کی رمی کی جاتی ہےاورگیارہ بارہ تک منی میں رات گزارکرزوال بعددونوں دن تینوں جمرات کی رمی کی جاتی ہے، اس کے بعد حج کے اعمال ختم ہوجاتے ہیں۔دس ذی الحجہ اوراس کے بعد طواف افاضہ کرناضروری ہے۔ مکہ چھوڑنے سے پہلے الوداعی طواف بھی واجب ہے۔دوران حج سارے حجاج مل کر ایک رب کی عبادت کرتے ہیں۔ایک ہی طرح کالباس پہنتے ہیں۔وہ ایک ایسا منظر ہوتاہے، جہاں امیروغریب،گورے کالے سب ایک لباس میں ہوتے ہیں۔ (مزید تفاصیل کے لیے دیکھے: لفظ حج)\n§اسلا م کی معاشرتی تعلیمات:\nاسلام نے انسان کی انفرادی اور اجتماعی زندگی کو ایک خاص نظام کاپابند بنایاہے۔جس کے ذریعےسے وہ دنیا وآخرت دونوں میں کامیابی حاصل کرسکتاہے۔نکاح کوحلال اورجائزاور زنا کوحرام اورناجائز قرار دیا۔اس طرح سےاسلام نےہر برائی سے روکااور ہر بھلائی کاحکم دیا۔اس کے بعدبھی اگر کوئی شخص برائی سے باز نہ آئے اوردوسروں پر ظلم وزیادتی کرے تواس کے لیے سخت سزا متعین ہے۔جیسے چوری، قتل، زنا، شراب نوشی، یتیموں اورکمزوروں پر ظلم وغیرہ۔پھر اسلا م نے جو سزائیں متعین کی ہیں وہ جرم وزیادتی کے مطابق ہیں۔\nاس طرح اسلام نے حاکم اور محکوم کے تعلق کو بھی واضح کیاہے۔ رعیت کوحکم دیاہے کہ وہ حاکم کے حکم کی اطاعت کریں۔ ان کے خلاف کوئی کام نہ کریں(بہ شرطے کہ ا ن کا حکم االلہورسول کے حکم کے خلاف نہ ہو)کیوں کہ حاکم کے خلاف چلنے میں دنیا میں فساد برپاہوگااورامن وامان کونقصان پہنچے گا،مسلمانوں کااتحاد باقی نہ رہ پائے گا۔\nہم مختصر طور پر کہہ سکتے ہیں کہ اسلام نے االلہ اور بندے کےتعلق کوبہتر طریقے سے بیان کیاہے۔ اسی طرح فرد کاتعلق اپنے معاشرہ کے ساتھ اچھے طریقےپر جوڑاہے۔بھلائی کاکوئی بھی ایسا کام نہیں ہے،جس کاحکم اسلام نے نہ دیا ہو اور کوئی برائی ایسی نہیں ہے جس سے اسلام نے نہ روکا ہو۔یہی ایک سچے اورمکمل دین کی علامت ہے۔لیکن کیا کہا جائےکہ بہت سارے لوگ ان باتوں کونہیں جانتےاور نہ اس کی واقفیت رکھتے ہیں۔اس لیے وہ اسلام پر آئے دن نئے نئےالزامات لگاتے رہتے ہیں۔جب کہ اسلام ان چیزوں سے بری ہے۔","",{}],[39,"§اسم\nاسم یا نام رکھنے اور پھر ناموں سے کسی کو پکارنے کے بارے میں اسلام کی دو اہم تعلیمات ہیں۔\n(۱)اسلام سے قبل اگر کوئی شخص کسی بچے کو منہ بولا بیٹا(لے پالک)بنا لیتا تو وہ بچہ اسشخص کی اولاد کے نام سے جانا جاتاتھا۔ جیسے نبی اکرم صلی اللہ علیہ وسلم نے زید بن حارثہ رضی اللہ عنہ کو اپنا منہ بولا بیٹابنا لیاتھا، لوگ ان کو زید بن محمد کہنے لگے تھے۔ قرآن نے واضح طور سے اس سے منع کردیا: ﴿ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحࣱ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰ ا رَّحِيمًا﴾ [الأحزاب: ۵] \"ان منہ بولے بیٹوں کو ان کے والد کے ناموں سے پکارو۔ یہی اللہ کے نزدیک زیادہ انصاف والی بات ہے\"۔اس لیے اب کسی منہ بولے بیٹے کو منہ بولے والد کے نام سے نہیں پکارا جائے گا اور نہ وہ اس کا والد مانا جائے گا۔ حقیقی باپ بیٹے کے جو احکام ہیں، وہ منہ بولے باپ بیٹے پر نافذ نہیں کیے جائیں گے۔ جیسے میراث اور شادی وغیرہ۔\nاس آیت سے یہ مطلب بھی نکلتا ہے کہ بیٹے کے ساتھ باپ کا نام جوڑناہی مناسب اورشرعی ہے۔ نام کا دوسرا حصہ والد کا ہونا چاہیے۔ نہ ایک ہی شخص کے دو تین نام ہوں۔ جیسے کوئی اپنا نام احمدمحمد عبداللہ رکھے تو یہ مناسب نہیں ہے۔ کیوں کہ کسی صحابی، تابعی، امام،محدث اور کسی دیگر شخص کے بارے میں ایسا نہیں آتا کہ اس نے دو یا تین نام رکھے ہوں۔ لیکن کچھ ممالک میں ایسا ہی ہوتا ہے۔ اس لیےعرب کے لوگوں کو یہ سمجھنا مشکل ہوتا ہے کہ یہ تینوں نام ایک ہی شخص کے ہیں یا اس کا، اس کے والد یا اس کے دادا کے نام ہیں؟جبیربن مطعم بن عدی رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لی خَمْسَةُ أَسْمَاءٍ: أَنَا مُحَمَّدٌ وَأَحْمَدُ وَأَنَا الْمَاحِي الَّذِي يَمْحُو اللَّه بِي الْکُفْرَ، وَأَنَا الْحَاشِرُ الَّذِي يُحْشَرُ النَّاسُ عَلَی قَدَمِي، وَأَنَا الْعَاقِبُ». (صحیح البخاری: ۳۵۳۲) \"میرے پانچ نام ہیں۔میں محمد ہوں، میں احمد ہوں، میں ماحی ہوں جس کے ذریعے اللہ کفر کو مٹاتا ہےاور میں حاشر ہوں جس کے قدموں پر لوگ قیامت میں اٹھیں گے اورمیں عاقب ہوں(جس کے بعد کوئی نبی نہیں آئے گا)\"۔\nآپ صلی اللہ علیہ وسلم کے یہ مبارک اسمائے گرامی،آپ کی خصوصیات بتانے کے لیے ہیں۔ ایک دوسری حدیث میں ابوموسیٰ اشعری رضی اللہ عنہ سےروایت ہےکہ رسول اللہ صلی اللہ علیہ وسلم کہتے ہیں: «أَنَا مُحَمَّدٌ وَأَحْمَدُ وَالْمُقَفِّی وَالْحَاشِرُ وَنبي التَّوْبَةِ وَنبي الرَّحْمَةِ». (صحیح مسلم: ۱۲۶/۲۳۵۵، ۶۲۵۴) \"میں محمد ہوں، میں احمد ہوں، میں مقفّی ہوں، میں نبی التوبہ ہوں،میں نبی الملاحم ہوں\"۔\nبعض علماء نے نبی اکرم صلی اللہ علیہ وسلم کے بیس سے بھی زیادہ نام بتائے ہیں۔ لیکن آپ کا حقیقی نام صرف محمد بن عبداللہ ہی تھا۔\nاسی طرح یہ بھی مناسب نہیں کہ کوئی خاتون اپنی شادی کے بعد اپنے نام کے ساتھ اپنے شوہر کا نام جوڑ لے۔جیسے زینب سے زینب فرید بن جائے۔ اس لیے کہ فرید اس کے شوہر کا نام ہے۔ایسا کرنا قرآن کی مذکور بالا آیت کے خلاف ہے، جس میں کہا گیا ہے: [آیت] \"ان کو ان کے والد کے ناموں سے پکارو\"۔(الاحزاب: ۵)\nاسلام نے عورتوں کی عزت،احترام، وقار اور رتبے کوبڑی اہمیت دی ہے۔اس لیے خواہ وہ غیر شادی شدہ ہو یا شادی شدہ،دونوں صورتوں میں اس کووالد کے نام کے ساتھ ہی پکارا جائے گا۔کبھی اس کو زینب بنت عبداللہ (عبد اللہ کی بیٹی زینب) کہیں گے اورکبھی زینب زوجہ فرید (فرید کی بیوی زینب)کہیں گے۔یہاں زوجہ کا لفظ لگانا لازم ہے۔ تاکہ وہ فرید کی بیٹی نہ بن جائے۔یہ جدید رسم ورواج کی بات ہے، اس میں عورت کی کوئی اہمیت ہی نہیں ہے۔جب وہ غیرشادی شدہ ہوتی ہے تو اس کو مس جارج کہتے ہیں اور جب وہ شادی شدہ ہوجاتی ہے تو مسز لارڈ پکاری جاتی ہے۔ سوال یہ ہے کہ اس کی اپنی شخصیت کہاں گئی؟ کیا یہ عورتوں کے حقوق اور عزت واحترام کے خلاف نہیں ہے؟\n(۲)ناموں کے بارے میں اسلام کی دوسری ہدایت یہ ہے کہ بچوں کے نام مناسب اور اچھے رکھے جائیں۔عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ أَحَبَّ أَسْمَائِکُمْ إِلَی اللَّه عَبْدُ اللَّه وَعَبْدُ الرَّحْمَنِ». (صحیح مسلم: ۲/۲۱۳۲) \"اللہ تعالیٰ کو عبداللہ اور عبدالرحمن نام زیادہ پسند ہیں\"۔\nمطلب یہ ہے کہ وہ نام جس میں اللہ کا بندہ ہونے کا خیال آئے جیسے: عبدالکریم(کریم کابندہ)، عبدالرحیم(رحیم کا بندہ)،عبدالعظیم(عظیم کا بندہ)، عبد الجبار(جبارکا بندہ)، وغیرہ۔ کیوں کہ یہ سب اللہ کے نام ہیں۔اس کےبعد اچھے ناموں میں رسولوں کے نام ہیں۔جیسے: محمد، احمد،آدم، نوح، ابراہیم، اسماعیل، اسحاق، یعقوب، یوسف، سلیمان، موسیٰ، ہارون اور عیسٰی وغیرہ۔اس کے بعد مناسب ناموں میں صحابہ کرام کے نام ہیں۔جیسے: ابوبکر، عمر، عثمان، علی، زبیر، عبیدہ، حسن اور حسین وغیرہ اور اسی طرح سے امہات المومنین اور دیگرصحابیات کے نام پسندیدہ ہیں۔پسندیدہ ناموں میں وہ نام بھی ہیں جن کےمعنی اچھّے ہوں،جیسے: انس، سہل،سہیل،سعد اورسعید وغیرہ۔\nبرے ناموں کے بارے میں ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «أَخْنَی الأَسْمَاءِ يَوْمَ الْقِيَامَةِ عِنْدَ اللَّه رَجُلٌ تَسَمَّی مَلِکَ الأَمْلاکِ».(صحيح البخاری:۶۲۰۵ وصحیح مسلم:۲۱۴۳) \"اللہ کے نزدیک سب سے ناپسندیدہ نام یہ ہے کہ کوئی اپنا نام ملک الملوک( شہنشاہ)رکھے\"۔\nایسے ناموں سے بھی گریز کرناچاہیے جن میں خود کی تعریف ہو جیسے: برہ بہت ثواب کے کام کرنے والی۔ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں آیاہے: «إِنَّ زَيْنَبَ کَانَ اسْمُها بَرَّةَ فَقِيلَ تُزَکِّي نَفْسَها فَسَمَّاها رَسُولُ اللَّه صلی اللہ علیہ وسلم زَيْنَبَ». (صحیح البخاری: ۶۱۹۲ وصحیح مسلم: ۲۱۴۱) \"زینب کا حقیقی نام برہ تھا تونبی اکرم صلی اللہ علیہ وسلم نے ان کا نام زینب رکھ دیا\"۔\nایسے نام کو بھی نبی اکرم صلی اللہ علیہ وسلم نے پسند نہیں کیاجن کے غلط معنیٰ پائے جاتے ہوں۔صحیح حدیث میں آیا ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت حاضر ہوا۔آپ نے اس کا نام پوچھا تواس نےبتایا: حزن (مصیبت اور پریشانی)۔ آپ نے فرمایا: تم حزن نہیں بلکہ سہل ہو۔اس نے کہا:جس نام کو میرے گھروالوں نےرکھا ہے،میں اس کو تبدیل کرنا نہیں چاہتا۔آپ خاموش ہوگئے۔ اسی طرح غیر مناسب ناموں میں فرعون،قارون اور ہامان وغیرہ بھی ہیں۔ جن پر اللہ کا عذاب آچکا ہے۔\nغلط ناموں میں یہ بھی ہے کہ کوئی شخص اللہ کو چھوڑکر کسی اور کے ساتھ اپنی بندگی جوڑے۔ جیسے: عبدالنبی، عبدالرسول اور عبدالکلام وغیرہ۔ اسی طرح غلام بھی چوں کہ بندہ کے معنی میں ہے، اس لیے غلام محمد، غلام رسول اور غلام علی وغیرہ نام رکھنا بھی مناسب نہیں۔\nبچوں کےنام رکھنے کے بارے میں یہ باتیں لڑکےاور لڑکی دونوں کے لیے ہیں۔ لڑکیوں کے نام رکھتے وقت بھی ان باتوں کو ذہن میں رکھنا چاہیے کہ وہ خوبصورت بھی ہوں اور ان سے اللہ کے سوا کسی اور کی بندگی کا خیال نہ آئے۔","",{}],[40,"§اسماعیل علیہ السلام\nاسماعیل کامطلب ہے: االلہ نے سن لیا۔اسماعیل علیہ السلام ابراہیم علیہ السلام کے بڑے بیٹے تھے۔ جب چھیاسی سال کے ہوگئے اور ان کے یہاں کوئی اولاد نہیں ہوئی تو االلہ تعالیٰ سے یہدعا کی:﴿رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمࣲ‏﴾ [الصافات: ۱۰۰-۱۰۱] \"اے میرے رب! مجھے نیک اولادعطا فرما،توہم نے اسے ایک بردبار بچے کی بشارت دی\"۔\nااللہتعالی نے یہ دعاسن لی اور ان کوایک بیٹا عطا کیا۔اسی لیےانھوں نے اپنے اس بیٹے کانام اسماعیل رکھا۔ یہ بردبار بچہ اسماعیل ہی تھے۔\nایساماناجاتاہے کہ اسماعیل کی پیدایش (۲۲۴۸ ق.م.) ہبرون نامی شہر کےقریب ہوئی تھی۔ اسماعیل کی پیدایش کےچودہ پندرہ سال بعد ابراہیم علیہ السلام کے یہاں دوسرا بیٹا پیداہوا،اس کانام انھوں نے اسحاق رکھااور االلہ تعالیٰ کی تعریف میں یہ کلمات اداکیے: ﴿ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي وَهَبَ لِي عَلَى ٱلۡكِبَرِ إِسۡمَٰعِيلَ وَإِسۡحَٰقَۚ إِنَّ رَبِّي لَسَمِيعُ ٱلدُّعَآءِ﴾ [إبراهیم: ۳۹] \"تمام تعریفیں اس االلہ کے لیے ہیں جس نے مجھے بڑی عمر میں اسماعیل اور اسحاق دیے۔ بےشک میرا ر ب دعا کاسننے والا ہے\"۔\nقرآن مجیدمیں ذکرہے کہ ابراہیم کوبہت ساری آزمایشوں سےگزرنا پڑا۔وہ ایک بار اپنی بیوی ہاجرہ اور بیٹے اسماعیل کولے کر ہبرون سے نکل پڑے اور ماں بیٹے کوعرب کے ریگستانی علاقے مکہ میں چھوڑکر جانے لگےتو ہاجرہ نے پوچھا: اےابراہیم!آپ ہمیں یہاں چھوڑکر کہاں جارہےہیں؟انھوں نے کوئی جواب نہیں دیا۔پھر ہاجرہ نےپوچھا: کیا االلہ کا یہی حکم ہے؟کہا: ہاں،اس پر ہاجرہ نے کہا: پھر توہمارا رب ہمیں ضائع نہیں کرے گا۔یہاں سے واپس جاتے وقت ابراہیم علیہ السلام نے دعاکی: ﴿رَّبَّنَآ إِنِّيٓ أَسۡكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيۡرِ ذِي زَرۡعٍ عِندَ بَيۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِيُقِيمُواْ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةࣰ مِّنَ ٱلنَّاسِ تَهۡوِيٓ إِلَيۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَشۡكُرُونَ﴾ [إبراهیم: ۳۷] \"اے ہمارے رب!میں نے اپنی کچھ اولاد اس بے کھیتی کی وادی میں تیرے حرمت والے گھرکے پاس بسائی ہے۔اے ہمارے رب!یہ اس لیے کہ وہ نماز قائم رکھیں پس تو کچھ لوگوں کے دلوں کوان کی طرف مائل کردےاور انھیں پھلوں کی روزیاں عنایت فرما۔ تاکہ وہ شکر گزاری کریں\"۔\nعبداللہ بن عباس رضی اللہ عنہما کہتےہیں: \"پھر ایک وقت وہ بھی آیا جب ہاجرہ کےپاس مشک میں جو پانی تھا وہ ختم ہوگیا اور ان کاننها بچہ پانی کے لیے تڑپنےلگا۔ ماں سےیہ دیکھا نہیں گیا۔ وہ اٹھ کھڑیہوئیں تاکہ پتا لگائیں کہ یہاں آس پاس پانی کاکوئی چشمہ ہے یانہیں؟ سب سے قریب پہاڑی صفا تھی، وہ اس پر چڑھ گئیں مگر وہاں نہ توکوئی انسان دکھائی دیا اور نہ پانی کاکوئی چشمہ ملا۔پھرنیچےوادی میں اترگئیں اور بھاگتی ہوئی دوسری پہاڑی مروہ پر چڑھ گئیں تاکہ پانی کاکوئی چشمہ ملے۔اس طرح انھوں نےصفا اور مروہ کےسات چکر لگائے مگر انھیں پانی کاکوئی چشمہ دکھائی نہیں دیا۔(ان کے ان سات چکروں کے لگانے کی یاد میں مسلمان حج یاعمرہ کرتے وقت صفااورمروہ کے سات چکر لگاتے ہیں)پھر جب وہ مروہ کے قریب پہنچیں توانھوں نےایک آواز سنی جوکسی فرشتے کی تھی۔اس نےاپنے پاؤں اورپروں سے زمین کھودی جس سے وہاں پانی نکل آیا۔ جس کوزمزم کہتے ہیں۔آج تک یہ پانی اس مقام پرنکلتا جارہاہے اور اتنا ہے کہ بیس تیس لاکھ حاجی اسے پیتے ہیں استعمال کرتے ہیں اور اپنے ملکوں کوبھی لے جاتے ہیں۔مگر وہ ختم نہیں ہوتا دنیا حیرت زدہ ہے کہ اس ریگستان میں یہ چشمہ کہاں سے آرہاہے۔اس طر ح ہاجرہ اور ان کے بیٹے اسماعیل مکہ میں کعبہ کے قریب رہنے لگے۔ پھر یمن کاایک قبیلۂ جرہم ادھر نکل آیا۔انهوں نے جب دیکھا کہ اس وادی میں پانی پایا جاتاہے تواسماعیل کی ماں ہاجرہ سے وہاں رہنے کی اجازت طلب کی جس کوہاجرہ نےقبول کرلیا۔ اسماعیل جوان ہوگئے تو قبیلہ جرہم کی ایک لڑکی سے شادی کرلی۔پھر اسماعیل کی ماں ہاجرہ کی وفات ہوگئی ان کومکہ میں ہی دفن کردیاگیا۔کچھ لوگوں کاخیال ہے کہ ان کواور ان کے بیٹے اسماعیل کو خانہ کعبہ میں حجر کے مقام پر دفن کیا گیاہے۔لیکن اس کاکوئی ثبوت نہیں ہے۔ ایک بار ابراہیم علیہ السلام مکہ آئے۔ اس وقت اسماعیل گھر پر نہیں تھے۔انھوں نے ان کی بیوی سے سوال کیا: تم لوگ کیسے ہو؟ اس نے کہا: بہت تکلیف اور تنگ دستی میں ہیں۔ ابراہیم علیہ السلام نے کہا: جب اسماعیل آئے تواس کو میرا سلام کہنا اور یہ بھی کہہ دینا کہ اپنے دروازے کی چوکھٹ بدل دے۔ اسماعیل علیہ السلام کوان کی بیوی نے جب یہ بات بتائی تووہ سمجھ گئےکہ وہ میرے والد ابراہیم تھے اور دروازے کی چوکھٹ بدلنے سے ان کامطلب یہ تھا کہ میں اس بیوی کوطلاق دےدوں۔چنانچہ اسماعیل نے اپنی اس بیوی کوطلاق دے دی اور قبیلۂ جرہم ہی کی ایک دوسری خاتون سے شادی کرلی۔کچھ دنوں بعد ابراہیم علیہ السلام دوبارہ مکہ آئے اور اسماعیل کی بیوی سےپوچھا: تم لوگ کیسے ہو؟ اس نے کہا: الحمداللہ ہم لوگ بہت آرام سے ہیں۔ پوچھا: تم لوگ کیاکھاتے ہو؟ اس نے جواب دیا: گوشت پوچھا: کیا پیتے ہو؟ جواب دیا:پانی۔ ابراہیم علیہ السلام نےگوشت اور پانی کے لیے دعا کی۔یہی وجہ ہے کہ مکہ میں رہنے والوں کوگوشت اور پانی ضرور ملتا ہے۔ پھر ابراہیم نے اس سے کہا: جب تمھارے شوہر آئیں تو ان سےمیرا سلام کہہ دینا اور یہ بھی کہہ دینا کہ اپنے دروازے کی چوکھٹ کوباقی رکھیں۔اسماعیل کے آنے پر ان کی بیوی نے یہ ساری باتیں بتائیں توانھوں نے کہا: وہ میرے والد تھے اور چوکھٹ تم ہو۔انھوں نے مجھے حکم دیا ہے کہ میں تم کواپنے پاس رکھوں\"۔ (صحیح البخاری: ۳۳۶۴)\nاس سے معلوم ہوتا ہے کہ اسماعیل کی دونوں بیویاں قبیلۂ جرہم سے تھیں۔ بائبل کایہ ذکر کرنا کہ ہاجرہ نے اسماعیل کےلیےمصر سے بیوی منگوائی تھی، سچ نہیں معلوم ہوتا۔ یہ اس لیے بھی کہ طبری وغیرہ مورخین نے اسماعیل کے جوبارہ بیٹے بیان کئے ہیں، ان کی ماں سید مزاز بن عمرو کی بیٹی تھی،جوقبیلہ جرہم سے تھی۔\nعرب اسماعیل علیہ السلام کے بیٹےنباط اور قیدار کے خاندان سے ہیں۔نبی اکرم صلی اللہ علیہ وسلم اسماعیل علیہ السلام کی ذریت میں سے تھے۔اس لیے ان کو اْمّی کہا گیا ہے۔آپ بنی اسرائیل میں سے نہیں تھے اور یہودی اپنے علاوہ سب لوگوں کوامی کہا کرتے تھے۔ (تاریخ طبری ۲:/۴ا۳)\nااللہ تعالیٰ نے اسماعیل علیہ السلام کوبھی نبی بنایا۔ (مریم:۵۴) ان کوعمالیق اور اہل یمن کی جانب مبعوث کیا۔عمالیق کاعلاقہ حجاز سے لے کر سینا اور شام تک وسیع تھا۔یہ بھی ایک عربی قبیلہ تھا،لیکن اس کی اصل معلوم نہیں ہوسکی۔\nبائبل میں ہے: عیسوکے بیٹے الیفز کی بیوی تمنع سے عمالیق پیدا ہوے۔ (پیدایش: ۳۶:۲ا)\nبیان کیا جاتا ہےکہ اسماعیل علیہ السلام ایک سوسنیتالیس سال کی عمرمیں انتقال کرگئے۔ مکہ میں اپنی والدہ ہاجرہ کےقریب دفن کردیے گئے،یہ کہنا کہ دونوں خانہ کعبہ میں حجر کے اندر دفن ہیں کسی صحیح حدیث سے ثابت نہیں۔یہ بات صرف مورخین جیسے طبری اور ابن کثیر وغیرہ نے لکھی ہے۔","",{}],[41,"§آسمان\nدیکھیے: سماء","",{}],[42,"§اسماےحسنی\nاللہ تعالیٰ کی خوبیوں کوبیان کرناانس وجن کی طاقت سے باہرہے۔خوداللہ تعالیٰ کا ارشادہے:﴿قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادࣰ ا لِّكَلِمَٰتِ رَبِّي لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدࣰ ا﴾ [الکهف: ۱۰۹] \"کہہ دو کہ اگرمیرے رب کی باتوں کے لکھنے کے لیے سمندر سیاہی بن جائے تووہ بھی میرے رب کی باتوں کے ختم ہونے سے قبل ہی ختم ہوجائےگا، گوہم اس جیسا اور بھی(سمندر) اس کی مدد میں لے آئیں\"۔\nاللہ تعالیٰ نےاپنےناموں اوراپنی خوبیوں کوخودبیان فرمایاہے۔اس کےسارے نام اورسارے اوصاف وکمالات مبارک اور خوبصورت ہیں۔جیسا کہ قرآن مجیدمیں خود اللہ کا فرمان ہے:﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ﴾ [الأعراف: ۱۸۰] \"اللہ تعالی کے اچھے اور خوبصورت نام ہیں، تم اسے اُنهیں ناموں سے پکارو۔ اور ان لوگوں کو چھوڑوجواس کے ناموں کے بارے میں کجروی کرتے ہیں جو کچھ وہ کرتے ہیں اس کا بدلہ وہ پا جائیں گے\"۔\nاسماےحسنی دو جگہوں پر استعمال ہوتے ہیں:\nاول یہ کہ ان کے ذریعےسےاللہ تعالی سےدعاکی جائے۔جیسے کوئی یہ دعا کرے:اے معاف کرنے والےمجھے معاف کردے۔اے رحم کرنے والے مجھ پر رحم کر۔اے رزق دینے والے مجھے رزق عطاکر،ان ناموں کے ذریعے صرف اللہ تعالی سے دعاکی جائے۔کسی اور سے نہ کی جائے اورنہ کسی غیر کوان ناموں سے پکاریں اورنہ ہی کسی کو یہ نام دیں۔\nدوم یہ کہ انھی ناموں کے مطابق اللہ تعالی کی عبادت کی جائے۔جیسے اس کے سامنے ہم اس لیے توبہ و استغفارکریں کہ وہی بندوں کی توبہ قبول کرسکتاہے۔ اس کے سامنے اس لیےجھکیں کہ وہی عظیم اور عالی ہے۔اس کی عظمت اورکبریائی میں کوئی شریک نہیں۔ اس لیے مسلمان پانچ وقت کی نمازوں میں صرف اللہ ہی کو سجدہ کرتے ہیں۔ اس کا حکم ہے:\n۱- ﴿تَسۡجُدُواْ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ﴾ [فصلت: ۳۷] \"تم نہ تو سورج کو سجدہ کرو اور نہ چاند کو سجدہ کرو بلکہ اس اللہ کو سجدہ کرو جس نے ان سب کو پیدا کیا ہے۔اگر تم واقعی اسی اللہ کی عبادت کرتےہو\"۔\n۲- ﴿وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلࣰ ا طَوِيلًا﴾ [الإنسان: ۲۶] \"اور رات کے وقت کچھ حصے میں بھی سجدہ کرو اور بہت رات تک اسی کی تسبیح کیا کرو\"۔\nایک صحیح حدیث میں ہے کہ اللہ تعالی کے ننانوے نام ہیں، جو ان کااحصااور استیعاب کرے گا،جنت میں جائے گا۔\nابو ہریرہ رضی اللہ عنہ سے مروی حدیث میں آیاہے: «لِلَّه تِسْعَةٌ وَتِسْعُونَ اسْمًا مِائَةٌ إِلا وَاحِدًا لايَحْفَظُها أَحَدٌ إِلا دَخَلَ الْجَنَّةَ وَهوَ وَتْرٌ يُحِبُّ الْوَتْرَ».(صحيح البخاری: ۶۴۱۰ وصحیح مسلم: ۲۶۷۷/۵) \" اللہ تعالیٰ کے ننانوے نام ہیں، ایک کم سو۔ جوشخص بھی انھیں یاد رکھے گا، جنت میں جائےگا۔ اللہ تعالی طاق ہے اور طاق کو پسند کرتا ہے\"۔\nعلماءکے نزدیک اس حدیث کا مطلب یہ نہیں ہےکہ اللہ تعالیٰ کے صرف ننانوے نام ہی ہیں،بلکہ اس کا مطلب یہ ہےکہ جو شخص ان ننانوے ناموں کو یاد کرکےاس کے مطابق زندگی گزارے گا۔ اپنی عبادت اور اطاعت کے کام انجام دےگا۔ان کے ذریعے وہ اپنے رب سے مانگے گا، وہ جنت میں جائے گا۔رہے اللہ تعالی کے اسماے گرامی تواس کا علم صرف اللہ تعالیٰ کوہے،اسی لیے قرآن مجیدمیں ہے:\n۱- ﴿قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيࣰّ ا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلࣰ ا﴾ [الإسراء: ۱۱۰] \"کہہ دیجیے کہ رب تعالی کو اللہ کہہ کر پکارو یا رحمٰن کہہ کر، جس نام سے بھی پکارو، تمام اچھے نام اسی کے ہیں۔ نہ تو تو اپنی نماز بہت بلند آواز سے پڑھ اور نہ بالکل پوشیدہ، بل کہ اس کے درمیان کا راستا تلاش کر لے\"۔\n۲- ﴿وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ﴾ [الأعراف: ۱۸۰] \"اور اچھے اچھے نام اللہ ہی کے لیے ہیں۔ اس لیے تم ان کے ذریعے اسے پکارو۔ (دعاکرو)اور ایسے لوگوں کو چھوڑ دوجو اس کے ناموں میں کج روی کرتے ہیں\"۔\nمطلب یہ ہے کہ اس کو ایسے ناموں سے نہ پکارو جو اس کی شان کے خلاف ہوں اور نہ اس کے ناموں کاخود ساختہ مطلب نکال کر اس کی بے عزتی کرو۔ نہ اس کےجیسے نام کسی اور کے رکھو، کیوں کہ یہ سب وہ امور ہیں جن سے شرک کادروازہ کھلتا ہےاور قرآن میں شرک کو سب سے بڑاظلم کہاگیاہے۔\nاگرہم گزشتہ اقوام کی تاریخ کا مطالعہ کر یں تو واضح طور پرنظر آے گا کہ ان میں شرک کےفروغ کابڑاسبب اللہ کےاسماے گرامی میں کج روی اور الحاد پیداکرناتھا۔جیسے یہودیوں نے اسےیہوواکا نام دےدیا، جس کا مطلب صرف قوم یہود کا رب ہے۔اسی طرح نصاریٰ نے اسےفادر (باپ) کانام دیا۔ اسی وجہ سے اُنھیں عیسی علیہ السلام کواللہ کابیٹابنانے کی ضرورت پڑی۔دوسری اقوام نے بھی اللہ تعالیٰ کے ایسے نام رکھے جو ان کے مزاج اور نظریے کے موافق تھے۔ پھر اس نظر یے کو ہی اللہ بنالیا۔جیسا کہ ہندو مذہب میں ایشور(اللہ)کے لیے سویتا کالفظ مستعمل ہے،جو سورج کےلیےبھی استعمال ہوتا ہے۔اس لیے سورج کو بھی معبودبنالیا گیا۔ مکہ کے کفار ومشرکین نے اللہ کے نام عزیز سے عزیٰ نام کا بت بنالیا۔الہ سےلات نامی بت بنالیااور اس کی عبادت وپرستش کرنے لگے۔قرآن مجید اس طرف اشارہ کرتےہوے بیان کرتاہے:﴿كَمِثۡلِهِۦ شَيۡءࣱۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ﴾ [الشوری: ۱۱] \"اس جیسی کوئی چیز نہیں اور وہ سب کچھ سمیع وبصیر( سننے اور دیکھنے والا)ہے\"۔\nاللہ تعالی بےخبراور غافل نہیں، بلکہ با خبر اور جاننے دیکھنےوالا ہے۔لیکن اپنی مخلوق سے علاحدہ ہے۔ اس لیےاس کے ناموں کی تعیین میں ہمیں بے حد احتیاط کرنی چاہیے۔اس کاسب سے بہتراصول اور ضابطہ یہ ہے کہ قرآن اورصحیح احادیث ثابت شدہ ناموں کو سامنے رکھا جائے۔\nبعض احادیث میں اللہ تعالی کےمختلف اسما آئے ہیں۔سنن ترمذی(۳۵۰۷)اورسنن ابن ماجہ (۳۸۶۱) کی ایک حدیث میں ننانوے ناموں کاذکر ہے۔لیکن اس کی سندضعیف ہے۔صحیح بات یہ ہے کہ قرآن اور صحیح احادیث کی روشنی میں انھیں جمع کرناچاہیے،چنانچہ متعدد علماے اسلام نےان ناموں کوجمع کرنے کی کوشش کی ہے۔ مثال کے طورپر حافظ ابن حجرنے فتح الباری میں ننانوے اسماے حسنی کا ذکرکیا ہے۔معاصرعلماءمیں علامہ ابن عثیمین نے بھی کتاب وسنت کی روشنی میں ان اسماےمبارکہ کا ذکر کیاہے۔یہاں ان کی تالیف القواعدالمثلی فی اسماءاللہ الحسنی سے یہ نام ان کے معانی کے ساتھ ذکر کیے جاتے ہیں:\n۱-اللہ : رب عزوجل کا یہ اسم ذاتی ہے۔ یہ سب ناموں سے اشرف و اعلی اورسارےاوصاف حسنہ وخصائص جمیلہ کاجامع ہے۔ یہ نام سارےاسماء وصفات حسنہ کو اپنے اندرسموئےاوران کااحاطہ کئے ہوے ہے۔ (سورہ الفاتحہ: ۱)\n۲-احد:اکیلا اوریکتاذات۔اللہ تعالی ہرطرح کےمجدوشرف،جلال وجمال،حکمت وکمال،حمدوثنااوررحمت ورأفت میں سب سےمنفرداورالگ ہے۔اللہ تعالی کی کوئی نظیرنہیں ہے۔ (سورہ الاخلاص)\n۳-آخر: ہرچیزکے بعد،اللہ تعالی کوبقااور دوام حاصل ہے۔(سورہ الحدید: ۳)\n۴-اعلی: علوسےافعل کےوزن پراسم تفضیل اورمبالغےکاصیغہ ہے۔اللہ تعالی سب سے بلندوبالا ہے۔ اس سےبلندکوئی چیزنہیں ہے۔ (سورہ الاعلی)\n۵-اکرم: کرم سےاکرم اسم تفضیل اورمبالغےکاصیغہ ہے۔بڑی بزرگی اور عظمت والا۔یہ اللہ تعالی کا ذاتی وصف ہے۔وہ اکرم الاکرمین ہے۔کوئی بڑائی اوربزرگی اس کےبرابرنہیں ہے۔ سب اس کے سامنے بےحقیقت اورحقیرہیں۔(سورہ العلق: ۳)\n۶-الہ : معبودبرحق،حقیقی معنی میں صرف عبادت کے لیے لائق اللہ تعالی ہے۔(سورہ البقرۃ: ۲۵۵)\n۷-اول: اول یعنی سب سے پہلا، جودوسری اشیاءسے سابق ہے۔(سورہ الحدید: ۳)\n۸-باری: کائنات اوراس میں پائی جانے والی ہرچیزکاموجدوخالق۔(سورہ الحشر: ۲۴)\n۹-باطن: ہرچیزکااحاطہ کرنےوالاحتی کہ اللہ تعالی ہرچیزکی جان سے زیادہ اس کے قریب ہے۔(سورہ الحدید: ۳)\n۱۰-بَرّ:براورباردونوں اسم فاعل ہیں،وسیع پیمانےپراچھا سلوک واحسان کرنے والا۔ (سورہ الطور: ۲۸)\n۱۱-بصیر: بصریبصرسے مبالغےکاصیغہ ہے۔سب کچھ دیکھنےاورہرچیزکاعلم رکھنے والا۔(سورہ الشوری: ۱۱)\n۱۲-تواب: تاب یتوب توبۃ سےمبالغےکاصیغہ ہے۔ اللہ تعالی بندوں کوتوبہ کی توفیق دینے والا، ان کی توبہ قبول کرنےاوران کےگناہوں کو معاف کرنے والا ہے۔(سورہ البقرۃ: ۳۷)\n۱۳-جبار: جبرسےمبالغے کاصیغہ ہے۔اللہ تعالی ضعیفوں اورکمزوروں کی کمزوری کو دورکرنےوالااور ایسےٹوٹےدلوں کوجو اس کی عظمت اورجاہ وجلال کے سامنے جھکتے ہیں جوڑنے والاہے۔ اس کی عظمت وجلال کےسامنے ہرچیزسرنگوں اور اس کی عزت وجبروت کے سامنے ہرمخلوق سجدہ ریزہے۔ (سورہ الحشر: ۲۳)\n۱۴-حافظ:حفظ سے حافظ اسم فاعل ہے۔حفاظت کرنے والا۔(سورہ یوسف: ۶۴)\n۱۵-حفیظ: مبالغےکاصیغہ ہے۔یہ اللہ تعالی کاذاتی وصف ہے، جس کے معنی علیم یعنی بڑے جاننے والے کے ہیں،اس لیے کہ اللہ تعالی ساری معلومات کو محفوظ رکھتاہے۔اس کے علم سےکوئی چیز باہرنہیں ہے۔ اللہ تعالی ہروجودکی حفاظت اور اس کی نگہبانی کرنے والاہے۔(سورہ ہود: ۵۷)\n۱۶-حسیب: حسب یحسب سےمبالغےکاصیغہ ہے۔صرف اللہ تعالی بندوں کے لیے کافی ہے۔اس کے ساتھ کسی اورکی ضرورت نہیں ہے۔اللہ تعالی کوبندوں کےحالات کا علم ہے۔اس پربھروسہ کرنے والوں کےلیےوہ کافی ہے۔وہ اپنی حکمت اورعلم کے بموجب بندوں کےہرچھوٹےبڑےخیراور شر پران کو جزا اورسزا دینےوالاہے۔(سورہ النساء: ۸۶، الاحزاب: ۳۹)\n۱۷-حفيّ: فعیل کےوزن پرمبالغےکاصیغہ ہے۔عزت واکرام والا، اظہارخوشی میں مبالغہ کرنے والا، پوری طرح علم رکھنے والا۔باراورلطیف کےمعنی میں یعنی اللہ تعالی اپنےلطف وکرم سے اخلاص اورعبادت کی طرف ہدایت کرنےوالااورگناہوں کومعاف کرنے والا ہے۔(سورہ الاعراف: ۱۸۷، مریم: ۴۷)\n۱۸-حق: حق کا معنی سچ کے ہیں۔اللہ تعالی حق اورسچ ہے،اس کا کلام حق ہے، اس کا وعدہ اور وعیدحق ہےاور اس کے افعال حق ہیں۔ وہ حی وقیوم ابدی حیات والی ذات ہے، جس سے زوال اور فنانہیں ہے۔ وہ اپنےکلام کےذریعے حق کو ثابت کرتاہے۔وہ حق ہے، وہ اپنے اسماء وصفات، الوہیت اور ربوبیت میں ایک ایسی حقیقت ہےجوجھٹلائی نہیں جاسکتی۔(سورہ النمل: ۷۹)\n۱۹-حکیم:مبالغےکاصیغہ ہے۔اللہ تعالی کمال حکمت سےمتصف اورمخلوقات کےدرمیان فیصلہ کرنے والاہے۔وہ وسیع علم والاہے۔اس کےقول وفعل میں سراسرحکمت ہے۔(سورہ الانعام: ۱۸، الانفال: ۶۸)\n۲۰-حلیم: حلم سےمبالغےکاصیغہ ہے۔بردبار،گناہوں پرسزادینے میں جلدبازی سے کام نہ لینے والا، ضبط کرنے والا، معاف کرنے والا۔(سورہ البقرۃ :۲۶۳، الاسرا: ۴۴)\n۲۱-حمید:حمد سےمبالغےکاصیغہ ہے۔بہت زیادہ خوبیوں والااورقابلِ تعریف،جس کی تعریف وتوصیف میں ہرچیزرطب اللسان ہے اور جو ہرطرح کی حمدوثناکالائق وسزاوار ہے۔(سورہ البقرۃ :۲۶۷، فاطر: ۱۵)\n۲۲-حی: زندہ۔حی اورقیوم کواسم اعظم کہاجاتاہے۔اللہ تعالی کو دائمی اورکامل حیات حاصل ہے، جس کے ابتدااور انتہاکی تحدیدنہیں کی جاسکتی۔اس کے لیے موت اور فنا جائز نہیں ہے۔حیات اور زندگی اللہ تعالی کاذاتی وصف ہے۔ اس کی حیات کامل ترین اورجاوداں ہے۔(سورہ البقرۃ: ۲۵۵، الفرقان: ۵۸)\n۲۳-خالق:خلق سے اسم فاعل ہے۔ اللہ تعالی سابق مثال کےبغیر ہرمعدوم چیزکاخالق اورسب کو پیداکرنےاوروجود بخشنے والاہے۔(الحشر: ۲۴)\n۲۴-خلاق: مبالغے کا صیغہ ہے۔اللہ تعالی کائنات اوراس میں پائی جانے والی ہرمعدوم اورناپیدچیز کا اولین خالق وموجد اور پیدا کرنے والا ہے۔(سورہ الحجر: ۸۶)\n۲۵-خبیر: خبر یخبرسےمبالغےکاصیغہ ہے۔اللہ تعالی کائنات کی ہرچیزپرمطلع اور سب کی خبررکهنے والاہے۔(سورہ الملک: ۱۴)\n۲۶-رحمن : رحمن کا نام اللہ تعالی کی ذاتی صفت پردلالت کرتا ہے، جو اس کے ساتھ قائم ودائم ہے۔ اللہ سب پربڑا مہربان اوربہت رحم کرنے والا ہے۔اس کی رحمت عام ہے۔(سورہ الفاتحہ)\n۲۷-رحیم: اللہ تعالی کافعلی وصف ہے۔ اس صفت کا اہل ایمان کے ساتھ خاص تعلق ہے۔وہ خصوصی طور آخرت میں اہل ایمان پرمہربانی کرنے والاہے۔(سورہ الفاتحہ)\n۲۸-رزاق: رزق سےرزاق مبالغے کا صیغہ کاہے۔ رزق اللہ تعالی کی فعلی صفت ہے۔اللہ تعالی کی طرف سےعطاکردہ روزی اور نعمت کو رزق کہتے ہیں۔اللہ تعالی کے رزاق ہونے کا مطلب یہ ہے کہ اس نےمخلوق کے رزق کا ذمہ خود لیاہے۔ہرنفس کو اس کی ضرورت کے مطابق روزی عطاکرنے کا کام وہ خود کرتا ہے۔اس کی رحمت اوررزق ساری مخلوقات کااحاطہ کئے ہوے ہے،مومن وکافراور دوست ودشمن کا اس میں کوئی امتیاز نہیں ہے، انسانی علوم ومعارف میں سے وہ سب کو عطافرماتاہے، لیکن ایمان وتقوی اور علم وعرفان کی دولت سے وہ صرف اپنے مومن بندوں کو نوازتا ہے۔(سورہ الذاریات: ۵۸)\n۲۹-رقیب: مبالغے کا صیغہ ہے۔اس کا معنی حفیظ یعنی حفاظت کرنے والے اورنگہبان اور نگراں کے ہیں۔اللہ تعالی ہرچیزکی حفاظت کا ذمہ دار۔رقیب اور شہید مترادف کلمات ہیں، دونوں سے پتا چلتا ہے کہ ہرچھوٹی بڑی چیز اللہ تعالی کی نگاہ میں ہے۔ ا س کا علم ہر چیز پر محیط ہے۔ وہ دلوں کے اسرارورموز سے واقف ہے۔ اس کی قدرت کا یہ حال ہے تو انسان کے تمام تر حرکات وسکنات کا علم اس کے پاس کیوں نہ ہوگا۔(سورہ النساء: ۱، المائدۃ: ۱۱۷)\n۳۰-روؤف: رأفت سےمبالغے کا صیغہ ہے۔اللہ تعالی شفقت ورحمت والا اورمہربان ہے۔(سورہ النور: ۲۰)\n۳۱-سلام: اللہ تعالی سلامتی والاہے، وہ صرف خیراور بھلائی سے متصف ہے۔ اس کی ذات ہرعیب ونقص سے پاک ہے۔اللہ تعالی جنت میں اپنے بندوں کو سلام کرے گا۔(سورہ یسین: ۵۸) سب اس کے ظلم سے محفوظ ہیں۔(سورہ الحشر: ۲۳)\n۳۲-سمیع: سمع یسمع سےسمیع مبالغے کا صیغہ ہے،اور سمع (سننا) اللہ تعالی کاذاتی وصف ہے۔اللہ تعالی مخلوقات کی آوازوں کو خوب سنتاہے۔ اس کے نزدیک خفیہ اورراز کی باتیں اور کھلے امور سب برابر ہیں۔ کوئی چیز اس کے علم کی گرفت سے باہر نہیں ہے۔ وہ اپنے بندوں کی دعاؤں کو سننے اور قبول کرنے والا ہے۔ وہ سب کی سنتااور انھیں سمجھتاہے۔ وہ دعاؤں کو قبول کرنے والا ہے۔(سورہ الشوری: ۱۱)\n۳۳-شاکر: شکراداکرنے والا۔ (سورہ النساء: ۱۴۷)\n۳۴-شکور: شکر سےمبالغے کا صیغہ ہے۔اللہ تعالی ہلکی پھلکی عبادت پربھی زیادہ سےزیادہ ثواب عطاکرنے والااور معمولی شکرکی ادائی پر بندوں سے راضی ہونے والاہے۔(سورہ التغابن: ۱۷، فاطر: ۳۰)\n۳۵-شہید: علیم کے معنی میں،بڑےعلم والا جوعالم الغیب والشہادۃ ہے، ساری باتیں اس کے مشاہدے میں ہیں۔ اس پر کوئی چیز مخفی نہیں ہے۔(الانعام: ۱۹)\n۳۶-صمد: اللہ تعالی کھانےپینے،سونے،کمزوری اورتکان سےبےنیازذات ہے۔سب اس کے محتاج ہیں،کو کسی بھی محتاج نہیں ہے۔ وہ عظیم سردار ہے، جس کی سرداری درجۂ کمال کو پہنچی ہوئی ہے اور جو اپنےعلم، حکمت، حلم،قدرت، عزت،عظمت اور غنی اورساری صفات میں کامل ترین ہے۔ (سورہ الاخلاص)\n۳۷-ظاہر: اللہ تعالی بلنداورغالب ہے۔ہرچیزاس سے کمتر ہے۔ وہ ہرچیزسے بلندہے،اس سے بلندکوئی اورچیز نہیں۔ (سورہ الحدید: ۳)\n۳۸-عالم: علم سے اسم فاعل ہے۔اللہ تعالی ہرچیزکاعلم رکھنے اور اسے جاننے والاہے۔(سورہ الحشر: ۲۲)\n۳۹-علیم: علم سےمبالغے کاصیغہ ہے۔ اللہ تعالی کائنات کےسارے اسرار ورموزکا واقف کار، ماضی حال اورمستقبل کا علم رکھنے والا۔(سورہ النساء: ۱۱، المائدۃ: ۹۷)\n۴۰-عزیز: مبالغے کا صیغہ ہے۔ اللہ تعالی غالب،قوت وطاقت اورقہروغلبہ میں سب پرفائق، مقتدر اورناقابل تسخیر ہستی ہے۔(سورہ الزمر:۱)\n۴۱-عظیم: مبالغے کا صیغہ ہے۔وہ اپنی ذات، اسماوصفات اورافعال واحکام اورامرونہی میں سب سے بڑا اور عظمت والاہے۔(سورہ البقرہ: ۲۵۵، الواقعہ: ۷۴، الحاقہ: ۳۳)\n۴۲-عفوّ: فعول کے وزن پرعفوّ مبالغے کا صیغہ ہے۔ اللہ تعالی توبہ واستغفارکرنےوالوں اور ایمان وعمل صالح کرنے والوں سے درگذر کرنے والااوران کے گناہوں کو معاف کرنے والا۔(سورہ النساء: ۴۳)\n۴۳-عليّ: مطلق علواوربلندی اللہ تعالی کی ذاتی صفت ہے، وہ عليّ اور اعلی ہےیعنی اس کی ذات ہراعتبار سےسب سے بلنداور سب سےاوپرمخلوقات سےالگ عرش کےاوپر بلندی پر ہے۔(سورہ البقرۃ: ۲۵۵)\n۴۴،۴۵-غفاروغفور: دونوں مبالغے کے صیغے ہیں۔ اللہ تعالی بہت بخشنے والا ہے۔ وہ آدمی کے گناہوں کو عیاں نہیں کرتابل کہ اُن کو ڈھانپ لیتاہے،انھیں ظاہرنہیں ہونے دیتااور اس پر مزیدوہ بندے کےگناہوں کو بخش دیتاہے۔غافربھی اللہ تعالی کے ناموں میں سے ہے۔(غفار: سورہ النوح: ۱۰، الزمر: ۵ غفور: فاطر: ۲۸)\n۴۶-غنی: مبالغے کا صیغہ ہے۔سب سے بے نیازاورسب سے مال دار۔(سورہ ابراہیم: ۸)\n۴۷-فتاح: فتح سےمبالغے کا صیغہ ہے۔ اللہ تعالی سب سےبڑا فاتح اور سب کا حاکم،دشمنانان دین پر اپنے نیک بندوں کوفتح ونصرت دینے والا،بندوں پر ہرخیروشراورنفع ونقصان اوردینے اور نہ دینے کا دروازہ کھولنے والا اور ان کے اسباب فراہم کرنے والا ہے۔(سورہ سبا:۲۶)\n۴۸-قادر: اسم فاعل ہے۔قدرت والا۔اللہ تعالی ہرچیزپر قادر ہے۔(سورہ الانعام: ۶۵)\n۴۹-قدیر: مبالغے کاصیغہ ہے۔کامل قدرت والا، جس نے کائنات کو وجودبخشااور اپنی قدرت سے نظام عالم کو پختہ اور مستحکم بنایا۔(سورہ البقرۃ: ۲۰)\n۵۰، ۵۱-قاہروقہار: قہرسےقاہراسم فاعل ہے،قہرکامعنی غلبہ،علواور بلندی کے ہیں۔اللہ تعالی قہر اور غضب وغصے والاہےاوراسی سےقہار مبالغے کا صیغہ ہے۔ بڑے قہر اورغضب والا۔اللہ تعالی اپنے بندوں پرمکمل غلبہ رکھتاہے۔ سب اس کے قابومیں ہیں اور اس کے سامنے ذلیل وخوار۔ وہ سب پر غالب اور سب سے بلندہے۔ اللہ تعالی کے قہارہونے کا لازمی نتیجہ ہے کہ وہ اپنی حیات،عزت، قدرت اور جاہ وجلال میں کامل مکمل اور فائق ترہو۔وہ زندہ وجاویدہے۔غالب اور قادرمطلق ہے، سب اس کے سامنے عاجز اور وہ سب کا ملجا وماوی۔(قاہر:سورہ الانعام: ۱۸، ۶۱، قہار: الرعد: ۱۷)\n۵۲-قدوس: قدس سےمبالغے کا صیغہ ہے۔ذات باری تعالی ہرعیب اور ہرنقص اور کمی سے مبرا، کامل اور قابل تعریف صفات والاہے۔(سورہ الجمعہ: ۱)\n۵۳-قریب: کائنات کی ہرچیزاللہ تعالی کےعلم میں ہے،اس کا علم ہرچیزکو محیط ہے۔،یہ قرب عام ہے۔قرب خاص یہ ہےکہ اللہ تعالی کو جو پکارتاہےوہ اس سے قریب ہوتا ہے۔وہ اپنے عبادت گزار بندوں اورسائلوں کےقریب ہے۔اس کی اس نزدیکی اور قربت کی حقیقت کا ادراک نہیں ہوسکتا، لیکن نیک بندوں پراس کے جو الطاف وعنایات ہیں اور اس کو جو توفیق الٰہی حاصل ہے اس سے اس قرب خاص کو جاناجاسکتاہے۔(سورہ ہود: ۶۱، سبا: ۵۰)\n۵۴-قوی: مبالغے کا صیغہ ہے۔جس کے معنی طاقت وقوت اور شدت کے ہیں، جو ضعف وکمزوری کے نقیض ہے۔اللہ تعالی کوہرچیزپرکامل قدرت اور غلبہ حاصل ہے۔اس پر کمزوری کبھی غالب نہیں آسکتی۔اس کو مکمل طور پر قدرت اور قوت حاصل ہے۔ساری کائنات پر اس کا تصرف ہے۔جوکچھ ہوتا ہے صرف اس کی مرضی اور مشیت سے ہوتا ہے۔ (سورہ الذاریات: ۵۸، الشوری:۱۹)\n۵۵-قیوم:قیوم، قیام اورقیم سب ہم معنی ہیں،قائم رہنے اورقائم رکھنے والا،سنبھالنے والا،مخلوق کے ہرطرح کےرزق اورمشکلات کی دیکھ بھال کرنے والا،اپنی قدرت کاملہ سےکائنات کی تدبیروانتظام کرنے والا۔(سورہ البقرۃ: ۲۵۵)\n۵۶-کبیر: مبالغے کاصیغہ ہے۔ اللہ تعالی سب سے بڑاہے۔ اس کی کبریائی اورعظمت کائنات پر محیط ہے۔ (سورہ الرعد: ۹)\n۵۷-کریم: کرم سےمبالغے کا صیغہ ہے۔بڑےکرم والا۔ذات باری تعالی سارے اوصاف وکمالات والاہے اوراپنی صفات حسنہ اور افعال میں بزرگ وبرترہے۔(سورہ الانفطار:۶)\n۵۸-لطیف: لطف سے مبالغے کا صیغہ ہے۔اللہ تعالی بندوں کے ساتھ بہت زیادہ لطف واحسان فرمانے والااور ان کے مصالح و مفادات کے لیے ایسے اسباب ووسائل فراہم کرنے والا ہے، جو ان کے گمان میں بھی نہیں ہوتے۔اللہ تعالی کا لطف اور اس کی مہربانی سب کو شامل ہے۔ اللہ تعالی بندے کو اپنے عالی مقام ومرتبے تک پہنچانے کی راہ آسان فرماتا ہے اور لوگوں کو تنگیوں سے باہر نکالتا ہے۔ اللہ تعالی کےلطف کے وصف کے ساتھ متصف ہونے کا مطلب یہ بھی ہے کہ اس پر کوئی چیز مخفی نہیں ہے۔ وہ ہر مخفی چیز سے واقف اور ہر طرح کے اسرار ورموز سے آگاہ ہے۔(سورہ الملک: ۱۴)\n۵۹-مبین: أبان یبین سے اسم فاعل کا صیغہ ہے۔ظاہرکرنے اور بیان کرنے والا۔اللہ تعالی اپنے بندوں کو سیدھی راہ دکھاتا اور اجروثواب والے اعمال کی طرف رہنمائی کرتاہےاوران چیزوں سے ڈراتاہےجوبندے کے حق میں موجب عقاب ہوں۔(سورہ النور: ۲۵)\n۶۰-متعالی: یہ تعالی یتعالی سے اسم فاعل ہے۔اس کا لفظی معنی بلندوبالاہونا ہے۔اللہ تعالی کو مطلق علو اوربلندی حاصل ہے۔ وہ اپنی قدرت کاملہ سے ساری مخلوقات پرغالب ہےاورمخلوق کی صفات سے مبرا اور پاک ہے۔(سورہ الرعد: ۹)\n۶۱-متکبر: تکبرغروراور گھمنڈ کو کہتے ہیں۔بڑائی والا،تکبریعنی فخرومباہات اور گھمنڈ انسان کی قابل مذمت صفت ہے۔ جب کہ اللہ رب العزت کی شایان شان بزرگی، بڑائی اور کبریائی اپنی مثال آپ ہے۔ اللہ تعالی اپنی ربوبیت اور قدرت کی صفات سے متصف ہونے کی وجہ سے سب سے بڑا ہے۔ اس کےمثل کوئی چیزنہیں ہے۔ وہ ہرعیب ونقص اور قابل مذمت چیزسے مبرا اور پاک ہے۔ اس کی عظمت وکبریائی ہر طرح کے عیب اوربرائی سے پاک ہے۔ (سورہ الحشر: ۲۳)\n۶۲-متین: بہت قوی اورمضبوط، جس کی طاقت وقوت دائمی اور لازوال ہے۔اللہ تعالی کو اپنے افعال میں کسی طرح کی مشقت یا کمزوری نہیں لاحق ہوتی۔ وہ عظیم اقتدار کامالک ہے۔ (سورہ الذاریات: ۵۸)\n۶۳-مجیب: جواب اورمجابہ کے لغوی معنی کلام کی مراجعت کےہیں۔اللہ تعالی مجبور اور بے کس کی دعا کو قبول فرمانے والاہے۔ وہ پکارنے اور سوال کرنے والوں کی مددکرتا اور دعا کرنے والوں کی دعاؤں کو سنتااور قبول فرماتاہے۔بل کہ سوال کرنے اور مانگنے سے پہلے ہی بے بس اورمجبور کی حاجت پوری کرتا ہے۔(سورہ ہود: ۶۱)\n۶۴-مجید: بزرگی والا، کرم اورجاہ وجلال میں وسعت کو مجدکہتے ہیں۔ مجید صفت کمال ہے۔ اللہ تعالی شرف ومجد والا اور مدح وثناکے لائق ہے۔ وہ اپنی بڑائی اور بزرگی میں درجۂ کمال کو پہنچاہواہے۔ (سورہ البروج:۱۵، ہود: ۷۳)\n۶۵-محیط: احاطہ کرنے والا۔ اللہ تعالی کائنات اور اس میں پائی جانے والی ہر چھوٹی بڑی مخلوق کو اپنے علم اور قدرت کے احاطے میں لیے ہوے ہے۔(سورہ ہود: ۹۲)\n۶۶-مصور: صورت بنانےوالا، تصویر کےمعنی مخلوق کی پیدایش کی ہیئت وشکل بنانے کے ہیں۔یہ صورت گری اللہ تعالی کے خصائص میں سے ہے۔اس لیے مجسمہ سازی اور صورت گری کو حرام قرار دیا گیا ہے۔اللہ تعالی مخلوقات کو پیدا کرنے اور ان کی صورت گری کرنے پھر اس میں روح ڈالنے والا ہے۔مخَلوق اس پر قادرنہیں ہے۔ اللہ تعالی جس طرح چاہتا ہے مخلوقات کی صورت گری کرتا اور انھیں وجود بخشتاہے۔خالق، باری اور مصور تقریباً ہم معنی اوصاف ہیں۔ خالق کا مطلب یہ ہے کہ اللہ تعالی ساری مخلوقات کوعدم سے وجود بخشنے والاہے۔ باری کا مطلب یہ ہے کہ اللہ تعالی لوگوں کو مٹی سے پیداکرنے والا ہے۔مصور کا مطلب یہ ہے کہ اللہ تعالی مختلف انداز کی صورت گری کرنے والا ہے۔خالق عام وصف ہے، اس سے خاص باری ہے اور مصور خاص الخاص ہے۔(سورہ الحشر: ۲۴)\n۶۷-مقتدر: اقتدار سے اسم فاعل کا صیغہ ہے۔ اللہ تعالی بڑی قدرت اور طاقت والا ہے۔وہ اپنے اقتدار اور حکومت میں اتنا قوی ہے کہ ہرچیز اس کے سامنے ہیچ اور بے حقیقت ہے۔ (سورہ القمر: ۵۵)\n۶۸- مقیت: مفعل کے وزن پر اسم فاعل ہے۔اس کامطلب قدیرکے ہے یعنی قدرت والا۔اس کا ایک مطلب حافظ، حفیظ اورشہید کے ہے۔اللہ تعالی ہرچیز کامنتظم اور مدبرہے۔یہ بھی کہا گیا ہےکہ اس کا مطلب روزی دینےوالے کے بھی ہیں،جو ساری مخلوقات کو روزی پہنچاتااوراپنی حکمت اور مرضی کے مطابق جس کو جوچاہتاہےعطاکرتا ہے۔(سورہ النساء: ۸۵)\n۶۹، ۷۰- ملک اورملیک: ملک کے معنی ہیں کسی چیز میں قوت اورصحت ہونے کے۔اللہ تعالی مالک، بادشاہ اور حاکم ہے۔وہ ملک الملوک یعنی شہنشاہوں کا شہنشاہ ہے وہ احکم الحاکمین ہے۔ اللہ تعالی روزِ جزا کا مالک اور ساری مخلوقات کا رب اور پالنہار ہے وہ بندوں کا تنہا بااختیارمالک ہے۔ سب اس کے غلام ہیں۔ وہ کائنات میں پورے طور پر تصرف فرمانے اور سب کے احوال کی نگرانی کرنے والا ہے۔ ہر چیز میں اس کی قدرت کاملہ کانفاذ ہے۔(ملک: سورہ الجمعہ: ۱،ملیک:القمر: ۵۵)\n۷۱-مہیمن: ہیمنہ سے مہیمن ہے۔کسی چیز کی حفاظت ونگرانی اورسرپرستی کو ہیمنہ کہتے ہیں۔ مہیمن کےمعنی شہیدکے ہیں۔اللہ تعالی ساری کائنات کانگہبان اورسب کاسرپرست ہے۔اس کا ایک معنی امین بھی ہے۔یعنی اللہ تعالی نے دوسرے کو خوف سے مامون ومحفوظ کردیاہے۔(سورہ الحشر: ۲۳)\n۷۲-مولی: مولی کامطلب ولی،دوست اورمددگار۔ہرچیزکامتولی اورمنتظم۔اہل ایمان کامعین ومددگار۔(سورہ الحج: ۷۸)\n۷۳-مومن: ایمان سےمشتق ہے،اس کا مطلب تصدیق ہے۔دوسرا معنی یہ ہے کہ ایسا امن وامان جو خوف ودہشت سے خالی ہو۔مطلب یہ ہے کہ بندے اللہ تعالی کےظلم سےمحفوظ رہیں گے۔ اللہ تعالی اپنے مومن بندوں کی تصدیق فرماتاہے۔انبیاورسل کی وحی کی تبلیغ میں اللہ تعالی ان کے سچ ہونے کی گواہی دیتا اوران کے صدق پر متنوع دلائل فراہم کرتاہے۔ (سورہ الحشر: ۲۳)\n۷۴-نصیر: نصر سےمبالغے کاصیغہ ہے۔اللہ تعالی دشمنوں کے مقابلے میں اہل ایمان کی مددکرنے والاہے۔ (سورہ الحج: ۷۸)\n۷۵-واحد: فرد، فرید، تنہا،اکیلا،بے نظیر،بے مثال اور لاثانی۔ اللہ تعالی اپنے اسماءوصفات اوراپنے افعال اور الوہیت وعبادت میں منفرداور بے مثال ہے۔(سورہ الرعد: ۱۶)\n۷۶-وارث: اللہ تعالی کی ذات لازوال اورباقی رہنے والی ہے۔ مخلوق کے فناہوجانے کے بعد آسمان وزمین کا وہی وارث ہوگا۔ (سورہ الحجر: ۲۳)\n۷۷-واسع: کشادگی اور وسعت والا۔ وسعت کے معنی مالداری، طاقت اوررفاہیت کے ہیں۔ اللہ تعالی کا فضل واحسان اور اس کا جود وکرم سب کو شامل ہے۔ وہ اپنے علم، حلم، حکمت، رحمت، جودوسخا، فضل واحسان اور بھلائی میں بڑا وسعت والا ہے۔(سورہ البقرۃ: ۱۱۵)\n۷۸-ودود: ود یود سےمبالغے کا صیغہ ہے۔بہت چاہنے والا۔ اللہ تعالی ان لوگوں سے بڑی محبت کرتا ہے، جو اس سے محبت کرتے اور اس کی طرف رجوع کرتے ہیں۔ وہ توبہ کرنے والوں کے گناہوں کو بخشتاہے۔اپنے انبیاورسل اور اولیاوصالحین سے شدیدمحبت فرماتاہے۔(سورہ ہود: ۹۰، البروج: ۱۴)\n۷۹-وکیل: فعیل کے وزن پرمبالغے کاصیغہ ہے۔ اللہ تعالی بندوں کے رزق کا کفیل اور ان کے مصالح ومفادات کا نگراں ہے۔وہی اپنےنیک بندوں کا ماوی وملجاہے، جو انھیں ہرطرح کی نعمت عطافرمانے والاہے۔ (سورہ الزمر: ۶۲)\n۸۰-ولی: ولی،اسم فاعل والی سے مبالغے کا صیغہ ہے،جو مولی اورمتولی کے معنی میں ہے۔ اللہ تعالی اپنے بندوں کا والی وناصراور مددگارہے۔ (سورہ الشوری: ۹، ۲۸)\n۸۱-وہاب: مبالغے کا صیغہ ہے۔ مطلب یہ ہے کہ اللہ تعالی بہت دینے اور ہبہ کرنے والا ہے۔وہ سب سے بڑا داتااور سب کو عطاکرنے والا ہے۔دنیاوی مال ومتاع کے علاوہ توفیق، سلامت روی اورحق پر ثابت قدمی، کتاب اوررسولوں پر ایمان کی توفیق دینے والاہے۔یہ سب کچھ اس کے فضل ورحمت اور کرم کا نتیجہ ہے۔ کسی کا اس میں حق اور دعوی نہیں ہے۔اللہ تعالی نے جب سے کائنات کو وجود بخشاہے اس کی بخشش اور ہبہ کا دروازہ سب کے لیے کھلاہے۔(سورہ آل عمران: ۸)\nمذکور بالا یہ سارے نام قرآن مجیدمیں مذکورہیں اوربقیہ نام احادیث نبویہ سے ثابت ہیں،جو درج ذیل ہیں:\n۸۲-جمیل: مبالغےکاصیغہ ہے۔یہ نام مبارک صحیح حدیث میں آیاہے: «إِنَّ اللهَ جَمِيلٌ يُحِبُّ الجَمَالَ» \"اللہ تعالی خوبصورت ہے اورخوبصورتی کو پسندکرتاہے\" (صحیح مسلم بروایت عبداللہ بن مسعود) جمیل جمال سے مبالغے کا صیغہ ہے۔ اللہ تعالی اپنی ذات اور اپنے اسماءوصفات اور افعال میں جمیل اور خوبصورت ہے۔ مخلوق اس کےحسن وجمال کے اوصاف بیان کرنے سے عاجز ہے۔\n۸۳-جَوَاد: یہ نام مبارک صحیح حدیث میں آیاہے: «إِنَّ اللهَ تعالی جَوَادٌ يُحِبُّ الجُودَ» \"اللہ تعالی سخی ہے اور سخاوت کو پسندکرتا ہے\" (مستدرک الحاکم: ۱/۴۸)۔جودوسخاوالا۔ اللہ تعالی بہت زیادہ عطا کرنے والا ہے۔ جود وسخا کوپسندفرماتاہے۔اس کے جودوسخا کی بارش ساری کائنات پر ہے۔ اس کافضل وکرم اور احسان عام ہے۔وہ مسلم وکافر،نیک وبدسب کو دیتا اور ہاتھ پھیلانے والوں کو خالی ہاتھ نہیں جاننے دیتا۔روزآخرت اس کے خصوصی جود وسخا اورانعام واکرام کے مستحق اس کے نیک بندے ہوں گے۔\n۸۴-حکم: یہ مبالغے کا صیغہ ہے اوریہ مبارک نام اس صحیح حدیث میں آیاہے: «إِنَّ اللهَ هُوَ الحَکَمُ، وإِلَيْهِ الحُکْمُ»\"اللہ تعالی فیصلہ کرنے والاہےاورفیصلہ اُسی کی طرف لوٹتاہے\" (سنن ابی داود: ۴۹۵۵) فیصلہ صرف اللہ تعالی کے ہاتھ میں ہے۔ وہ جیساچاہتاہےفیصلہ کرتا ہے۔وہ دنیااورآخرت میں بندوں کےدرمیان فیصلہ کرنے والاہے۔ اس کا حکم سب پر چلنے والاہے۔ ساری کائنات اللہ تعالی کی حکمرانی کے تابع ہے۔\n۸۵-حیی: یہ فعیل کے وزن پرحیاسے مشتق مبالغے کا صیغہ ہے۔یہ مبارک نام اس صحیح حدیث میں آیاہے: «إِنَّ اللَّهَ عَزَّ وَجَلَّ حَيِيٌّ سَتِيرٌ يُحِبُّ الْحَيَاءَ وَالسِّتْرَ» \"اللہ تعالی بڑاحیاکرنے والا اور پردہ پوشی کرنے والا ہے وہ شرم حیااور پردہ پوشی کوکرتاہے\"(سنن ابی داود: ۴۰۱۲ وسنن النسائی: ۴۰۶)۔حیی اللہ تعالی کی صفت ہے۔اللہ تعالی اپنے بندوں سے شرم کرتاہےکہ وہ ہاتھ اٹھائیں تووہ انھیں خالی جانے دے۔ وہ اپنے بندوں کی فضیحت ورسوائی اور ان کے عیوب کے ظاہر کرنے میں بہت زیادہ شرماتاہے۔حیامومن کی صفت ہے۔لیکن اللہ تعالی کے شایان شان حیا کو مخلوق کی حیاسے تشبیہ نہیں دی جاسکتی۔\n۸۶-رب: پروردگار، پالنے والا، مالک۔ رب کامصدرربوبیت ہے۔ رب کے لفظ میں کسی چیز کی اصلاح، نگرانی اوراہتمام داخل ہے۔ رب کے لفظ کااطلاق بغیرکسی اضافت کے صرف اللہ تعالی کے لیے خاص ہے۔ربوبیت کی خاص ترین صفت تخلیق (پیدا کرنے) اور اندازہ کرنے کا عمل ہے۔اللہ تعالی کی ربوبیت ساری مخلوقات کو عام ہے۔ وہ رب السماوات والارض اور رب العالمین ہے۔وہی آسمان وزمین اور پوری کائنات کاخالق ومالک ہے۔ سب پرمطلق قادر ہے۔ اس ربوبیت سے باہر کوئی چیز نہیں۔ ساری مخلوق اس کے قبضۂ قدرت واختیارمیں ہے۔ قرآن مجید میں اللہ تعالی نے اپنے لیے رب کا لفظ بکثرت استعمال فرمایاہے۔ (سورہ الفاتحہ)\n۸۷-رفیق: رفق سے مبالغےکا صیغہ ہے۔ رفق سختی اور تشدد کے نقیض ہے۔رفق کا مطلب نرمی اور آسانی پیدا کرنے کے ہیں۔یہ مبارک نام صحیح حدیث میں آیاہے : «إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ» \"اللہ تعالی نرمی والا ہے اور نرمی کو پسندکرتاہے\" (صحیح البخاری: ۶۳۹۵)۔اللہ تعالی بہت زیادہ نرمی اورآسانی پیدا کرنے والا ہے۔ وہی خیراوربھلائی کے سارے اسباب پیدا کرنے اوراسے دینے والا ہے۔\n۸۸-سبوح: یہ مبارک نام اس صحیح حدیث میں آیاہے: «إِنَّ النَّبِيَّ صلی اللہ علیہ وسلم کَانَ يَقُولُ فِي رُکُوعِهِ وَسُجُودِهِ: سُبُّوحٌ قُدُّوسٌ، رَبُّ الْمَلائِکَةِ وَالرُّوحِ» \"نبی اکرم صلی اللہ علیہ وسلم رکوع اور سجود میں یہ پڑھتے تھے: ہرعیب سے پاک اور ہرنقص سے مبرا ذات،فرشتوں اورروح کے رب \" (صحیح مسلم: ۴۸۷)۔ پاکیزہ، اللہ تعالی ہرایسی چیز سے مبرا اور پاک جواس کی ذات کے لیے مناسب نہ ہو۔ وہ ہر طرح کے عیب اور نقص سے پاک ہے۔ اس کی پاکی بیان کرکے اس کی عبادت کی جاتی ہے۔ اس کی پاکیزگی بیان کرنا واجب ہے۔ زمین وآسمان کی ہر چیز اس کی تقدیس اور پاکیزگی کا گن گاتی ہے۔\n۸۹-سید: یہ مبارک نام اس حدیث میں آیاہے : «السَّيِّدُ اللَّهُ تَبَارَکَ وَتَعَالَی» \"اللہ تعالی سردار ہے\" (سنن ابی داود: ۴۸۰۶، صحیح الجامع: ۳۷۰۰)۔ سید کے معنی سردارکے ہیں۔اللہ تعالی ساری کائنات کاتنہامالک اور سردار ہے۔ سب پر غالب ہے۔ سب کا کفیل ہے۔ سب سے بڑا ہے۔ ساری مخلوق اس کے بندے اور غلام ہیں۔\n۹۰-شافی: شفاسے اسم فاعل ہے۔ یہ مبارک نام صحیح حدیث میں آیاہے: «أَذْهِبْ الْبَأْسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لا شِفَاءَ إِلا شِفَاؤُکَ شِفَاءً لا يُغَادِرُ سَقَمًا» \"لوگوں کےرب! تکلیف اور مصیبت کو دور کردے۔شفاعطافرما۔ تیرے سوا کوئی شفادینے والانہیں ہے۔ایسی شفا جس کے بعد کوئی بیماری نہ آئے\"۔(صحیح البخاری: ۵۷۴۳، صحیح مسلم: ۲۱۹۱)۔ اللہ تعالی دلوں میں پائے جانے والے ہرطرح کے شکوک وشبہات سےنجات دینے والااور ہرطرح کے جسمانی امراض سے شفادینے والاہے۔\n۹۱-طیب: یہ مبارک نام صحیح حدیث میں آیاہے: «إِنَّ اللَّهَ طَيِّبٌ لا يَقْبَلُ إِلا طَيِّبًا» (صحیح مسلم: ۱۰۱۵)۔ طیب کے لغوی معنی طہارت وپاکیزگی اور نجس اور خبیث چیز سے سلامتی کے ہیں۔اللہ تعالی سب سےاچھااور سب سے پاک،پاکیزہ اور مقدس ومطہر ہے۔وہ ہر طرح کے نقص وعیب سے مبراہے۔اس کی ذات سے صرف پاکیزہ چیزیں ہی صادرہوتی ہیں۔ اس کی طرف صرف پاکیزہ چیزیں ہی اٹھ کر جاتی ہیں۔اس کے قریب صرف پاکیزہ چیز ہوتی ہے۔ اس کا کلام پاکیزہ اور اس کی طرف جانے والا کلام پاکیزہ، اس کا کام پاکیزہ اور ہرطرح کی اچھی چیزیں اور پاکیزگی اس کی ذات کے لیے ہے۔ اور طہارت وپاکیزگی کی وہ انتہاہے۔\n۹۲، ۹۳-قابض وباسط: ارشاد باری تعالی ہے: [آیت] (البقرة: ۲۴۵) (اللہ تعالی ہی تنگی اور کشادگی کرتاہےاور تم سب اسی کی طرف لوٹائے جاؤگے) [آیت] (الإسراء: ۳۰) (یقیناًتیرا رب جس کے لیے چاہے روزی کشادہ کردیتاہے اور جس کے لیے چاہے تنگ)۔انس سے مروی حدیث میں آتاہے: «إِنَّ اللهَ هُوَ المُسَعِّرُ القَابِضُ البَاسِطُ الرَزَّاقُ» \"اللہ تعالی ہی قیمتوں کو طے کرنے والا ہےاور وہ روزی کو تنگ اور کشادہ کرنے والا ہےاور وہی رزاق یعنی سب کو روزی دینے والاہے\" (مسند احمد: ۱۴۱۰۳) قبض سےقابض اور بسط سے باسط دونوں اسم فاعل ہیں۔ قبض کا مطلب یہ ہے کہ کوئی ایسی چیز جولے لی گئی ہواور کسی چیز میں اکٹھی ہوجائے، اس میں سرعت اورجلدی کا مفہوم بھی پایا جاتاہے۔کیوں کہ آدمی جب سرعت پکڑتا ہے تو وہ اپنے دل ودماغ اور اعضاوجوارح کی طاقت کو اکٹھاکرلیتاہے۔قبض کا ایک معنی بخیلی اور تنگی کے بھی ہے۔ قبض کا مطلب جمع کرنابھی ہے۔ اس کے مقابل بسط کا لفظ ہے۔جس کے معنی عرض یاغیرعرض (چوڑائی یا غیرچوڑائی) میں پھیلاؤ کے ہیں۔ بسط کا ایک مطلب وسعت اور پھیلاؤ ہے۔ قابض وباسط کے معنی یہ ہیں کہ اللہ تعالی رزق میں تنگی اور فراخی دینے والا ہے۔ وہ اپنے جود وسخا اور رحمت ومہربانی سے رزق میں گنجایش دیتاہے اور اپنے عدل سے اس پر روک لگا دیتاہے۔قبض وبسط کی یہ کیفیت اللہ تعالی انسانوں کے دل ودماغ اور اعضا وجوارح پر بھی طاری کرتا ہے۔\n۹۴، ۹۵- مقدم،موخر: ان دونوں مبارک ناموں کا ذکردرج ذیل حدیث میں آیاہے: «اللَّهُمَّ اغْفِرْ لِي مَا قَدََّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ المُقَدِّمُ وَأَنْتَ المُؤَخِّرُ، وَأَنْتَ عَلَی کُلِِّ شَيْءٍ قَدِيرٌ» \"اللہ میرے اگلے اورپچھلے، کھلے اورچھپےگناہوں پرپردہ ڈال دےاورمجھے بخش دے۔اےاللہ توہی بلند مراتب عطا کرنے والا، ہر چیز کو اس کے اپنے مقام اور مرتبے پر رکھنے والااورہر چیز کو آگے پیچھے رکھنے والاہے\" (صحیح البخاری: ۶۳۹۸ وصحیح مسلم: ۲۷۱۹ بروایت ابوموسی اشعری )۔  «اللَّهُمَّ اغْفِرْ لِي مَا قَدََّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ المُقَدِّمُ وَأَنْتَ المُؤَخِّرُ، لاَ إلَهَ إِلاَّ أَنْتَ» \"اللہ میرے اگلے اورپچھلےاور کھلے اورچھپےگناہوں اور ان اعمال پرپردہ ڈال دےجس سےتومجھ سے زیادہ باخبرہےاورمجھے بخش دے۔اےاللہ، توہی بلند مراتب عطا کرنے والا، ہر چیز کو اس کے اپنے مقام اور مرتبے پر رکھنے والا۔ہر چیز کو آگے پیچھے رکھنے والاہے۔ توہی معبودبرحق ہے\"(سنن الترمذی: ۳۴۲۱ بروایت علی بن ابی طالب) مقدم: بلند مراتب عطا کرنے والا، ہر چیز کو اس کے اپنے مقام اور مرتبے پر رکھنے والا۔موخر: ہر چیز کو آگے پیچھے رکھنے والا، ان دونوں مبارک ناموں کامطلب یہ ہے کہ اللہ تعالی جس کو آگے کردے، اسے کوئی پیچھے کرنے والا نہیں ہے اور جسے پیچھے کردے، اسے کوئی آگے کرنے والا نہیں ہے۔\n۹۶-محسن: اللہ تعالی کے صفاتی ناموں میں سے محسن ہے۔جس کاذکرکئی احادیث میں آیا ہے۔ (مصنف عبد الرزاق: ۴/۲۹۲ والمعجم الکبیر للطبرانی ۷/۲۵۷) اللہ تعالی احسان اور بھلائی کرنے والا ہے۔مخلوقات پراس کا فضل واحسان بے حدوحساب ہے۔\n۹۷-معطی: دینے والا۔اسی سے عطیہ ہے۔اللہ تعالی نے مخلوق کو ہرچیز سے نوازا ہے۔ دنیاوآخرت میں سب کے رزق کا مالک اللہ تعالی ہے۔ (صحیح البخاری وصحیح مسلم)\n۹۸-منان: مبالغے کا صیغہ ہے۔منّ یمنّ کا مطلب قطع کرنااور کاٹناہے۔اس کا ایک معنی عطاکرنابھی ہے۔ منت کے معنی قوت کے ہیں۔ بلا کسی معاوضے اور بدلے کے عطیہ اور ہبہ کو من کہتے ہیں۔ منان کا مطلب یہ ہےکہ اللہ تعالی مخلوقات کو کسی بدلے اور معاوضے کے بغیر اپنے فضل وکرم سے بے حد وشمار نعمتوں سے مالا مال کرنےوالا ہے۔آدمی اگر ان نعمتوں اور احسانات کا ادراک کرے تو اسے معلوم ہوگا کہ رب عزوجل نےاسے کتنی بڑی بڑی نعمتوں سے نوازا ہے۔(مسنداحمد، سنن ابی داود، ابن حبان بروایت انس بن مالک)\n۹۹- وتر: یکتا،اکیلا۔ اللہ تعالی کی ذات اکیلی ہے۔ وہ بے نظیرہے۔ اس کا کوئی شریک نہیں ہے۔ وہ مخلوقات سے بالکل الگ تھلگ ہے۔ (صحیح البخاری، صحیح مسلم بروایت ابوہریرہ)\nیہ ننانوے(۹۹) نام ہیں۔ان کے علاوہ اللہ تعالی کے اور بھی اسماے گرامی ہیں، جوقرآن اور صحیح حدیثوں میں پائےجاتے ہیں۔ حدیث میں مذکور ہے کہ جو اللہ کے ان ننانوے ناموں کا ورد کرے گا، وہ جنت میں داخل ہوگا۔وردکرنے کامطلب ان کے مطابق عمل کرنا ہے۔جیسے وہ الہ (معبود)ہے تو صرف اسی کی عبادت کی جائے، وہ غفار (بخشنے والا)ہے تو صرف اسی سے معافی مانگی جائے۔ وہ علیم (جاننے والا)ہے تو صرف اسی کو غیب کاجاننے والاماناجائے۔وہ مجیب(قبول کرنے والا)ہے تو صرف اسی سے دعا مانگی جائے کہ وہی دعاقبول کرتاہے۔ وہ رزاق ( بہت رزق دینے والا)ہے تو صرف اسی سےرزق طلب کیا جائے۔ کسی پیر،فقیر،صوفی،ولی،کے ہاتھ میں رزق نہیں ہے۔ ایک حدیث میں ہے، جو تمھاری قسمت میں ہے وہ مل کر رہے گا۔اس لیے طلب کرنے میں صحیح طریقہ اختیار کرو۔\nخلاصہ کلام یہ ہے کہ اللہ تعالی کے مذکور بالا ناموں کےورد کرنے اور انھیں شمار کرنے کا مطلب یہ ہے کہ ان کوان کے معانی کے ساتھ دل ودماغ میں بٹھایااور ان کے مطابق عمل کیا جائے۔","",{}]]);
